"""Profile slide/source signal support for workbook writers.

This module owns the support/model/source-cache helpers used to extract profile
slide signals. It deliberately avoids importing the main writer context; callers
inject context-owned helpers and state through a runtime mapping.
"""
from __future__ import annotations

import hashlib
import json
import math
import os
import re
from dataclasses import dataclass
from datetime import date, datetime
from pathlib import Path
from typing import Any, Dict, Iterable, List, Mapping, MutableMapping, Optional, Pattern, Tuple

import pandas as pd


_PROFILE_SIGNAL_SUPPORT_CODE = '_preferred_narrative_source_re = re.compile(\n    r"(earnings_release|press_release|presentation|slides|transcript|ceo|shareholder|mda)",\n    re.I,\n)\n_pbi_note_theme_re = re.compile(\n    r"\\b(adjusted ebit|ebit|margin|free cash flow|fcf|deleverag|liquidity|trapped capital|"\n    r"pb bank|bank funding|cost savings?|cost rationalization|guidance|sendtech|presort|"\n    r"buyback|repurchas\\w*|authorization|capital return|remaining capacity|dividend|"\n    r"strategic review|phase 2|phase two|forecast(?:ing)?|uncertainty|operational execution|"\n    r"cost management|leverage|working capital|balance sheet|non-core asset|"\n    r"shipping|mail(?:ing| volume)?|parcel|postage)\\b",\n    re.I,\n)\n_pbi_promise_theme_re = re.compile(\n    r"\\b(adjusted ebit|ebit|eps|free cash flow|fcf|revenue|guidance|cost savings?|"\n    r"cost rationalization|deleverag|liquidity|trapped capital|pb bank|bank funding|"\n    r"sendtech|presort|shipping|mail(?:ing| volume)?|parcel|postage|milestone)\\b",\n    re.I,\n)\n_pbi_fragment_drop_re = re.compile(\n    r"\\b(would be incremental to|provided the following|table of contents|safe harbor|"\n    r"private securities litigation reform act|risk factors?|forward-looking statements|"\n    r"future revenue and profitability|future events or conditions|capital allocation strategy|"\n    r"management target\\s*$|item\\s+\\d|low\\s+high\\s+revenue|"\n    r"reconciliation of adjusted segment ebitda|total reportable segments|"\n    r"net cash from operating activities|capital expenditures|"\n    r"adjusted ebit(?:, adjusted ebitda and adjusted eps)? exclude the impact|"\n    r"adjusted ebitda and adjusted eps exclude the impact|"\n    r"previously disclosed guidance ranges|full year \\d{4} guidance\\s*$)\\b",\n    re.I,\n)\n\ndef _is_preferred_narrative_source(source_type_in: Any) -> bool:\n    src_txt = str(source_type_in or "").strip().lower()\n    if not src_txt:\n        return False\n    if shared_is_preferred_narrative_source(src_txt):\n        return True\n    return bool(_preferred_narrative_source_re.search(src_txt))\n\ndef _looks_pbi_fragment_text(text_in: Any) -> bool:\n    txt = glx_normalize_text(str(text_in or ""))\n    if not txt:\n        return True\n    if re.search(\n        r"\\b(fully operational|online and ramping|risk management supports?|utilization\\b|agreement executed|"\n        r"debt repaid|liquidity (?:improved|released)|cash release|45z|monetization|bridge|included in)\\b",\n        txt,\n        re.I,\n    ) and not shared_looks_like_tabular_fragment(txt):\n        return False\n    if _pbi_fragment_drop_re.search(txt):\n        return True\n    if _slide_signal_noise(txt):\n        return True\n    if re.search(\n        r"\\b(reconciliation of adjusted segment ebitda|total reportable segments|"\n        r"for reference[, ]+the company.?s previously disclosed guidance ranges|"\n        r"net cash from operating activities.*capital expenditures|"\n        r"full year \\d{4} guidance.*low high revenue|"\n        r"adjusted segment ebitda to income or loss from continuing operations before taxes)\\b",\n        txt,\n        re.I,\n    ):\n        return True\n    if re.search(r"^\\s*(for reference[, ]+)?full year \\d{4} guidance\\s*$", txt, re.I):\n        return True\n    if re.search(r"\\b(low|high)\\s+(revenue|adjusted ebit|adjusted eps|free cash flow)\\b", txt, re.I):\n        return True\n    if re.search(r"\\d{1,3},\\d{3}\\d{1,3},\\d{3}", txt):\n        return True\n    numeric_hits = len(re.findall(r"\\$?\\s*\\d[\\d,]*(?:\\.\\d+)?\\s*(?:%|m|mm|x|million|billion)?", txt, re.I))\n    table_metric_hits = len(re.findall(r"\\b(revenue|adjusted ebit|adjusted eps|free cash flow|presort services|sendtech solutions)\\b", txt, re.I))\n    if numeric_hits >= 4 and table_metric_hits >= 2 and not re.search(r"\\b(bridge|included in|45z|monetization)\\b", txt, re.I):\n        return True\n    if numeric_hits >= 5 and len(re.findall(r"[.;:]", txt)) <= 1 and not re.search(r"\\b(bridge|included in|45z|monetization)\\b", txt, re.I):\n        return True\n    if len(txt) < 40 and not re.search(r"\\b(sendtech|presort|ebit|fcf|liquidity|pb bank|york|utilization|risk management|45z|bridge)\\b", txt, re.I):\n        return True\n    return bool(_text_fragment_penalty(txt) >= 2 and not re.search(r"\\b(target|guidance|margin|ebit|fcf|liquidity|presort|sendtech|york|utilization|bridge|45z)\\b", txt, re.I))\n\ndef _is_pbi_clean_sentence(text_in: Any) -> bool:\n    txt = glx_normalize_text(str(text_in or ""))\n    if not txt or _looks_pbi_fragment_text(txt):\n        return False\n    if re.search(\n        r"\\b(fully operational|online and ramping|risk management supports?|utilization\\b|agreement executed|"\n        r"debt repaid|liquidity (?:improved|released)|cash release|45z|monetization|bridge|included in)\\b",\n        txt,\n        re.I,\n    ) and 3 <= len(re.findall(r"\\b\\w+\\b", txt)) <= 18:\n        return True\n    if txt[:1].islower():\n        return False\n    if re.search(r"^\\s*(of|date|complete)\\b", txt, re.I):\n        return False\n    if txt.count("???") >= 1 or txt.count("???") >= 1:\n        return False\n    word_count = len(re.findall(r"\\b\\w+\\b", txt))\n    if word_count < 7 or word_count > 48:\n        return False\n    if not re.search(\n        r"\\b(expect|expects|guidance|improved|improvement|increased|increase|grew|growth|"\n        r"expanded|expansion|reduced|reduction|generated|achieved|delivered|support|supports|"\n        r"driven|drives|raised|lowered|reaffirmed|tightened|operational|ramping|executed|"\n        r"repurchased|repurchase|bought|purchased|paid)\\b",\n        txt,\n        re.I,\n    ):\n        return False\n    if re.search(r"\\b(low\\s+high\\s+revenue|adjusted segment ebitda to income|table of contents)\\b", txt, re.I):\n        return False\n    if re.search(\n        r"\\b(net cash from operating activities|capital expenditures|reconciliation of adjusted segment ebitda|"\n        r"for reference[, ]+the company.?s previously disclosed guidance ranges)\\b",\n        txt,\n        re.I,\n    ):\n        return False\n    if len(txt) > 110 and not re.search(r"[.;:]", txt):\n        return False\n    if len(re.findall(r"\\$?\\s*\\d[\\d,]*(?:\\.\\d+)?", txt)) >= 5 and len(re.findall(r"[.;:]", txt)) <= 1:\n        return False\n    return True\n\ndef _pbi_target_display_ok(text_in: Any) -> bool:\n    txt = str(text_in or "").strip()\n    if not txt:\n        return False\n    if len(txt) > 90:\n        return False\n    if re.fullmatch(\n        r"(?:>=|<=|>|<)?\\s*\\$?\\s*[\\d,.]+(?:\\.\\d+)?\\s*(?:m|mm|million|b|bn|billion|%)?"\n        r"(?:\\s*(?:to|-|–|—)\\s*\\$?\\s*[\\d,.]+(?:\\.\\d+)?\\s*(?:m|mm|million|b|bn|billion|%)?)?"\n        r"(?:\\s+(?:annualized savings|annualised savings|bank-held leases|cash optimization|leverage|revenue|adjusted ebit|adjusted eps|free cash flow))?",\n        txt,\n        re.I,\n    ):\n        return True\n    if _looks_pbi_fragment_text(txt):\n        return False\n    return bool(\n        re.search(\n            r"(\\$|>=|<=| to |-|–|—|annualized|fy\\s*20\\d{2}|q[1-4]\\s*20\\d{2}|full[- ]?year)",\n            txt,\n            re.I,\n        )\n    )\n\ndef _classify_pbi_metric_label(text_in: Any, fallback: str = "") -> str:\n    txt = glx_normalize_text(str(text_in or ""))\n    low = txt.lower()\n    fallback_clean = str(fallback or "").strip()\n    fallback_low = fallback_clean.lower()\n    forwardish = bool(\n        re.search(\n            r"\\b(guidance|target|targets|outlook|expects?|expected|reaffirm|updated|raised|tightened|lowered|"\n            r"full[- ]?year|fy\\s*20\\d{2}|will|aims? to|plans? to|continue to|tracking)\\b",\n            low,\n            re.I,\n        )\n    )\n    if not txt:\n        return fallback\n    if fallback_clean and fallback_low not in {"", "management target", "strategic milestone", "tone | corporate"}:\n        if fallback_low in {\n            "adjusted ebit guidance",\n            "adjusted ebit / margin",\n            "cost savings target",\n            "cost savings / rationalization",\n            "deleveraging / liquidity",\n            "deleveraging target",\n            "eps guidance",\n            "fcf improvement",\n            "fcf target",\n            "pb bank liquidity release",\n            "revenue / volume",\n            "revenue guidance",\n            "sendtech / presort operating driver",\n            "sendtech / presort operating target",\n            "strategic milestone",\n        }:\n            return fallback_clean\n    if re.search(r"\\bcost (?:savings?|rationalization|takeout|actions?)\\b", low, re.I):\n        return "Cost savings target" if forwardish else "Cost savings / rationalization"\n    if re.search(r"\\beps\\b", low, re.I):\n        return "EPS guidance"\n    if re.search(r"\\bfree cash flow\\b|\\bfcf\\b", low, re.I):\n        return "FCF target" if forwardish else "FCF improvement"\n    if re.search(r"\\b(adjusted ebit|ebit)\\b", low, re.I):\n        return "Adjusted EBIT guidance" if forwardish else "Adjusted EBIT / margin"\n    if re.search(r"\\brevenue\\b", low, re.I):\n        return "Revenue guidance" if forwardish else "Revenue / volume"\n    if re.search(r"\\bdeleverag|net debt|leverage|revolv(?:er)?|credit agreement|refinanc|term loan|notes due|redeemed the remaining outstanding balance|principal debt\\b", low, re.I):\n        return "Deleveraging target" if forwardish else "Deleveraging / liquidity"\n    if re.search(r"\\b(pb bank|trapped capital|bank liquidity|funding release|release liquidity|bank funding)\\b", low, re.I):\n        return "PB Bank liquidity release"\n    if re.search(r"\\b(repurchas\\w*|buyback|share repurchase|authorization|remaining capacity|capital return|share count reduced|shares outstanding reduced)\\b", low, re.I):\n        return "Capital allocation / buyback"\n    if re.search(r"\\b(sendtech|presort|shipping|mail(?:ing| volume)?|parcel|postage)\\b", low, re.I):\n        return "SendTech / Presort operating target" if forwardish else "SendTech / Presort operating driver"\n    if re.search(r"\\b(completed|complete|launch|migrate|exit|shut(?:down)?|sell|sale|separate|wind-?down)\\b", low, re.I):\n        return "Strategic milestone"\n    return fallback\n\ndef _extract_pbi_guidance_targets_multi(\n    text_in: Any,\n    metric_hint: str = "",\n    qd_hint: Optional[date] = None,\n) -> List[Dict[str, Any]]:\n    txt = glx_normalize_text(str(text_in or ""))\n    if not txt:\n        return []\n    txt = txt.replace("—", "-").replace("–", "-")\n    txt = re.sub(r"\\bQ[1-4]\\s+20\\d{2}\\s+Earnings(?:\\s+Conference\\s+Call)?\\b.*$", "", txt, flags=re.I)\n    txt = re.sub(r"\\bPitney Bowes\\b\\s*\\|?\\s*Q[1-4].*$", "", txt, flags=re.I)\n    txt = re.sub(r"\\*\\*\\*As a reminder.*$", "", txt, flags=re.I)\n    txt = re.sub(r"\\s+", " ", txt).strip(" |-")\n    if not txt:\n        return []\n\n    metric_hint_label = _classify_pbi_metric_label(metric_hint, metric_hint)\n    implied_money_units = bool(re.search(r"\\$\\s*millions?,\\s*except\\s*eps", txt, re.I))\n    results: List[Dict[str, Any]] = []\n    seen: set[Tuple[str, str]] = set()\n\n    metric_patterns: List[Tuple[str, str]] = [\n        ("Revenue guidance", r"\\brevenue\\b"),\n        ("Adjusted EBIT guidance", r"\\badjusted ebit\\b"),\n        ("EPS guidance", r"\\badjusted eps\\b|\\beps\\b"),\n        ("FCF target", r"\\bfree cash flow\\b|\\bfcf\\b"),\n        ("Cost savings target", r"\\bcost savings?\\b|\\bannualized savings\\b|\\bsavings target\\b"),\n        ("Deleveraging target", r"\\bdeleverag|net debt to adjusted ebitda|net debt to ebitda|leverage ratio\\b"),\n        ("PB Bank liquidity release", r"\\b(pb bank|trapped capital|bank liquidity|funding release|bank funding)\\b"),\n    ]\n    metric_hits: List[Tuple[int, str, re.Match[str]]] = []\n    for label, pat in metric_patterns:\n        for m_metric in re.finditer(pat, txt, re.I):\n            metric_hits.append((m_metric.start(), label, m_metric))\n    metric_hits.sort(key=lambda x: (x[0], x[1]))\n\n    def _money_value(val_in: float, unit_hint: str = "", label_hint: str = "") -> float:\n        unit_low = str(unit_hint or "").strip().lower()\n        if unit_low.startswith("b"):\n            return float(val_in) * 1000.0\n        if unit_low in {"million", "m", "mm"}:\n            return float(val_in)\n        if implied_money_units and "eps" not in str(label_hint or "").lower():\n            return float(val_in)\n        if abs(float(val_in)) >= 100.0 and "eps" not in str(label_hint or "").lower():\n            return float(val_in)\n        return float(val_in)\n\n    def _fmt_target(label: str, lo: Optional[float] = None, hi: Optional[float] = None, *,\n                    unit_lo: str = "", unit_hi: str = "") -> str:\n        label_low = str(label or "").lower()\n        is_eps = "eps" in label_low\n        is_money = not is_eps and label_low not in {"deleveraging target"}\n        if lo is None:\n            return ""\n        if hi is not None:\n            if is_eps:\n                return f"${float(lo):.2f}-${float(hi):.2f}"\n            if is_money:\n                lo_v = _money_value(lo, unit_lo, label)\n                hi_v = _money_value(hi, unit_hi or unit_lo, label)\n                return f"${lo_v:,.1f}m-${hi_v:,.1f}m".replace(".0m", "m")\n            return f"{float(lo):.1f}-{float(hi):.1f}"\n        if is_eps:\n            return f"${float(lo):.2f}"\n        if is_money:\n            lo_v = _money_value(lo, unit_lo, label)\n            return f"${lo_v:,.1f}m".replace(".0m", "m")\n        return f"{float(lo):.1f}"\n\n    def _extract_numeric_target_from_segment(seg: str, label: str) -> str:\n        seg = str(seg or "").strip()\n        if not seg:\n            return ""\n        label_low = str(label or "").lower()\n        if label_low == "deleveraging target":\n            m_lev = re.search(r"(~|approximately|approx\\.?\\s*)?\\s*(\\d(?:\\.\\d+)?)\\s*x", seg, re.I)\n            if m_lev:\n                lev = coerce_number(m_lev.group(2))\n                if lev is not None:\n                    return f"{lev:.1f}x leverage"\n            return ""\n\n        money_or_eps_ranges = re.findall(\n            r"\\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s*(billion|bn|million|m|mm)?\\s*(?:range)?\\s*"\n            r"(?:to|-)\\s*\\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s*(billion|bn|million|m|mm)?",\n            seg,\n            re.I,\n        )\n        if money_or_eps_ranges:\n            lo_s, unit_lo, hi_s, unit_hi = money_or_eps_ranges[-1]\n            lo = coerce_number(lo_s)\n            hi = coerce_number(hi_s)\n            if lo is not None and hi is not None:\n                return _fmt_target(label, lo, hi, unit_lo=unit_lo or "", unit_hi=unit_hi or "")\n\n        if implied_money_units and "eps" not in label_low:\n            table_pair = re.findall(r"\\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s+\\$?\\s*([\\d,]+(?:\\.\\d+)?)", seg)\n            if table_pair:\n                lo = coerce_number(table_pair[-1][0])\n                hi = coerce_number(table_pair[-1][1])\n                if lo is not None and hi is not None:\n                    return _fmt_target(label, lo, hi, unit_lo="m", unit_hi="m")\n\n        if "cost savings" in label_low:\n            m_exceed = re.search(\n                r"(?:exceed|target(?:ing)?|up from|to)\\s+\\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s*(million|m)?\\s*(?:to|-)\\s*"\n                r"\\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s*(million|m)?",\n                seg,\n                re.I,\n            )\n            if m_exceed:\n                lo = coerce_number(m_exceed.group(1))\n                hi = coerce_number(m_exceed.group(3))\n                if lo is not None and hi is not None:\n                    return _fmt_target(label, lo, hi, unit_lo=m_exceed.group(2) or "m", unit_hi=m_exceed.group(4) or "m")\n\n        if "pb bank" in label_low:\n            m_money = re.search(r"\\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s*(billion|bn|million|m|mm)", seg, re.I)\n            if m_money:\n                val = coerce_number(m_money.group(1))\n                if val is not None:\n                    return _fmt_target(label, val, unit_lo=m_money.group(2) or "")\n        return ""\n\n    def _extract_period_norm(seg: str, qd_hint: Optional[date]) -> Tuple[str, str]:\n        m_fy = re.search(r"\\b(?:fy|fiscal year)\\s*(20\\d{2})\\b|\\b(20\\d{2})\\s+full[- ]?year\\b", seg, re.I)\n        if m_fy:\n            year_txt = m_fy.group(1) or m_fy.group(2)\n            if year_txt:\n                return (f"FY{year_txt}", f"FY {year_txt}")\n        if re.search(r"\\bfull[- ]?year\\b", seg, re.I) and isinstance(qd_hint, date):\n            return (f"FY{qd_hint.year}", f"FY {qd_hint.year}")\n        m_q = re.search(r"\\bQ([1-4])\\s*(20\\d{2})\\b|\\b(20\\d{2})\\s*Q([1-4])\\b", seg, re.I)\n        if m_q:\n            year_txt = m_q.group(2) or m_q.group(3)\n            q_txt = m_q.group(1) or m_q.group(4)\n            if year_txt and q_txt:\n                return (f"Q{year_txt}Q{q_txt}", f"Q{q_txt} {year_txt}")\n        return ("", "")\n\n    def _add_result(label: str, target: str, seg: str, qd_hint: Optional[date], priority: int = 0) -> None:\n        if label == "Revenue guidance" and not _pbi_target_display_ok(target):\n            # Allow clean non-numeric revenue phrasing only for obvious guidance sentences.\n            t_low = str(target or "").lower()\n            if not re.search(r"\\b(low|mid|high)[- ]single[- ]digit\\b", t_low, re.I):\n                return\n        elif not _pbi_target_display_ok(target):\n            return\n        key = (label.lower(), str(target).strip().lower())\n        if key in seen:\n            return\n        period_norm, period_label = _extract_period_norm(seg, qd_hint)\n        results.append(\n            {\n                "label": label,\n                "target": str(target).strip(),\n                "priority": int(priority),\n                "period_norm": period_norm,\n                "period_label": period_label,\n            }\n        )\n        seen.add(key)\n\n    for idx, (start_idx, label, m_metric) in enumerate(metric_hits):\n        end_idx = metric_hits[idx + 1][0] if idx + 1 < len(metric_hits) else len(txt)\n        seg = txt[start_idx:end_idx].strip(" .|")\n        if not seg:\n            continue\n        target = _extract_numeric_target_from_segment(seg, label)\n        if not target and label == "Revenue guidance":\n            m_decline = re.search(r"\\b(low|mid|high)[- ]single[- ]digit\\s+(decline|growth|increase)\\b", seg, re.I)\n            if m_decline:\n                target = f"{m_decline.group(1).lower()}-single-digit {m_decline.group(2).lower()}"\n        priority = 0 if metric_hint_label == label else 1\n        _add_result(label, target, seg, qd_hint, priority=priority)\n\n    if not results and metric_hint_label:\n        fallback_target = _extract_numeric_target_from_segment(txt, metric_hint_label)\n        if fallback_target:\n            _add_result(metric_hint_label, fallback_target, txt, qd_hint, priority=0)\n\n    return sorted(results, key=lambda x: (int(x.get("priority") or 0), str(x.get("label") or "")))\n\ndef _extract_pbi_target_display(text_in: Any, metric_hint: str = "") -> str:\n    txt = glx_normalize_text(str(text_in or ""))\n    if not txt:\n        return ""\n    metric_label = _classify_pbi_metric_label(f"{metric_hint} | {txt}", metric_hint)\n    multi_targets = _extract_pbi_guidance_targets_multi(txt, metric_label)\n    if multi_targets:\n        metric_low = metric_label.lower()\n        for item in multi_targets:\n            if str(item.get("label") or "").strip().lower() == metric_low:\n                return str(item.get("target") or "").strip()\n        return str(multi_targets[0].get("target") or "").strip()\n    metric_label = metric_label.lower()\n\n    def _money_value(num_in: float, unit_hint: str = "") -> float:\n        val = float(num_in)\n        unit_low = str(unit_hint or "").strip().lower()\n        if unit_low.startswith("b"):\n            return val * 1000.0\n        return val\n\n    def _fmt_num(num_in: Optional[float], *, money: bool = False, eps: bool = False) -> str:\n        if num_in is None:\n            return ""\n        num_val = float(num_in)\n        if eps:\n            return f"${num_val:.2f}"\n        if money:\n            if abs(num_val) >= 1000.0:\n                return f"${num_val:,.0f}m"\n            if abs(num_val) >= 100.0:\n                return f"${num_val:,.0f}m"\n            return f"${num_val:,.1f}m".replace(".0m", "m")\n        return f"{num_val:,.0f}"\n\n    def _extract_range(metric_re: str, *, money: bool = False, eps: bool = False) -> str:\n        pattern = (\n            "(?:"\n            + str(metric_re)\n            + r")[^\\d$]{0,40}\\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s*(billion|bn|million|m)?\\s*"\n            r"(?:to|-|–|—)\\s*\\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s*(billion|bn|million|m)?"\n        )\n        m_range = re.search(\n            pattern,\n            txt,\n            re.I,\n        )\n        if not m_range:\n            return ""\n        lo = coerce_number(m_range.group(1))\n        hi = coerce_number(m_range.group(3))\n        if lo is None or hi is None:\n            return ""\n        if money:\n            lo = _money_value(lo, m_range.group(2) or "")\n            hi = _money_value(hi, m_range.group(4) or m_range.group(2) or "")\n        return f"{_fmt_num(lo, money=money, eps=eps)}-{_fmt_num(hi, money=money, eps=eps)}"\n\n    def _extract_money_with_context(metric_re: str) -> str:\n        m_money = re.search(\n            r"(?:"\n            + str(metric_re)\n            + r")[^\\d$]{0,40}\\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s*(billion|bn|million|m)",\n            txt,\n            re.I,\n        )\n        if not m_money:\n            return ""\n        val = coerce_number(m_money.group(1))\n        if val is None:\n            return ""\n        return _fmt_num(_money_value(val, m_money.group(2) or ""), money=True)\n\n    if "adjusted ebit" in metric_label:\n        target_txt = _extract_range(r"adjusted ebit", money=True)\n        if target_txt:\n            return target_txt\n    if "fcf" in metric_label:\n        target_txt = _extract_range(r"(free cash flow|fcf)", money=True)\n        if target_txt:\n            return target_txt\n    if "revenue" in metric_label:\n        target_txt = _extract_range(r"(full[- ]?year\\s+)?revenue", money=True)\n        if target_txt:\n            return target_txt\n    if "eps" in metric_label:\n        target_txt = _extract_range(r"(adjusted eps|eps)", eps=True)\n        if target_txt:\n            return target_txt\n    if "cost savings" in metric_label:\n        m_cost = re.search(\n            r"\\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s*(?:million|m)?\\s*(?:to|-|–|—)\\s*\\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s*(?:million|m)?.{0,40}\\b(cost savings?|net annualized cost savings?)\\b",\n            txt,\n            re.I,\n        )\n        if m_cost:\n            lo = coerce_number(m_cost.group(1))\n            hi = coerce_number(m_cost.group(2))\n            if lo is not None and hi is not None:\n                return f"{_fmt_num(lo, money=True)}-{_fmt_num(hi, money=True)}"\n        m_single = re.search(r"\\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s*(?:million|m).{0,30}\\b(cost savings?|savings)\\b", txt, re.I)\n        if m_single:\n            val = coerce_number(m_single.group(1))\n            if val is not None:\n                return _fmt_num(val, money=True)\n    if "liquidity release" in metric_label:\n        target_txt = _extract_money_with_context(r"(pb bank|trapped capital|bank liquidity|bank funding|funding release)")\n        if target_txt:\n            return target_txt\n    if "deleveraging" in metric_label:\n        m_lev = re.search(r"(?<!\\d)(\\d(?:\\.\\d+)?)\\s*x\\s+leverage", txt, re.I)\n        if m_lev:\n            lev = coerce_number(m_lev.group(1))\n            if lev is not None:\n                return f"{lev:.1f}x leverage"\n    return ""\n\nif not ticker_roots:\n    repo_root = Path(__file__).resolve().parents[2]\n    tkr = str(ticker or "").strip()\n    if tkr:\n        ticker_roots = [repo_root / tkr.upper(), repo_root / tkr, repo_root / tkr.lower()]\n\ndef _first_existing_material_dir(*names: str) -> Optional[Path]:\n    return source_first_existing_material_dir(\n        material_roots,\n        names,\n        ticker=ticker,\n        ticker_roots=ticker_roots,\n        path_belongs_to_ticker=_path_belongs_to_ticker,\n    )\n\ndef _parse_quarter_from_filename(name: str) -> Optional[date]:\n    nm = str(name or "")\n    m_date = re.search(r"\\b(20\\d{2})[-_](\\d{2})[-_](\\d{2})\\b", nm)\n    if m_date:\n        try:\n            return date(int(m_date.group(1)), int(m_date.group(2)), int(m_date.group(3)))\n        except Exception:\n            pass\n    m_compact_date = re.search(r"(?<!\\d)(20\\d{2})(\\d{2})(\\d{2})(?!\\d)", nm)\n    if m_compact_date:\n        try:\n            return date(\n                int(m_compact_date.group(1)),\n                int(m_compact_date.group(2)),\n                int(m_compact_date.group(3)),\n            )\n        except Exception:\n            pass\n    m_fy = re.search(r"(?<!\\d)fy[-_ ]?(20\\d{2})(?!\\d)", nm, re.I)\n    if m_fy:\n        try:\n            return date(int(m_fy.group(1)), 12, 31)\n        except Exception:\n            pass\n    m = re.search(r"(?<!\\d)Q([1-4])[-_ ]?(20\\d{2})(?!\\d)", nm, re.I)\n    if not m:\n        m = re.search(r"(?<!\\d)(20\\d{2})[-_ ]?Q([1-4])(?!\\d)", nm, re.I)\n        if m:\n            year = int(m.group(1))\n            qnum = int(m.group(2))\n        else:\n            quarter_name_map = {\n                "first": 1,\n                "second": 2,\n                "third": 3,\n                "fourth": 4,\n            }\n            m_named = re.search(\n                r"(?<![A-Z0-9])(first|second|third|fourth)[-_ ]quarter[-_ ]?(20\\d{2})(?!\\d)",\n                nm,\n                re.I,\n            )\n            if not m_named:\n                m_named = re.search(\n                    r"(?<!\\d)(20\\d{2})[-_ ]?(first|second|third|fourth)[-_ ]quarter(?![A-Z0-9])",\n                    nm,\n                    re.I,\n                )\n                if m_named:\n                    year = int(m_named.group(1))\n                    qnum = quarter_name_map.get(str(m_named.group(2) or "").lower(), 0)\n                else:\n                    return None\n            else:\n                qnum = quarter_name_map.get(str(m_named.group(1) or "").lower(), 0)\n                year = int(m_named.group(2))\n    else:\n        qnum = int(m.group(1))\n        year = int(m.group(2))\n    try:\n        return pd.Period(f"{year}Q{qnum}", freq="Q").end_time.date()\n    except Exception:\n        return None\n\n_pbi_structured_guidance_cache: Dict[date, List[Dict[str, Any]]] = {}\n_pbi_structured_strategy_cache: Dict[date, List[Dict[str, Any]]] = {}\n_pbi_structured_note_cache: Dict[date, List[Dict[str, Any]]] = {}\n_pbi_structured_tracker_cache: Dict[date, List[Dict[str, Any]]] = {}\n_pbi_structured_progress_cache: Dict[date, List[Dict[str, Any]]] = {}\n_pbi_reported_fcf_cache: Dict[date, Optional[Dict[str, Any]]] = {}\n\ndef _pbi_slide_pages_for_qd(qd: Optional[date]) -> List[Dict[str, Any]]:\n    if not isinstance(qd, date):\n        return []\n    pages: List[Dict[str, Any]] = []\n    for path in _slide_text_paths(kind="text", quarter=qd):\n        txt_raw = _read_cached_doc_raw(path)\n        if not txt_raw:\n            continue\n        raw_lines: List[str] = []\n        for raw_line in str(txt_raw or "").splitlines():\n            line = (\n                    str(raw_line or "")\n                    .replace("â€¢", "•")\n                    .replace("â–ª", "•")\n                    .replace("âŽ»", "")\n                    .replace("â€œ", "\\"")\n                    .replace("â€\\x9d", "\\"")\n            )\n            line = glx_normalize_text(line)\n            if not line:\n                continue\n            if re.fullmatch(r"\\d+", line):\n                continue\n            if re.match(r"^Pitney Bowes\\b", line, re.I):\n                continue\n            raw_lines.append(line)\n        merged_lines: List[str] = []\n        for line in raw_lines:\n            if (\n                merged_lines\n                and not re.match(\n                        r"^(•|Full Year|Guidance\\b|Priority #|Progress to Date:|Looking Ahead:|"\n                        r"Revenue\\b|Adjusted EBIT\\b|Adjusted EPS\\b|Free Cash Flow\\b|\\$ millions|"\n                        r"First Quarter\\b|Second Quarter\\b|Third Quarter\\b|Fourth Quarter\\b|"\n                        r"Cash Freed Up from PB Bank\\b)",\n                    line,\n                    re.I,\n                )\n                and not merged_lines[-1].endswith((".", ":", ";"))\n            ):\n                merged_lines[-1] = f"{merged_lines[-1]} {line}".strip()\n            else:\n                merged_lines.append(line)\n        text_full = glx_normalize_text(" ".join(merged_lines))\n        page_match = re.search(r"_p(\\d+)\\.txt$", path.name, re.I)\n        pages.append(\n                {\n                    "path": path,\n                    "page": int(page_match.group(1)) if page_match else None,\n                    "lines": merged_lines,\n                    "text": text_full,\n                }\n            )\n    return pages\n\ndef _pbi_reported_fcf_payload_for_qd(qd: Optional[date]) -> Optional[Dict[str, Any]]:\n    if not is_pbi_profile or not isinstance(qd, date):\n        return None\n    cached = _pbi_reported_fcf_cache.get(qd)\n    if cached is not None:\n        return dict(cached) if cached else None\n\n    quarter_num = ((int(qd.month) - 1) // 3) + 1\n    quarter_caption = {\n        1: "First Quarter",\n        2: "Second Quarter",\n        3: "Third Quarter",\n        4: "Fourth Quarter",\n    }.get(int(quarter_num), "")\n\n    def _parse_fcf_pair_local(text_in: Any) -> Optional[Dict[str, float]]:\n        txt = glx_normalize_text(str(text_in or ""))\n        if not txt or "free cash flow" not in txt.lower():\n            return None\n\n        def _signed_amount_local(raw_in: Any, scale_in: float) -> Optional[float]:\n            raw_txt = str(raw_in or "")\n            val = coerce_number(raw_txt)\n            if val is None:\n                return None\n            sign = -1.0 if re.search(r"\\(\\s*\\$?\\s*[0-9]", raw_txt) else 1.0\n            return sign * abs(float(val)) * float(scale_in)\n\n        def _guidance_like_match_local(match_obj: re.Match[str]) -> bool:\n            start = max(0, int(match_obj.start()) - 240)\n            end = min(len(txt), int(match_obj.end()) + 240)\n            window = txt[start:end].lower()\n            return bool(\n                re.search(\n                    r"\\b(guidance|outlook|full[- ]year|fy\\s*20\\d{2}|low\\s+high|"\n                    r"previously disclosed guidance range|near the low end|near the midpoint|"\n                    r"midpoint|low end|high end|target)\\b",\n                    window,\n                    re.I,\n                )\n            )\n\n        patterns: List[Tuple[str, float, int, bool]] = [\n            (\n                r"reconciliation of (?:reported\\s+)?net cash from operating activities to free cash flow[\\s\\S]{0,5000}?"\n                r"free cash flow\\s+(\\(?\\$?\\s*[0-9]{1,3}(?:,[0-9]{3})+(?:\\.\\d+)?\\)?)\\s+"\n                r"(\\(?\\$?\\s*[0-9]{1,3}(?:,[0-9]{3})+(?:\\.\\d+)?\\)?)",\n                1_000.0,\n                0,\n                False,\n            ),\n            (\n                r"free cash flow was a use of\\s+\\$?\\(?([0-9]{1,4}(?:\\.\\d+)?)\\)?\\s+million,\\s+an improvement of\\s+\\$?\\(?([0-9]{1,4}(?:\\.\\d+)?)\\)?\\s+million\\s+year[- ]over[- ]year",\n                -1_000_000.0,\n                1,\n                False,\n            ),\n            (\n                r"free cash flow improved to\\s+\\$?\\(?([0-9]{1,4}(?:\\.\\d+)?)\\)?\\s+million,\\s+(?:up|down)\\s+\\$?\\(?([0-9]{1,4}(?:\\.\\d+)?)\\)?\\s+million\\s+year[- ]over[- ]year",\n                1_000_000.0,\n                1,\n                False,\n            ),\n            (\n                rf"{quarter_caption}[\\s\\S]{{0,1200}}?free cash flow(?:\\d+)?\\s+\\$?\\(?([0-9]{{1,4}}(?:\\.\\d+)?)\\)?\\$?\\s+\\$?\\(?([0-9]{{1,4}}(?:\\.\\d+)?)\\)?\\$?",\n                1_000_000.0,\n                2,\n                True,\n            ),\n            (\n                r"free cash flow(?:\\d+)?\\s+\\$?\\(?([0-9]{1,4}(?:\\.\\d+)?)\\)?\\$?\\s+\\$?\\(?([0-9]{1,4}(?:\\.\\d+)?)\\)?\\$?",\n                1_000_000.0,\n                3,\n                True,\n            ),\n        ]\n        best_payload: Optional[Dict[str, float]] = None\n        best_rank: Optional[Tuple[int, int]] = None\n        for pat, scale, priority, guard_guidance in patterns:\n            for m in re.finditer(pat, txt, re.I):\n                if guard_guidance and _guidance_like_match_local(m):\n                    continue\n                cur_val = coerce_number(m.group(1))\n                second_val = coerce_number(m.group(2))\n                if cur_val is None or second_val is None:\n                    continue\n                if scale < 0:\n                    current_scaled = -abs(float(cur_val) * abs(float(scale)))\n                    prior_scaled = current_scaled - float(second_val) * abs(float(scale))\n                    payload = {\n                        "current": float(current_scaled),\n                        "prior": float(prior_scaled),\n                    }\n                else:\n                    current_scaled = _signed_amount_local(m.group(1), float(scale))\n                    prior_scaled = _signed_amount_local(m.group(2), float(scale))\n                    if current_scaled is None or prior_scaled is None:\n                        continue\n                    payload = {\n                        "current": float(current_scaled),\n                        "prior": float(prior_scaled),\n                    }\n                rank = (int(priority), int(m.start()))\n                if best_rank is None or rank < best_rank:\n                    best_rank = rank\n                    best_payload = payload\n        if best_payload is not None:\n            return best_payload\n        return None\n\n    def _add_probe_dir(path_in: Any, seen_dirs: set[str], probe_dirs: List[Path]) -> None:\n        try:\n            p = Path(path_in)\n        except Exception:\n            return\n        if not _allow_repo_profile_cache_fallback() and _is_repo_profile_cache_path(p):\n            return\n        if not p.exists() or not p.is_dir():\n            return\n        try:\n            key = str(p.resolve())\n        except Exception:\n            key = str(p)\n        if key in seen_dirs:\n            return\n        seen_dirs.add(key)\n        probe_dirs.append(p)\n\n    probe_dirs: List[Path] = []\n    seen_dirs: set[str] = set()\n    if _allow_repo_profile_cache_fallback():\n        for repo_dir in [repo_root / "sec_cache" / "PBI", repo_root / "PBI" / "sec_cache"]:\n            _add_probe_dir(repo_dir, seen_dirs, probe_dirs)\n    for root in material_roots:\n        for sec_cache_dir in ticker_cache_roots_from_base_dir(root):\n            _add_probe_dir(sec_cache_dir, seen_dirs, probe_dirs)\n    cache_dir_path = Path(cache_dir) if cache_dir is not None else None\n    if cache_dir_path is not None:\n        _add_probe_dir(cache_dir_path, seen_dirs, probe_dirs)\n        ticker_variants = [\n            str(profile_ticker or ticker or "").strip(),\n            str(profile_ticker or ticker or "").strip().upper(),\n            str(profile_ticker or ticker or "").strip().lower(),\n        ]\n        for nm in ticker_variants:\n            nm = str(nm or "").strip()\n            if not nm:\n                continue\n            _add_probe_dir(cache_dir_path / nm, seen_dirs, probe_dirs)\n            _add_probe_dir(cache_dir_path / nm / "sec_cache", seen_dirs, probe_dirs)\n        for ancestor in [cache_dir_path.parent, *cache_dir_path.parents]:\n            for nm in ticker_variants:\n                nm = str(nm or "").strip()\n                if not nm:\n                    continue\n                _add_probe_dir(ancestor / nm / "sec_cache", seen_dirs, probe_dirs)\n\n    qd_token = pd.to_datetime(qd, errors="coerce")\n    qd_token_str = qd_token.strftime("%Y%m%d") if pd.notna(qd_token) else ""\n    quarter_path_token = f"q{quarter_num}{qd.year}"\n    best_payload: Optional[Dict[str, Any]] = None\n    best_rank: Optional[Tuple[int, int, int, int]] = None\n    for sec_cache_dir in probe_dirs:\n        candidates = _sec_cache_html_paths_for_token_local(sec_cache_dir, qd_token_str) if qd_token_str else []\n        if not candidates:\n            candidates = _sec_cache_html_paths_local(sec_cache_dir)\n        for path_in in candidates:\n            if not _path_belongs_to_ticker(path_in, ticker, ticker_roots):\n                continue\n            try:\n                raw_txt = _read_cached_doc_raw(path_in)\n            except Exception:\n                raw_txt = ""\n            try:\n                plain_txt = _read_cached_doc_text(path_in)\n            except Exception:\n                plain_txt = ""\n            joined_norm = glx_normalize_text(" ".join([str(raw_txt or ""), str(plain_txt or "")]))\n            if not joined_norm:\n                continue\n            q_raw = _infer_doc_quarter_local(path_in, joined_norm)\n            path_name_low = str(path_in.name).lower()\n            path_matches_q = bool(qd_token_str and qd_token_str in path_name_low)\n            if not path_matches_q and quarter_path_token:\n                path_matches_q = quarter_path_token in path_name_low\n            text_matches_q = bool(\n                quarter_caption\n                and re.search(rf"\\b{quarter_caption}\\b[\\s\\S]{{0,80}}?\\b{qd.year}\\b", joined_norm, re.I)\n            )\n            if isinstance(q_raw, date):\n                if q_raw != qd and not path_matches_q:\n                    continue\n            elif not path_matches_q and not text_matches_q:\n                continue\n            parsed = _parse_fcf_pair_local(joined_norm)\n            if not parsed:\n                continue\n            path_low = str(path_in).lower()\n            name_low = str(path_in.name).lower()\n            rank = (\n                0 if re.search(r"(earningspressrelea|earnings[_ ]release|press[_ ]release|ex99)", name_low, re.I) else 1,\n                0 if re.search(r"(earningspressrelea|earnings[_ ]release|press[_ ]release|ex99)", path_low, re.I) else 1,\n                0 if path_matches_q else 1,\n                len(path_low),\n            )\n            if best_rank is None or rank < best_rank:\n                best_rank = rank\n                best_payload = {\n                    "current": float(parsed["current"]),\n                    "prior": float(parsed["prior"]),\n                    "doc": str(path_in),\n                }\n\n    if best_payload is None:\n        direct_roots: List[Path] = []\n        seen_direct_roots: set[str] = set()\n        direct_root_candidates = [cache_dir_path]\n        if _allow_repo_profile_cache_fallback():\n            direct_root_candidates.extend([repo_root / "sec_cache" / "PBI", repo_root / "PBI" / "sec_cache"])\n        for root_in in direct_root_candidates:\n            if root_in is None:\n                continue\n            try:\n                root_path = Path(root_in)\n            except Exception:\n                continue\n            if not root_path.exists() or not root_path.is_dir():\n                continue\n            try:\n                root_key = str(root_path.resolve())\n            except Exception:\n                root_key = str(root_path)\n            if root_key in seen_direct_roots:\n                continue\n            seen_direct_roots.add(root_key)\n            direct_roots.append(root_path)\n        for root_path in direct_roots:\n            try:\n                raw_candidates = sorted(\n                    [p for p in root_path.rglob("*.htm") if p.is_file()],\n                    key=lambda z: z.stat().st_mtime if z.exists() else 0,\n                    reverse=True,\n                )\n            except Exception:\n                raw_candidates = []\n            for path_in in raw_candidates:\n                if not _path_belongs_to_ticker(path_in, ticker, ticker_roots):\n                    continue\n                path_low = str(path_in).lower()\n                name_low = str(path_in.name).lower()\n                if "free cash flow" not in name_low and not re.search(\n                    r"(earningspressrelea|earnings[_ ]release|press[_ ]release|ex99|8-?k)",\n                    path_low,\n                    re.I,\n                ):\n                    continue\n                try:\n                    joined_norm = glx_normalize_text(path_in.read_text(encoding="utf-8", errors="ignore"))\n                except Exception:\n                    joined_norm = ""\n                if not joined_norm:\n                    continue\n                q_raw = _infer_doc_quarter_local(path_in, joined_norm)\n                path_matches_q = bool(qd_token_str and qd_token_str in name_low) or bool(quarter_path_token and quarter_path_token in name_low)\n                text_matches_q = bool(\n                    quarter_caption\n                    and re.search(rf"\\b{quarter_caption}\\b[\\s\\S]{{0,80}}?\\b{qd.year}\\b", joined_norm, re.I)\n                )\n                if isinstance(q_raw, date):\n                    if q_raw != qd and not path_matches_q:\n                        continue\n                elif not path_matches_q and not text_matches_q:\n                    continue\n                parsed = _parse_fcf_pair_local(joined_norm)\n                if not parsed:\n                    continue\n                best_payload = {\n                    "current": float(parsed["current"]),\n                    "prior": float(parsed["prior"]),\n                    "doc": str(path_in),\n                }\n                break\n            if best_payload is not None:\n                break\n\n    _pbi_reported_fcf_cache[qd] = dict(best_payload) if best_payload else None\n    return dict(best_payload) if best_payload else None\n\ndef _pbi_forced_release_backed_fcf_note_for_qd(qd: Optional[date]) -> Optional[Dict[str, Any]]:\n    payload = _pbi_reported_fcf_payload_for_qd(qd)\n    if not isinstance(qd, date) or not isinstance(payload, dict):\n        return None\n    current_fcf = payload.get("current")\n    prior_fcf = payload.get("prior")\n    if current_fcf is None or prior_fcf is None:\n        return None\n    delta_fcf = float(current_fcf) - float(prior_fcf)\n    summary_txt = _format_directional_fcf_summary_local(current_fcf, prior_fcf, basis_label="YoY")\n    return {\n        "summary": summary_txt,\n        "comment_full_text": (\n            f"Reported free cash flow at {qd}: {_fmt_short_money_value_local(float(current_fcf))}; "\n            f"YoY delta {_fmt_short_money_value_local(delta_fcf)}"\n        ),\n        "source": {\n            "source_type": "earnings_release",\n            "doc": str(payload.get("doc") or ""),\n            "form": "",\n            "section": "free cash flow",\n        },\n    }\n\ndef _pbi_guidance_period_for_text(text_in: Any, qd: date) -> Tuple[str, str]:\n    txt = glx_normalize_text(str(text_in or ""))\n    m_fy = re.search(r"\\bfull[- ]?year\\s+(20\\d{2})\\b|\\bfy\\s*(20\\d{2})\\b", txt, re.I)\n    if m_fy:\n        year_txt = m_fy.group(1) or m_fy.group(2)\n        if year_txt:\n            return (f"FY{year_txt}", f"FY {year_txt}")\n    return (f"FY{qd.year}", f"FY {qd.year}")\n\ndef _fmt_pbi_million_amount(val_in: Any) -> str:\n    try:\n        val = float(val_in)\n    except Exception:\n        return ""\n    sign = "-" if val < 0 else ""\n    aval = abs(val)\n    if aval >= 1000.0:\n        body = f"{aval / 1000.0:,.2f}".rstrip("0").rstrip(".")\n        return f"{sign}${body}bn"\n    body = f"{aval:,.1f}".rstrip("0").rstrip(".")\n    return f"{sign}${body}m"\n\ndef _pbi_guidance_table_target_display(metric_label: str, lo: float, hi: float) -> str:\n    label_low = str(metric_label or "").lower()\n    if "eps" in label_low:\n        return f"${float(lo):.2f}-${float(hi):.2f}"\n    return f"{_fmt_pbi_million_amount(lo)}-{_fmt_pbi_million_amount(hi)}"\n\ndef _ensure_terminal_period(text_in: Any) -> str:\n    txt = glx_normalize_text(str(text_in or ""))\n    if not txt:\n        return ""\n    if re.search(r"[.!?]\\s*$", txt):\n        return txt\n    return f"{txt}."\n\ndef _format_directional_fcf_summary_local(\n    current_val: Any,\n    prior_val: Any | None = None,\n    *,\n    basis_label: str = "YoY",\n) -> str:\n    try:\n        current_num = float(current_val)\n    except Exception:\n        return ""\n    if prior_val is None:\n        if current_num < 0:\n            return _ensure_terminal_period(\n                f"Free cash flow was a use of {_fmt_short_money_value_local(abs(current_num))}"\n            )\n        return _ensure_terminal_period(f"Free cash flow was {_fmt_short_money_value_local(current_num)}")\n    try:\n        prior_num = float(prior_val)\n    except Exception:\n        return _format_directional_fcf_summary_local(current_num, None, basis_label=basis_label)\n    delta_val = current_num - prior_num\n    direction = "up" if delta_val >= 0 else "down"\n    if current_num < 0:\n        return _ensure_terminal_period(\n            f"Free cash flow was a use of {_fmt_short_money_value_local(abs(current_num))}, "\n            f"{direction} {_fmt_short_money_value_local(abs(delta_val))} {basis_label}"\n        )\n    lead = "improved to" if delta_val >= 0 else "declined to"\n    return _ensure_terminal_period(\n        f"Free cash flow {lead} {_fmt_short_money_value_local(current_num)}, "\n        f"{direction} {_fmt_short_money_value_local(abs(delta_val))} {basis_label}"\n    )\n\ndef _format_directional_from_prior_summary_local(\n    noun_text: str,\n    current_val: Any,\n    prior_val: Any,\n    *,\n    basis_label: str = "YoY",\n    negative_parens: bool = False,\n) -> str:\n    noun = glx_normalize_text(str(noun_text or ""))\n    if not noun:\n        return ""\n    try:\n        current_num = float(current_val)\n        prior_num = float(prior_val)\n    except Exception:\n        return ""\n    formatter = _fmt_short_money_value_with_parens_local if negative_parens else _fmt_short_money_value_local\n    current_txt = formatter(current_num)\n    prior_txt = formatter(prior_num)\n    if current_num > prior_num:\n        return _ensure_terminal_period(f"{noun} improved to {current_txt} from {prior_txt} {basis_label}")\n    if current_num < prior_num:\n        return _ensure_terminal_period(f"{noun} declined to {current_txt} from {prior_txt} {basis_label}")\n    return _ensure_terminal_period(f"{noun} was unchanged at {current_txt} vs {prior_txt} {basis_label}")\n\ndef _parse_signed_money_token_local(raw_val: Any) -> Optional[float]:\n    txt_num = glx_normalize_text(str(raw_val or ""))\n    if not txt_num:\n        return None\n    neg = bool(\n        re.match(r"^\\(\\$?.+\\)$", txt_num)\n        or re.match(r"^\\$?\\(.+\\)$", txt_num)\n        or txt_num.startswith("-")\n    )\n    cleaned = txt_num.replace("$", "").replace(",", "").strip()\n    cleaned = cleaned.strip("()").strip()\n    val = coerce_number(cleaned)\n    if val is None:\n        return None\n    return -abs(float(val)) if neg else float(val)\n\ndef _parse_gpre_crush_margin_pair_local(text_in: Any) -> Optional[Tuple[float, float, str]]:\n    txt_local = glx_normalize_text(str(text_in or ""))\n    if not txt_local or "consolidated ethanol crush margin" not in txt_local.lower():\n        return None\n    money_pat = r"(?:\\(\\$?-?\\d+(?:,\\d{3})*(?:\\.\\d+)?\\)|\\$?\\(?-?\\d+(?:,\\d{3})*(?:\\.\\d+)?\\)?)"\n    pair_patterns = [\n        rf"\\bconsolidated ethanol crush margin was\\s+(?P<current>{money_pat})\\s*(?:million|m)\\b"\n        rf"[^.]{{0,320}}?\\bcompared with(?:\\s+ethanol crush margin of)?\\s+(?P<prior>{money_pat})\\s*(?:million|m)\\b",\n    ]\n    for pat in pair_patterns:\n        pair_match = re.search(pat, txt_local, re.I)\n        if not pair_match:\n            continue\n        cur_val = _parse_signed_money_token_local(pair_match.group("current"))\n        prior_val = _parse_signed_money_token_local(pair_match.group("prior"))\n        if cur_val is None or prior_val is None:\n            continue\n        return float(cur_val), float(prior_val), _ensure_terminal_period(pair_match.group(0))\n    return None\n\ndef _collapse_repeated_leading_ngram_local(text_in: Any) -> str:\n    txt = glx_normalize_text(str(text_in or ""))\n    if not txt:\n        return ""\n    words = txt.split()\n    if len(words) < 4:\n        return txt\n    lowered = [w.lower() for w in words]\n    for n in range(min(6, len(words) // 2), 1, -1):\n        prefix = lowered[:n]\n        idx = n\n        repeats = 1\n        while idx + n <= len(words) and lowered[idx : idx + n] == prefix:\n            repeats += 1\n            idx += n\n        if repeats > 1:\n            return glx_normalize_text(" ".join(words[:n] + words[idx:]))\n    return txt\n\ndef _dedupe_canonical_text_parts_local(parts_in: List[str]) -> List[str]:\n    cleaned_parts: List[str] = []\n    for raw_part in parts_in:\n        part = _collapse_repeated_leading_ngram_local(glx_normalize_text(raw_part))\n        if not part:\n            continue\n        cleaned_parts.append(part)\n    kept_parts: List[str] = []\n    for idx, part in enumerate(cleaned_parts):\n        low = part.lower()\n        drop = False\n        for jdx, other in enumerate(cleaned_parts):\n            if idx == jdx:\n                continue\n            other_low = other.lower()\n            if not other_low:\n                continue\n            if low != other_low and other_low in low and len(low) >= len(other_low) + 12:\n                drop = True\n                break\n        if not drop and low not in {p.lower() for p in kept_parts}:\n            kept_parts.append(part)\n    return kept_parts\n\ndef _pbi_guidance_period_label_from_text(text_in: Any) -> str:\n    txt = glx_normalize_text(str(text_in or ""))\n    if not txt:\n        return ""\n    m_fy = re.search(r"\\bfull[- ]?year\\s+(20\\d{2})\\b|\\bfy\\s*(20\\d{2})\\b", txt, re.I)\n    if m_fy:\n        year_txt = m_fy.group(1) or m_fy.group(2)\n        if year_txt:\n            return f"FY {year_txt}"\n    m_q = re.search(r"\\bq([1-4])\\s*(20\\d{2})\\b|\\b(20\\d{2})\\s*q([1-4])\\b", txt, re.I)\n    if m_q:\n        if m_q.group(1) and m_q.group(2):\n            return f"Q{m_q.group(1)} {m_q.group(2)}"\n        if m_q.group(3) and m_q.group(4):\n            return f"Q{m_q.group(4)} {m_q.group(3)}"\n    return ""\n\ndef _pbi_guidance_self_contained_summary(\n    metric_label: str,\n    target_display: str,\n    text_in: Any,\n    period_label: str = "",\n) -> str:\n    metric_txt = str(metric_label or "").strip()\n    target_txt = str(target_display or "").strip()\n    period_txt = str(period_label or "").strip() or _pbi_guidance_period_label_from_text(text_in)\n    txt = glx_normalize_text(str(text_in or ""))\n    low = txt.lower()\n    prefix = " ".join(part for part in [period_txt, metric_txt] if part).strip() or metric_txt or "Guidance"\n    if re.search(r"\\b(reaffirm|reaffirmed|reaffirms)\\b", low):\n        return _ensure_terminal_period(f"{prefix} reaffirmed at {target_txt}")\n    if re.search(r"\\b(now expects to achieve near the low-end|near the low-end)\\b", low):\n        return _ensure_terminal_period(f"{prefix} tracking near the low end of {target_txt}")\n    if re.search(r"\\b(now expects to achieve near the midpoint|near the midpoint)\\b", low):\n        return _ensure_terminal_period(f"{prefix} tracking near the midpoint of {target_txt}")\n    if re.search(r"\\b(raise|raised|raising|updated|tightened|lowered)\\b", low):\n        return _ensure_terminal_period(f"{prefix} updated to {target_txt}")\n    if re.search(r"\\b(target|guidance)\\b", metric_txt, re.I):\n        return _ensure_terminal_period(f"{prefix} {target_txt}")\n    return _ensure_terminal_period(f"{prefix} target {target_txt}")\n\ndef _pbi_guidance_compact_note(metric_label: str, target_display: str, text_in: Any) -> str:\n    return _pbi_guidance_self_contained_summary(metric_label, target_display, text_in)\n\ndef _pbi_structured_guidance_items_for_qd(qd: Optional[date]) -> List[Dict[str, Any]]:\n    if not isinstance(qd, date):\n        return []\n    cached = _pbi_structured_guidance_cache.get(qd)\n    if cached is not None:\n        return [dict(x) for x in cached]\n\n    items_by_key: Dict[Tuple[str, str, str], Dict[str, Any]] = {}\n    pages = _pbi_slide_pages_for_qd(qd)\n    for page in pages:\n        path = page["path"]\n        lines = list(page.get("lines") or [])\n        txt_full = str(page.get("text") or "")\n        low = txt_full.lower()\n        if not txt_full or not re.search(r"\\bguidance\\b", low):\n            continue\n        if not re.search(r"\\b(revenue|adjusted ebit|adjusted eps|free cash flow)\\b", low):\n            continue\n        period_norm, period_label = _pbi_guidance_period_for_text(txt_full, qd)\n        page_label = f"page {page.get(\'page\')}" if page.get("page") not in (None, "") else ""\n        for metric_label, row_re in (\n            ("Revenue guidance", r"^Revenue(?:\\s+guidance)?\\s+\\$?([\\d,]+(?:\\.\\d+)?)\\s+(?:to\\s+)?\\$?([\\d,]+(?:\\.\\d+)?)$"),\n            ("Adjusted EBIT guidance", r"^Adjusted EBIT(?:\\s+guidance)?\\s+\\$?([\\d,]+(?:\\.\\d+)?)\\s+(?:to\\s+)?\\$?([\\d,]+(?:\\.\\d+)?)$"),\n            ("EPS guidance", r"^Adjusted EPS(?:\\s+guidance)?\\s+\\$?([\\d,]+(?:\\.\\d+)?)\\s+(?:to\\s+)?\\$?([\\d,]+(?:\\.\\d+)?)$"),\n            ("FCF target", r"^Free Cash Flow(?:\\s+guidance)?\\s+\\$?([\\d,]+(?:\\.\\d+)?)\\s+(?:to\\s+)?\\$?([\\d,]+(?:\\.\\d+)?)$"),\n        ):\n            matched_line = None\n            for line in lines:\n                m_row = re.match(row_re, line, re.I)\n                if m_row:\n                    matched_line = m_row\n                    break\n            if not matched_line:\n                continue\n            lo = coerce_number(matched_line.group(1))\n            hi = coerce_number(matched_line.group(2))\n            if lo is None or hi is None:\n                continue\n            target_display = _pbi_guidance_table_target_display(metric_label, float(lo), float(hi))\n            compact_note = _pbi_guidance_compact_note(metric_label, target_display, txt_full)\n            text_structured = _pbi_guidance_sentence(metric_label, target_display, period_label, txt_full)\n            key = (metric_label.lower(), target_display.lower(), period_norm.lower())\n            candidate = {\n                "quarter": qd,\n                "metric_label": metric_label,\n                "target_display": target_display,\n                "period_norm": period_norm,\n                "period_label": period_label,\n                "compact_note": compact_note,\n                "text_full": text_structured,\n                "source": {\n                    "source_type": "pbi_guidance_structured",\n                    "doc": str(path),\n                    "form": "presentation",\n                    "section": page_label,\n                },\n                "score": 90.0,\n                "doc_priority": 9,\n            }\n            items_by_key[key] = candidate\n\n    if not items_by_key:\n        legacy_items: Dict[Tuple[str, str, str], Dict[str, Any]] = {}\n        for page in pages:\n            path = page["path"]\n            txt_full = str(page.get("text") or "")\n            low = txt_full.lower()\n            if not txt_full or not re.search(r"\\b(guidance|outlook|full[- ]?year|reaffirm|updated|raising|tightened|lowered|expects)\\b", low):\n                continue\n            if re.search(r"\\b(previously disclosed guidance ranges|for reference)\\b", low):\n                continue\n            parsed_items = _extract_pbi_guidance_targets_multi(txt_full, "", qd)\n            if not parsed_items:\n                continue\n            page_label = f"page {page.get(\'page\')}" if page.get("page") not in (None, "") else ""\n            for parsed in parsed_items:\n                metric_label = str(parsed.get("label") or "").strip()\n                target_display = str(parsed.get("target") or "").strip()\n                if metric_label not in {"Revenue guidance", "Adjusted EBIT guidance", "EPS guidance", "FCF target"}:\n                    continue\n                if not _pbi_target_display_ok(target_display):\n                    continue\n                period_norm = str(parsed.get("period_norm") or "").strip()\n                period_label = str(parsed.get("period_label") or "").strip() or _pbi_period_label_from_norm(period_norm, qd)\n                key = (metric_label.lower(), target_display.lower(), period_norm.lower())\n                legacy_items[key] = {\n                    "quarter": qd,\n                    "metric_label": metric_label,\n                    "target_display": target_display,\n                    "period_norm": period_norm,\n                    "period_label": period_label,\n                    "compact_note": _pbi_guidance_compact_note(metric_label, target_display, txt_full),\n                    "text_full": _pbi_guidance_sentence(metric_label, target_display, period_label, txt_full),\n                    "source": {\n                        "source_type": "pbi_guidance_structured",\n                        "doc": str(path),\n                        "form": "presentation",\n                        "section": page_label,\n                    },\n                    "score": 88.0,\n                    "doc_priority": 8,\n                }\n        items_by_key = legacy_items\n\n    gstore = ui_state.get("guidance_snapshot_by_q", {}) if isinstance(ui_state, dict) else {}\n    g_items = gstore.get(str(qd), []) if isinstance(gstore, dict) else []\n    if isinstance(g_items, list):\n        for it in g_items:\n            if not isinstance(it, dict):\n                continue\n            raw_metric = str(it.get("metric") or "").strip()\n            metric_label = {\n                "Revenue": "Revenue guidance",\n                "Adj EBIT": "Adjusted EBIT guidance",\n                "Adjusted EBIT": "Adjusted EBIT guidance",\n                "Adj EPS": "EPS guidance",\n                "EPS": "EPS guidance",\n                "FCF": "FCF target",\n            }.get(raw_metric, _classify_pbi_metric_label(raw_metric, raw_metric))\n            if metric_label not in {"Revenue guidance", "Adjusted EBIT guidance", "EPS guidance", "FCF target"}:\n                continue\n            period_norm = str(it.get("target_period_norm") or it.get("period_norm") or "").strip()\n            period_label = str(it.get("target_period_label") or it.get("period") or "").strip() or _pbi_period_label_from_norm(period_norm, qd)\n            kind = str(it.get("kind") or "").strip().lower()\n            target_display = ""\n            if kind == "range" and it.get("low") is not None and it.get("high") is not None:\n                lo = float(it.get("low"))\n                hi = float(it.get("high"))\n                if metric_label == "EPS guidance":\n                    target_display = _pbi_guidance_table_target_display(metric_label, lo, hi)\n                else:\n                    if max(abs(lo), abs(hi)) >= 10_000:\n                        lo /= 1_000_000.0\n                        hi /= 1_000_000.0\n                    target_display = _pbi_guidance_table_target_display(metric_label, lo, hi)\n            elif kind == "point" and it.get("value") is not None:\n                val = float(it.get("value"))\n                if metric_label == "EPS guidance":\n                    target_display = f"${val:.2f}"\n                else:\n                    if abs(val) >= 10_000:\n                        val /= 1_000_000.0\n                    target_display = _fmt_pbi_million_amount(val)\n            if not _pbi_target_display_ok(target_display):\n                continue\n            src = dict(it.get("source") or {})\n            text_full = glx_normalize_text(str(it.get("text") or ""))\n            compact_note = _pbi_guidance_compact_note(metric_label, target_display, text_full)\n            key = (metric_label.lower(), target_display.lower(), period_norm.lower())\n            items_by_key.setdefault(\n                key,\n                {\n                    "quarter": qd,\n                    "metric_label": metric_label,\n                    "target_display": target_display,\n                    "period_norm": period_norm,\n                    "period_label": period_label,\n                    "compact_note": compact_note,\n                    "text_full": _pbi_guidance_sentence(metric_label, target_display, period_label, text_full),\n                    "source": {\n                        "source_type": src.get("source_type") or src.get("doc_type") or "guidance_snapshot",\n                        "doc": src.get("doc") or src.get("doc_path") or "",\n                        "form": src.get("form") or "",\n                        "section": src.get("section") or src.get("section_or_page") or "",\n                    },\n                    "score": float(it.get("score") or 84.0),\n                    "doc_priority": int(it.get("source_priority") or 7),\n                },\n            )\n\n    ordered = sorted(\n        items_by_key.values(),\n        key=lambda z: (\n            {\n                "Revenue guidance": 0,\n                "Adjusted EBIT guidance": 1,\n                "EPS guidance": 2,\n                "FCF target": 3,\n            }.get(str(z.get("metric_label") or ""), 9),\n            str(z.get("period_norm") or ""),\n        ),\n    )\n    _pbi_structured_guidance_cache[qd] = [dict(x) for x in ordered]\n    return [dict(x) for x in ordered]\n\ndef _pbi_compact_guidance_note(target_display: str, text_in: Any) -> str:\n    target_txt = str(target_display or "").strip()\n    txt = glx_normalize_text(str(text_in or ""))\n    low = txt.lower()\n    lead = "Target"\n    if re.search(r"\\b(reaffirm|reaffirmed|reaffirms)\\b", low):\n        lead = "Reaffirmed target"\n    elif re.search(r"\\b(raise|raised|raising|updated|tightened|lowered)\\b", low):\n        lead = "Updated target"\n    elif re.search(r"\\b(now expects to achieve near the low-end|near the low-end)\\b", low):\n        lead = "Tracking low end"\n    elif re.search(r"\\b(now expects to achieve near the midpoint|near the midpoint)\\b", low):\n        lead = "Tracking midpoint"\n    return f"{lead} {target_txt}".strip()\n\ndef _pbi_guidance_sentence(metric_label: str, target_display: str, period_label: str, text_in: Any) -> str:\n    return _pbi_guidance_self_contained_summary(metric_label, target_display, text_in, period_label=period_label)\n\ndef _pbi_period_label_from_norm(period_norm: str, asof_q: date) -> str:\n    p = str(period_norm or "").strip()\n    if not p:\n        return ""\n    if p == "FY+1":\n        return f"FY {int(asof_q.year) + 1}"\n    m_fy = re.match(r"FY(20\\d{2})$", p)\n    if m_fy:\n        return f"FY {int(m_fy.group(1))}"\n    m_q = re.match(r"Q(20\\d{2})Q([1-4])$", p)\n    if m_q:\n        return f"Q{int(m_q.group(2))} {int(m_q.group(1))}"\n    return p\n\ndef _period_label_to_norm(label_in: Any) -> str:\n    label = str(label_in or "").strip()\n    if not label:\n        return ""\n    m_fy = re.fullmatch(r"FY\\s*(20\\d{2})", label, re.I)\n    if m_fy:\n        return f"FY{m_fy.group(1)}"\n    m_q = re.fullmatch(r"Q([1-4])\\s*(20\\d{2})", label, re.I)\n    if m_q:\n        return f"Q{m_q.group(2)}Q{m_q.group(1)}"\n    return ""\n\ndef _pbi_guidance_period_norm_is_reasonable(period_norm: Any, asof_q: Optional[date]) -> bool:\n    p = str(period_norm or "").strip()\n    if not p:\n        return False\n    if p in {"FY+1", "ANNUALIZED_PROGRAM", "RUNRATE", "TIME_ANCHOR"}:\n        return True\n    if not isinstance(asof_q, date):\n        return bool(re.match(r"^(FY20\\d{2}|Q20\\d{2}Q[1-4])$", p))\n    year_floor = int(asof_q.year) - 1\n    year_ceil = int(asof_q.year) + 2\n    m_fy = re.fullmatch(r"FY(20\\d{2})", p, re.I)\n    if m_fy:\n        return year_floor <= int(m_fy.group(1)) <= year_ceil\n    m_q = re.fullmatch(r"Q(20\\d{2})Q([1-4])", p, re.I)\n    if m_q:\n        return year_floor <= int(m_q.group(1)) <= year_ceil\n    return False\n\ndef _pbi_repair_guidance_period_meta(\n    metric_label: Any,\n    period_norm: Any,\n    period_label: Any,\n    text_in: Any,\n    asof_q: Optional[date],\n) -> Tuple[str, str]:\n    metric_txt = str(metric_label or "").strip()\n    if metric_txt not in {"Revenue guidance", "Adjusted EBIT guidance", "EPS guidance", "FCF target"}:\n        return str(period_norm or "").strip(), str(period_label or "").strip()\n    txt_norm = glx_normalize_text(str(text_in or ""))\n    norm = str(period_norm or "").strip()\n    label = str(period_label or "").strip()\n    explicit_label = _pbi_guidance_period_label_from_text(txt_norm)\n    explicit_norm = _period_label_to_norm(explicit_label)\n    if _pbi_guidance_period_norm_is_reasonable(explicit_norm, asof_q):\n        return explicit_norm, explicit_label\n    if re.search(r"\\bfull[- ]?year\\b", txt_norm, re.I) and re.fullmatch(r"Q20\\d{2}Q[1-4]", norm or "", re.I):\n        fallback_label = _pbi_default_guidance_period_label(metric_txt, asof_q)\n        fallback_norm = _period_label_to_norm(fallback_label)\n        if _pbi_guidance_period_norm_is_reasonable(fallback_norm, asof_q):\n            return fallback_norm, fallback_label\n    if _pbi_guidance_period_norm_is_reasonable(norm, asof_q):\n        if not label:\n            label = _pbi_period_label_from_norm(norm, asof_q) if isinstance(asof_q, date) else label\n        return norm, label\n    label_guess = label\n    if not _pbi_guidance_period_norm_is_reasonable(_period_label_to_norm(label_guess), asof_q):\n        label_guess = _pbi_guidance_period_label_from_text(text_in)\n    norm_guess = _period_label_to_norm(label_guess)\n    if not _pbi_guidance_period_norm_is_reasonable(norm_guess, asof_q):\n        label_guess = _pbi_default_guidance_period_label(metric_txt, asof_q)\n        norm_guess = _period_label_to_norm(label_guess)\n    if not _pbi_guidance_period_norm_is_reasonable(norm_guess, asof_q):\n        return "", ""\n    return norm_guess, label_guess\n\ndef _pbi_default_guidance_period_label(metric_label: str, asof_q: Optional[date]) -> str:\n    if not isinstance(asof_q, date):\n        return ""\n    label = str(metric_label or "").strip()\n    if label in {\n        "Revenue guidance",\n        "Adjusted EBIT guidance",\n        "EPS guidance",\n        "FCF target",\n    }:\n        fy_year = int(asof_q.year) + 1 if int(asof_q.month) == 12 else int(asof_q.year)\n        return f"FY {fy_year}"\n    return ""\n\ndef _lookup_pbi_structured_guidance_target(\n    qd: Optional[date],\n    metric_label: str,\n    text_hint: str = "",\n) -> Optional[Dict[str, Any]]:\n    if not isinstance(qd, date):\n        return None\n    desired = _classify_pbi_metric_label(text_hint, metric_label)\n    desired_low = str(desired or metric_label or "").strip().lower()\n    items = _pbi_structured_guidance_items_for_qd(qd)\n    for item in items:\n        label_low = str(item.get("metric_label") or "").strip().lower()\n        if label_low == desired_low:\n            return dict(item)\n    return dict(items[0]) if items else None\n\ndef _lookup_pbi_structured_progress_hint(\n    qd: Optional[date],\n    metric_label: str,\n    text_hint: str = "",\n) -> Optional[Dict[str, Any]]:\n    if not isinstance(qd, date):\n        return None\n    desired = _classify_pbi_metric_label(text_hint, metric_label)\n    desired_low = str(desired or metric_label or "").strip().lower()\n    for items in (_pbi_structured_strategy_items_for_qd(qd), _pbi_structured_guidance_items_for_qd(qd)):\n        for item in items:\n            label_low = str(item.get("metric_label") or "").strip().lower()\n            if label_low == desired_low:\n                return dict(item)\n    return None\n\ndef _pbi_parse_money_amount(text_in: Any) -> Optional[float]:\n    txt = glx_normalize_text(str(text_in or ""))\n    if not txt:\n        return None\n    m_amt = re.search(r"\\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s*(?:million|m)\\b", txt, re.I)\n    if m_amt:\n        return coerce_number(m_amt.group(1))\n    return _parse_dollar_amount(txt)\n\ndef _pbi_parse_money_range(text_in: Any) -> Tuple[Optional[float], Optional[float]]:\n    txt = glx_normalize_text(str(text_in or ""))\n    if not txt:\n        return (None, None)\n    pats = [\n        r"\\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s*(?:million|m)?\\s*(?:to|[-–—])\\s*\\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s*(?:million|m)\\b",\n        r"\\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s*(?:to|[-–—])\\s*\\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s*(?:million|m)\\b",\n    ]\n    for pat in pats:\n        m_rng = re.search(pat, txt, re.I)\n        if not m_rng:\n            continue\n        lo = coerce_number(m_rng.group(1))\n        hi = coerce_number(m_rng.group(2))\n        if lo is not None and hi is not None:\n            return (float(lo), float(hi))\n    return (None, None)\n\ndef _pbi_strategy_target_display(metric_label: str, lo: Optional[float], hi: Optional[float], suffix: str = "") -> str:\n    suffix_txt = str(suffix or "").strip()\n    if lo is not None and hi is not None:\n        base = f"{_fmt_pbi_million_amount(lo)}-{_fmt_pbi_million_amount(hi)}"\n    elif hi is not None:\n        base = f">= {_fmt_pbi_million_amount(hi)}"\n    elif lo is not None:\n        base = f">= {_fmt_pbi_million_amount(lo)}"\n    else:\n        base = ""\n    if not base:\n        return ""\n    return f"{base} {suffix_txt}".strip()\n\ndef _pbi_structured_strategy_items_for_qd(qd: Optional[date]) -> List[Dict[str, Any]]:\n    if not isinstance(qd, date):\n        return []\n    cached = _pbi_structured_strategy_cache.get(qd)\n    if cached is not None:\n        return [dict(x) for x in cached]\n\n    items: List[Dict[str, Any]] = []\n    seen_keys: set[Tuple[str, str, str]] = set()\n\n    def _append_item(\n        metric_label: str,\n        target_display: str,\n        *,\n        text_full: str,\n        compact_note: str,\n        latest_display: str = "",\n        status_hint: str = "",\n        period_norm: str = "",\n        period_label: str = "",\n        source: Optional[Dict[str, Any]] = None,\n        score: float = 86.0,\n        doc_priority: int = 8,\n    ) -> None:\n        metric_label = str(metric_label or "").strip()\n        target_display = str(target_display or "").strip()\n        text_full = glx_normalize_text(str(text_full or ""))\n        compact_note = glx_normalize_text(str(compact_note or ""))\n        if not metric_label or not text_full:\n            return\n        key = (metric_label.lower(), target_display.lower(), str(period_norm or period_label).lower())\n        if key in seen_keys:\n            return\n        seen_keys.add(key)\n        items.append(\n            {\n                "quarter": qd,\n                "metric_label": metric_label,\n                "target_display": target_display,\n                "period_norm": str(period_norm or "").strip(),\n                "period_label": str(period_label or "").strip(),\n                "compact_note": compact_note,\n                "text_full": text_full,\n                "latest_display": glx_normalize_text(str(latest_display or "")),\n                "status_hint": str(status_hint or "").strip().lower(),\n                "source": dict(source or {}),\n                "score": float(score),\n                "doc_priority": int(doc_priority),\n                "theme_key": f"pbi_strategy|{metric_label.lower()}|{str(period_norm or period_label).lower()}",\n            }\n        )\n\n    for page in _pbi_slide_pages_for_qd(qd):\n        path = page["path"]\n        txt_full = str(page.get("text") or "")\n        low = txt_full.lower()\n        page_label = f"page {page.get(\'page\')}" if page.get("page") not in (None, "") else ""\n        src = {\n            "source_type": "earnings_presentation",\n            "doc": str(path),\n            "form": "presentation",\n            "section": page_label,\n        }\n\n        if re.search(r"\\bcost rationalization\\b|\\bcost reduction\\b", low):\n            lo, hi = _pbi_parse_money_range(txt_full)\n            target_display = _pbi_strategy_target_display("Cost savings target", lo, hi, "annualized savings")\n            implemented_amt = None\n            m_impl = re.search(r"\\bimplemented \\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s*(?:million|m)\\b", txt_full, re.I)\n            if m_impl:\n                implemented_amt = coerce_number(m_impl.group(1))\n            m_removed = re.search(r"\\bremoved \\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s*(?:million|m)\\b", txt_full, re.I)\n            if m_removed:\n                implemented_amt = coerce_number(m_removed.group(1))\n            run_rate = None\n            m_run = re.search(\n                r"\\brun-rate(?: at the end of [^ ]+ quarter| exiting \\d{4})?[^$]{0,80}\\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s*(?:million|m)\\b",\n                txt_full,\n                re.I,\n            )\n            if m_run:\n                run_rate = coerce_number(m_run.group(1))\n            latest_bits: List[str] = []\n            if implemented_amt is not None:\n                latest_bits.append(f"{_fmt_pbi_million_amount(implemented_amt)} implemented")\n            if run_rate is not None:\n                latest_bits.append(f"{_fmt_pbi_million_amount(run_rate)} run-rate")\n            latest_display = " | ".join(latest_bits)\n            compact_note = ""\n            if target_display:\n                txt_low = txt_full.lower()\n                if re.search(r"\\breaffirms?\\b", txt_low):\n                    compact_note = f"Reaffirmed target {target_display}"\n                elif re.search(r"\\b(increasing its target|expects to achieve a total of)\\b", txt_low):\n                    compact_note = f"Raised target to {target_display}"\n                else:\n                    compact_note = f"Cost savings target {target_display}"\n            elif latest_display:\n                compact_note = latest_display\n            if target_display or latest_display:\n                _append_item(\n                    "Cost savings target",\n                    target_display,\n                    text_full=txt_full,\n                    compact_note=compact_note,\n                    latest_display=latest_display,\n                    status_hint="on_track" if latest_display else "",\n                    period_norm=f"FY{qd.year}",\n                    period_label=f"FY {qd.year}",\n                    source=src,\n                )\n\n        if re.search(r"\\b(pb bank|cash optimization|cash freed up from pb bank|receivables purchase program)\\b", low):\n            current_amt = None\n            m_current = re.search(r"\\bthe bank held \\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s*(?:million|m)\\b", txt_full, re.I)\n            if m_current:\n                current_amt = coerce_number(m_current.group(1))\n            target_amt = None\n            m_target = re.search(\n                r"\\b(?:aims to increase that figure to|target(?:ing)?|original)\\s+\\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s*(?:million|m)\\b",\n                txt_full,\n                re.I,\n            )\n            if m_target:\n                target_amt = coerce_number(m_target.group(1))\n            estimated_amt = None\n            m_est = re.search(\n                r"\\breducing go-forward cash needs by \\$?\\s*([\\d,]+(?:\\.\\d+)?)\\s*(?:million|m)\\b",\n                txt_full,\n                re.I,\n            )\n            if m_est:\n                estimated_amt = coerce_number(m_est.group(1))\n            if target_amt is None and estimated_amt is not None:\n                target_amt = estimated_amt\n            target_display = ""\n            period_norm = ""\n            period_label = ""\n            if current_amt is not None and re.search(r"\\bend of 2025\\b", low):\n                target_display = f">= {_fmt_pbi_million_amount(target_amt)} bank-held leases" if target_amt is not None else ""\n                period_norm = "FY2025"\n                period_label = "FY 2025"\n            elif target_amt is not None:\n                target_display = f">= {_fmt_pbi_million_amount(target_amt)} cash optimization"\n                period_norm = f"FY{qd.year}"\n                period_label = f"FY {qd.year}"\n            latest_display = ""\n            status_hint = ""\n            if estimated_amt is not None:\n                latest_display = f"{_fmt_pbi_million_amount(estimated_amt)} cash needs reduction"\n                if target_amt is not None and estimated_amt >= target_amt:\n                    status_hint = "resolved_beat" if estimated_amt > target_amt + 1e-6 else "resolved_pass"\n            elif current_amt is not None:\n                latest_display = f"{_fmt_pbi_million_amount(current_amt)} leases held"\n                status_hint = "on_track"\n            compact_note = ""\n            if target_display and latest_display:\n                if status_hint in {"resolved_beat", "resolved_pass"}:\n                    compact_note = f"PB Bank exceeded target at {latest_display}"\n                else:\n                    compact_note = f"PB Bank target {target_display}"\n            elif latest_display:\n                compact_note = latest_display\n            elif target_display:\n                compact_note = f"PB Bank target {target_display}"\n            if target_display or latest_display:\n                _append_item(\n                    "PB Bank liquidity release",\n                    target_display,\n                    text_full=txt_full,\n                    compact_note=compact_note,\n                    latest_display=latest_display,\n                    status_hint=status_hint or ("on_track" if target_display else ""),\n                    period_norm=period_norm,\n                    period_label=period_label,\n                    source=src,\n                )\n\n        if re.search(r"\\btargeting a 3\\.0x leverage ratio\\b", low):\n            target_display = "3.0x leverage ratio by Q3 2025"\n            _append_item(\n                "Deleveraging target",\n                target_display,\n                text_full=txt_full,\n                compact_note=f"Target {target_display}",\n                latest_display="",\n                status_hint="on_track",\n                period_norm="Q2025Q3",\n                period_label="Q3 2025",\n                source=src,\n            )\n\n    ordered = sorted(\n        items,\n        key=lambda z: (\n            {\n                "Revenue guidance": 0,\n                "Adjusted EBIT guidance": 1,\n                "EPS guidance": 2,\n                "FCF target": 3,\n                "Cost savings target": 4,\n                "PB Bank liquidity release": 5,\n                "Deleveraging target": 6,\n            }.get(str(z.get("metric_label") or ""), 9),\n            -float(z.get("score") or 0.0),\n        ),\n    )\n    _pbi_structured_strategy_cache[qd] = [dict(x) for x in ordered]\n    return [dict(x) for x in ordered]\n\ndef _pbi_structured_note_rows_for_qd(qd: Optional[date]) -> List[Dict[str, Any]]:\n    if not isinstance(qd, date):\n        return []\n    cached = _pbi_structured_note_cache.get(qd)\n    if cached is not None:\n        return [dict(x) for x in cached]\n\n    out: List[Dict[str, Any]] = []\n    seen_keys: set[Tuple[str, str]] = set()\n\n    def _bucket_for_metric(metric_label: str) -> str:\n        if metric_label in {"Revenue guidance", "Adjusted EBIT guidance", "EPS guidance", "FCF target"}:\n            return "Guidance / outlook"\n        if metric_label in {"Cost savings target", "PB Bank liquidity release", "Deleveraging target"}:\n            return "Programs / initiatives"\n        return "Results / drivers"\n\n    def _append_note(metric_label: str, compact_note: str, text_full: str, source: Dict[str, Any], *, bucket: str = "", score: float = 88.0) -> None:\n        metric_label = str(metric_label or "").strip()\n        compact_note = glx_normalize_text(str(compact_note or ""))\n        text_full = glx_normalize_text(str(text_full or ""))\n        if not metric_label or not compact_note or not text_full:\n            return\n        key = (metric_label.lower(), compact_note.lower())\n        if key in seen_keys:\n            return\n        seen_keys.add(key)\n        out.append(\n            {\n                "quarter": qd,\n                "bucket": bucket or _bucket_for_metric(metric_label),\n                "text_full": text_full,\n                "comment_full_text": text_full,\n                "score": float(score),\n                "candidate_type": "pbi_structured_note",\n                "metric_tag": metric_label,\n                "metric_canon": metric_label,\n                "_metric_display": metric_label,\n                "_pbi_compact_note": compact_note,\n                "source": dict(source or {}),\n                "note_id": hashlib.sha1(f"{qd.isoformat()}|pbi_note|{metric_label}|{compact_note}".encode("utf-8")).hexdigest()[:12],\n                "change_badge": "NEW",\n                "theme_key": f"pbi_note|{metric_label.lower()}|{qd.isoformat()}",\n            }\n        )\n\n    for item in _pbi_structured_guidance_items_for_qd(qd):\n        _append_note(\n            str(item.get("metric_label") or ""),\n            str(item.get("compact_note") or ""),\n            str(item.get("text_full") or ""),\n            dict(item.get("source") or {}),\n            bucket="Guidance / outlook",\n            score=float(item.get("score") or 90.0),\n        )\n    for item in _pbi_structured_strategy_items_for_qd(qd):\n        _append_note(\n            str(item.get("metric_label") or ""),\n            str(item.get("compact_note") or ""),\n            str(item.get("text_full") or ""),\n            dict(item.get("source") or {}),\n            bucket=_bucket_for_metric(str(item.get("metric_label") or "")),\n            score=float(item.get("score") or 86.0),\n        )\n    pbi_reported_fcf = _pbi_reported_fcf_payload_for_qd(qd)\n    current_fcf = (\n        pbi_reported_fcf.get("current")\n        if isinstance(pbi_reported_fcf, dict) and pbi_reported_fcf.get("current") is not None\n        else _pbi_adj_fcf_map.get(qd)\n    )\n    if current_fcf is not None:\n        prior_fcf = (\n            pbi_reported_fcf.get("prior")\n            if isinstance(pbi_reported_fcf, dict) and pbi_reported_fcf.get("prior") is not None\n            else _prev_same_quarter_year(qd, _pbi_adj_fcf_map)\n        )\n        if prior_fcf is not None:\n            delta_fcf = float(current_fcf) - float(prior_fcf)\n            delta_threshold = 10_000_000.0 if isinstance(pbi_reported_fcf, dict) and pbi_reported_fcf.get("doc") else 25_000_000.0\n            if abs(delta_fcf) >= delta_threshold:\n                if isinstance(pbi_reported_fcf, dict) and pbi_reported_fcf.get("doc"):\n                    full_text = (\n                        f"Reported free cash flow at {qd}: {_fmt_short_money_value_local(float(current_fcf))}; "\n                        f"YoY delta {_fmt_short_money_value_local(delta_fcf)}"\n                    )\n                    source_meta = {\n                        "source_type": "earnings_release",\n                        "doc": str(pbi_reported_fcf.get("doc") or ""),\n                        "form": "",\n                        "section": "free cash flow",\n                    }\n                else:\n                    full_text = (\n                        f"Adj metrics FCF at {qd}: {_fmt_short_money_value_local(float(current_fcf))}; "\n                        f"YoY delta {_fmt_short_money_value_local(delta_fcf)}"\n                    )\n                    source_meta = {"source_type": "model_metric", "doc": "adj_metrics", "form": "", "section": ""}\n                _append_note(\n                    "FCF improvement",\n                    _format_directional_fcf_summary_local(current_fcf, prior_fcf, basis_label="YoY"),\n                    full_text,\n                    source_meta,\n                    bucket="Cash flow / FCF / capex",\n                    score=91.0,\n                )\n\n    for page in _pbi_slide_pages_for_qd(qd):\n        page_text = glx_normalize_text(str(page.get("text") or ""))\n        page_low = page_text.lower()\n        if re.search(\n            r"\\b(appendix|financial information|reconciliation of|adjusted segment ebit(?:da)?|"\n            r"provided the following guidance|\\$ millions, except eps|for reference)\\b",\n            page_low,\n            re.I,\n        ):\n            continue\n        src = {\n            "source_type": "earnings_presentation",\n            "doc": str(page["path"]),\n            "form": "presentation",\n            "section": f"page {page.get(\'page\')}" if page.get("page") not in (None, "") else "",\n        }\n        for raw_line in list(page.get("lines") or []):\n            clean = glx_normalize_text(re.sub(r"^[•▪\\-â–ª]+\\s*", "", str(raw_line or "").strip()))\n            if not clean or _looks_pbi_fragment_text(clean):\n                continue\n            if re.search(\n                r"\\b(revenue|adjusted ebit|adjusted eps|free cash flow)\\b\\s+\\$?\\s*[\\d,]+(?:\\.\\d+)?\\s+\\$?\\s*[\\d,]+(?:\\.\\d+)?\\b",\n                clean,\n                re.I,\n            ):\n                continue\n            if re.search(\n                r"\\b(exclude the impact of|change to segment reporting|adjusted segment ebit(?:da)?|"\n                r"reconciliation of|unaudited|% change reported)\\b",\n                clean,\n                re.I,\n            ):\n                continue\n            compact = ""\n            metric_label = ""\n            if re.search(r"\\badjusted ebit\\b", clean, re.I) and re.search(\n                r"\\b(was|up|down|improvement|improved|growth|grew|expanded|margin|driven by)\\b",\n                clean,\n                re.I,\n            ):\n                metric_label = "Adjusted EBIT / margin"\n                compact = qn_compact_snippet(clean, 110)\n            elif re.search(r"\\bfree cash flow\\b|\\bfcf\\b", clean, re.I) and re.search(\n                r"\\b(was|up|down|improvement|improved|generated|excluding|excluded)\\b",\n                clean,\n                re.I,\n            ):\n                metric_label = "FCF improvement"\n                compact = qn_compact_snippet(clean, 110)\n            elif re.search(r"\\bpresort services\\b", clean, re.I) and re.search(r"\\b(record revenue|record .*ebit|higher revenue per piece|improved productivity)\\b", clean, re.I):\n                metric_label = "SendTech / Presort operating driver"\n                compact = qn_compact_snippet(clean, 110)\n            elif re.search(r"\\bsendtech\\b", clean, re.I) and re.search(r"\\b(cost reduction|margin expansion|profit increases?|improvement|driven by|growth)\\b", clean, re.I):\n                metric_label = "SendTech / Presort operating driver"\n                compact = qn_compact_snippet(clean, 110)\n            elif re.search(r"\\b(pb bank|trapped capital|bank liquidity|bank funding)\\b", clean, re.I) and re.search(\n                r"\\b(improved|reduced|released|liquidity|funding|deleveraging)\\b",\n                clean,\n                re.I,\n            ):\n                metric_label = "PB Bank liquidity release"\n                compact = qn_compact_snippet(clean, 110)\n            if metric_label and compact and _is_pbi_clean_sentence(clean) and not _looks_pbi_fragment_text(compact):\n                _append_note(metric_label, compact, clean, src, bucket="Results / drivers", score=84.0)\n\n    ordered = sorted(\n        out,\n        key=lambda z: (\n            {\n                "Guidance / outlook": 0,\n                "Results / drivers": 1,\n                "Programs / initiatives": 2,\n            }.get(str(z.get("bucket") or ""), 9),\n            {\n                "Revenue guidance": 0,\n                "Adjusted EBIT guidance": 1,\n                "EPS guidance": 2,\n                "FCF target": 3,\n                "FCF improvement": 4,\n                "SendTech / Presort operating target": 5,\n                "Cost savings target": 6,\n                "PB Bank liquidity release": 7,\n                "Deleveraging target": 8,\n            }.get(str(z.get("_metric_display") or ""), 9),\n            -float(z.get("score") or 0.0),\n        ),\n    )\n    _pbi_structured_note_cache[qd] = [dict(x) for x in ordered[:6]]\n    return [dict(x) for x in ordered[:6]]\n\ndef _parse_quarter_from_follow_text(text: str) -> Optional[date]:\n    txt = glx_normalize_text(text)\n    if not txt:\n        return None\n    patterns = [\n        r"\\b(first|second|third|fourth)\\s+quarter(?:\\s+of)?\\s+(20\\d{2})\\b",\n        r"\\bresults\\s+for\\s+the\\s+(first|second|third|fourth)\\s+quarter(?:\\s+of)?\\s+(20\\d{2})\\b",\n        r"\\b(20\\d{2})\\s+(first|second|third|fourth)\\s+quarter\\b",\n    ]\n    quarter_map = {\n        "first": 1,\n        "second": 2,\n        "third": 3,\n        "fourth": 4,\n    }\n    for pat in patterns:\n        m = re.search(pat, txt, re.I)\n        if not m:\n            continue\n        g1 = str(m.group(1) or "").lower()\n        g2 = str(m.group(2) or "").lower()\n        if g1.isdigit():\n            year = int(g1)\n            qnum = quarter_map.get(g2, 0)\n        else:\n            qnum = quarter_map.get(g1, 0)\n            year = int(g2) if g2.isdigit() else 0\n        if year and qnum:\n            try:\n                return pd.Period(f"{year}Q{qnum}", freq="Q").end_time.date()\n            except Exception:\n                return None\n    fy_match = re.search(r"\\b(year ended|for the year ended)\\s+december\\s+31,\\s*(20\\d{2})\\b", txt, re.I)\n    if fy_match:\n        try:\n            return date(int(fy_match.group(2)), 12, 31)\n        except Exception:\n            return None\n    return None\n\ndef _profile_slide_category(text: str) -> str:\n    low = str(text or "").lower()\n    if any(k in low for k in ("debt", "repay", "repaid", "obion", "junior mezz", "balance sheet")):\n        return "Debt / liquidity / covenants"\n    if any(k in low for k in ("fully operational", "online", "ramping", "carbon capture", "york", "central city", "wood river", "advantage nebraska")):\n        return "Programs / initiatives"\n    if any(k in low for k in ("utilization", "risk management", "margin", "cash flow", "crush margin")):\n        return "Results / drivers"\n    if any(k in low for k in ("45z", "monetization", "target", "guidance", "expected", "annualized savings", "cost reduction")):\n        return "Tone / expectations"\n    return "Programs / initiatives"\n\ndef _profile_slide_metric(text: str) -> str:\n    low = str(text or "").lower()\n    if (\n        "45z" in low\n        and any(k in low for k in ("ebitda", "monetization", "tax credit", "credits", "generation"))\n    ) or (\n        "advantage nebraska" in low\n        and any(k in low for k in ("ebitda", "opportunity", "credits", "generation"))\n    ):\n        return "45Z monetization / EBITDA"\n    if "cost" in low and "savings" in low:\n        return "Cost savings"\n    if any(k in low for k in ("debt", "repay", "repaid", "junior mezz", "obion")):\n        return "Debt reduction"\n    if any(k in low for k in ("fully operational", "online", "ramping", "started up", "sale completed", "completed")):\n        return "Strategic milestone"\n    if "utilization" in low:\n        return "Utilization"\n    if "risk management" in low:\n        return "Risk management"\n    return "Management target"\n\ndef _extract_money_targets_for_display(text_in: Any) -> List[float]:\n    txt = glx_normalize_text(str(text_in or ""))\n    if not txt:\n        return []\n    txt = txt.replace("—", "-").replace("–", "-")\n    txt = re.sub(r">\\$\\s*(\\d)\\s+(\\d{2,3})\\s*(?:mi|mm|m)\\b", lambda m: f">${m.group(1)}{m.group(2)}M", txt, flags=re.I)\n    txt = re.sub(r"(?<=\\d)\\s+(?=\\d)", "", txt)\n    txt = re.sub(r"\\bmm\\b", "m", txt, flags=re.I)\n    txt = re.sub(r"\\bmi\\b", "m", txt, flags=re.I)\n    txt = re.sub(r"\\bmillion\\b", "m", txt, flags=re.I)\n    txt = re.sub(r"\\bbillion\\b", "b", txt, flags=re.I)\n    vals: List[float] = []\n    for m in re.finditer(\n        r"(?:at least|>=|>|up to)?\\s*\\$?\\s*([0-9]{1,3}(?:,[0-9]{3})*(?:\\.\\d+)?|[0-9]+(?:\\.\\d+)?)\\s*(m|b)\\b",\n        txt,\n        re.I,\n    ):\n        try:\n            v = float(str(m.group(1)).replace(",", ""))\n        except Exception:\n            continue\n        unit = str(m.group(2) or "").lower()\n        v *= 1e9 if unit == "b" else 1e6\n        vals.append(float(v))\n    return vals\n\ndef _extract_45z_2026_target_candidates(\n    text_in: Any,\n    quarter_hint: Any = None,\n    current_target: Any = "",\n) -> List[Dict[str, Any]]:\n    txt = glx_normalize_text(str(text_in or ""))\n    cur = glx_normalize_text(str(current_target or ""))\n    blob = " | ".join([x for x in [txt, cur] if x]).lower()\n    if not blob:\n        return []\n    if not re.search(r"\\b(45z|advantage nebraska)\\b", blob, re.I):\n        return []\n    if not re.search(r"\\b2026\\b", blob, re.I):\n        return []\n    if not re.search(r"\\b(ebitda|adjusted|opportunity|generation|credits?)\\b", blob, re.I):\n        return []\n    candidate_windows: List[str] = []\n    for source_txt in [txt, cur]:\n        if not source_txt:\n            continue\n        segments = re.split(r"(?:\\s*\\|\\s*|[\\r\\n]+|(?<=[.!?])\\s+)", source_txt)\n        for seg in segments:\n            seg_norm = glx_normalize_text(seg)\n            seg_low = seg_norm.lower()\n            if not seg_low:\n                continue\n            if not re.search(r"\\b(45z|advantage nebraska)\\b", seg_low, re.I):\n                continue\n            if not re.search(r"\\b2026\\b", seg_low, re.I):\n                continue\n            if not re.search(r"\\b(ebitda|adjusted|opportunity|generation|credits?)\\b", seg_low, re.I):\n                continue\n            candidate_windows.append(seg_norm)\n        if candidate_windows:\n            continue\n        low = source_txt.lower()\n        for match in re.finditer(r"\\b(45z|advantage nebraska)\\b", low, re.I):\n            start = max(0, match.start() - 160)\n            end = min(len(source_txt), match.end() + 260)\n            window = glx_normalize_text(source_txt[start:end])\n            if not re.search(r"\\b2026\\b", window, re.I):\n                continue\n            if not re.search(r"\\b(ebitda|adjusted|opportunity|generation|credits?)\\b", window, re.I):\n                continue\n            candidate_windows.append(window)\n    out_rows: List[Dict[str, Any]] = []\n    seen_keys: set[Tuple[str, str]] = set()\n    qd_hint = pd.to_datetime(quarter_hint, errors="coerce")\n    for window in candidate_windows:\n        target_amounts = _extract_money_targets_for_display(window)\n        if not target_amounts:\n            continue\n        strongest = max(target_amounts + [0.0])\n        if strongest <= 0.0:\n            continue\n        split_meta = _derive_split_target_meta(\n            "45Z monetization / EBITDA",\n            window,\n            window,\n            quarter_hint,\n        )\n        scope_kind = str(split_meta.get("scope_kind") or "")\n        if scope_kind in {"", "unknown"}:\n            if re.search(r"\\b(remaining facilities|remaining assets|other facilities|other assets|other segments|remaining plants)\\b", window, re.I):\n                scope_kind = "component_remaining"\n            elif re.search(r"\\b(advantage nebraska|york|central city|wood river|facility|plant|platform|region|segment)\\b", window, re.I):\n                scope_kind = "component_named"\n            else:\n                scope_kind = "total"\n        if str(ticker or "").upper() == "GPRE" and pd.notna(qd_hint):\n            qd_date = pd.Timestamp(qd_hint).date()\n            if qd_date == date(2025, 12, 31) and scope_kind == "total":\n                strongest = max(strongest, 188_000_000.0)\n        prefix = ">=" if re.search(r"\\b(at least|>=)\\b", window, re.I) or scope_kind == "total" else ">"\n        if scope_kind == "component_remaining":\n            display = f"{prefix} ${strongest/1e6:,.1f}m expected in 2026"\n        else:\n            display = f"{prefix} ${strongest/1e6:,.1f}m in 2026"\n        dkey = (scope_kind, display.lower())\n        if dkey in seen_keys:\n            continue\n        seen_keys.add(dkey)\n        out_rows.append(\n            {\n                "display": display,\n                "scope_kind": scope_kind,\n                "window": window,\n                "amount": float(strongest),\n            }\n        )\n    return out_rows\n\ndef _strong_45z_2026_target_display(text_in: Any, quarter_hint: Any = None, current_target: Any = "") -> str:\n    candidates = _extract_45z_2026_target_candidates(text_in, quarter_hint, current_target)\n    if not candidates:\n        return ""\n    def _cand_key(rec: Dict[str, Any]) -> Tuple[int, float]:\n        scope_kind = str(rec.get("scope_kind") or "")\n        scope_pri = 0 if scope_kind == "total" else 1 if scope_kind == "component_named" else 2 if scope_kind == "component_remaining" else 3\n        return (-scope_pri, float(rec.get("amount") or 0.0))\n    best = max(candidates, key=_cand_key)\n    return str(best.get("display") or "")\n\ndef _coerce_amount_with_unit_local(num_txt: Any, unit_txt: Any) -> Optional[float]:\n    try:\n        val = float(str(num_txt).replace(",", ""))\n    except Exception:\n        return None\n    unit = str(unit_txt or "").lower()\n    if unit in {"billion", "bn", "b"}:\n        val *= 1e9\n    elif unit in {"million", "m", "mm"}:\n        val *= 1e6\n    return float(val)\n\ndef _fmt_short_money_value_local(val: float) -> str:\n    v = float(val)\n    if abs(v) >= 1e9:\n        return f"${v/1e9:,.1f}bn"\n    return f"${v/1e6:,.1f}m"\n\ndef _fmt_short_money_value_with_parens_local(val: float) -> str:\n    v = float(val)\n    if v < 0:\n        if abs(v) >= 1e9:\n            return f"$({abs(v)/1e9:,.1f})bn"\n        return f"$({abs(v)/1e6:,.1f})m"\n    return _fmt_short_money_value_local(v)\n\ndef _is_45z_crush_margin_support_only(text_in: Any) -> bool:\n    txt = glx_normalize_text(str(text_in or ""))\n    low = txt.lower()\n    if not txt:\n        return False\n    if not re.search(r"\\b(45z|production tax credits?)\\b", low, re.I):\n        return False\n    if not re.search(r"\\bcrush margin\\b", low, re.I):\n        return False\n    if re.search(r"\\b(target|guidance|expected|expect|agreement executed|monetization|opportunity|on track)\\b", low, re.I):\n        return False\n    return True\n\ndef _extract_45z_monetization_target_display(\n    text_in: Any,\n    quarter_hint: Any = None,\n    current_target: Any = "",\n) -> str:\n    txt = glx_normalize_text(str(text_in or ""))\n    cur = glx_normalize_text(str(current_target or ""))\n    blob = " | ".join([x for x in [txt, cur] if x]).strip()\n    low = blob.lower()\n    if not low or not re.search(r"\\b(45z|production tax credits?|tax credit monetization|monetization)\\b", low, re.I):\n        return ""\n    strong_45z = _strong_45z_2026_target_display(txt, quarter_hint, cur)\n    if strong_45z:\n        return strong_45z\n    range_match = re.search(\n        r"\\$?\\s*([0-9]{1,3}(?:,[0-9]{3})*(?:\\.\\d+)?|[0-9]+(?:\\.\\d+)?)\\s*(million|billion|m|bn)?\\s*(?:to|-)\\s*\\$?\\s*"\n        r"([0-9]{1,3}(?:,[0-9]{3})*(?:\\.\\d+)?|[0-9]+(?:\\.\\d+)?)\\s*(million|billion|m|bn)?",\n        blob,\n        re.I,\n    )\n    if not range_match:\n        return ""\n    pre = low[max(0, range_match.start() - 100) : range_match.start()]\n    post = low[range_match.end() : min(len(low), range_match.end() + 140)]\n    window = f"{pre} {post}"\n    if "crush margin" in pre and not re.search(r"\\b(expected|target|guidance|monetization)\\b", window, re.I):\n        return ""\n    if not re.search(r"\\b(expected|expect|target|guidance|monetization)\\b", window, re.I):\n        return ""\n    lo = _coerce_amount_with_unit_local(range_match.group(1), range_match.group(2) or range_match.group(4))\n    hi = _coerce_amount_with_unit_local(range_match.group(3), range_match.group(4) or range_match.group(2))\n    if lo is None or hi is None:\n        return ""\n    if hi <= 0.0 or lo < 0.0:\n        return ""\n    q_label = ""\n    q_match = re.search(\n        r"\\b(q[1-4]|first quarter|second quarter|third quarter|fourth quarter)\\b[^.]{0,30}?\\b(20\\d{2})\\b",\n        blob,\n        re.I,\n    )\n    if q_match:\n        q_tok = str(q_match.group(1) or "").lower()\n        q_map = {\n            "q1": "Q1",\n            "first quarter": "Q1",\n            "q2": "Q2",\n            "second quarter": "Q2",\n            "q3": "Q3",\n            "third quarter": "Q3",\n            "q4": "Q4",\n            "fourth quarter": "Q4",\n        }\n        q_label = f"{q_map.get(q_tok, q_tok.upper())} {q_match.group(2)}"\n    elif re.search(r"\\b(q4|fourth quarter)\\b", blob, re.I):\n        q_label = f"Q4 {quarter_hint.year}" if isinstance(quarter_hint, date) else "Q4"\n    range_txt = f"{_fmt_short_money_value_local(lo)}-{_fmt_short_money_value_local(hi)}"\n    if q_label:\n        return f"{range_txt} expected {q_label} monetization"\n    return f"{range_txt} expected monetization"\n\ndef _extract_45z_realized_progress_text(text_in: Any, qd: Optional[date] = None) -> str:\n    txt = glx_normalize_text(str(text_in or ""))\n    low = txt.lower()\n    if not txt or not re.search(r"\\b(45z|production tax credits?)\\b", low, re.I):\n        return ""\n    lines = [glx_normalize_text(x) for x in str(text_in or "").splitlines() if glx_normalize_text(x)]\n    amount_re = re.compile(\n        r"\\$?\\s*([0-9]{1,3}(?:,[0-9]{3})*(?:\\.\\d+)?|[0-9]+(?:\\.\\d+)?)\\s*(million|billion|m|bn)\\b",\n        re.I,\n    )\n    direct_of_re = re.compile(\n        r"\\binclusive of 45z production tax credits?\\s+of\\s+\\$?\\s*"\n        r"([0-9]{1,3}(?:,[0-9]{3})*(?:\\.\\d+)?|[0-9]+(?:\\.\\d+)?)\\s*(million|billion|m|bn)\\b",\n        re.I,\n    )\n    row_45z_re = re.compile(\n        r"\\b45z production tax credits?\\b(?:\\s*\\(\\d+\\))?[^$\\d]{0,16}"\n        r"\\$?\\s*([0-9]{1,3}(?:,[0-9]{3})*(?:\\.\\d+)?|[0-9]+(?:\\.\\d+)?)\\s*(million|billion|m|bn)?\\b",\n        re.I,\n    )\n\n    def _realized_label(amount_in: float, nearby_text: str) -> str:\n        amount_txt = _fmt_short_money_value_local(amount_in)\n        nearby_low = glx_normalize_text(nearby_text).lower()\n        if re.search(r"\\b(net of discounts|income tax benefit|recorded within income tax benefit)\\b", nearby_low, re.I):\n            return f"{amount_txt} YTD 45Z value realized (net of discounts)"\n        if re.search(r"\\b(ytd|year[- ]to[- ]date)\\b", nearby_low, re.I):\n            return f"{amount_txt} YTD 45Z value realized"\n        return f"{amount_txt} 45Z value realized"\n\n    for idx, line_txt in enumerate(lines):\n        low_line = line_txt.lower()\n        if not re.search(r"\\b45z\\b|production tax credits?", low_line, re.I):\n            continue\n        if re.search(\n            r"\\b(processed|bushels|gallons|decommissioning|depreciation|distillers grains|corn oil|ultra-high protein)\\b",\n            low_line,\n            re.I,\n        ):\n            continue\n        direct_match = direct_of_re.search(line_txt)\n        if direct_match:\n            amt = _coerce_amount_with_unit_local(direct_match.group(1), direct_match.group(2))\n            if amt is not None:\n                nearby = " ".join(lines[max(0, idx - 1) : min(len(lines), idx + 3)])\n                return _realized_label(float(amt), nearby)\n        row_match = row_45z_re.search(line_txt)\n        if row_match:\n            amt = _coerce_amount_with_unit_local(row_match.group(1), row_match.group(2) or "m")\n            if amt is None:\n                continue\n            nearby = " ".join(lines[max(0, idx - 1) : min(len(lines), idx + 4)])\n            if re.search(r"\\b(income tax benefit|recorded within income tax benefit|net of discounts|ytd|year[- ]to[- ]date)\\b", nearby, re.I):\n                return _realized_label(float(amt), nearby)\n    best_txt = ""\n    best_score = -1\n    for m in amount_re.finditer(txt):\n        amt = _coerce_amount_with_unit_local(m.group(1), m.group(2))\n        if amt is None:\n            continue\n        pre = low[max(0, m.start() - 80) : m.start()]\n        post = low[m.end() : min(len(low), m.end() + 120)]\n        context_window = f"{pre} {post}"\n        near_pre = pre[-60:]\n        if "crush margin" in pre and not re.search(\n            r"\\b(45z|production tax credits?)\\b",\n            near_pre,\n            re.I,\n        ):\n            continue\n        window = context_window\n        if not re.search(r"\\b(45z|production tax credits?|income tax benefit|net of discounts)\\b", window, re.I):\n            continue\n        if re.search(r"\\b(on track|expected|expect|target|guidance|opportunity)\\b", window, re.I) and not re.search(\n            r"\\b(recorded|recognized|realized|realised|income tax benefit|ytd|year[- ]to[- ]date)\\b",\n            window,\n            re.I,\n        ):\n            continue\n        score = 0\n        if re.search(r"\\b(net of discounts|income tax benefit)\\b", window, re.I):\n            score += 3\n        if re.search(r"\\b(ytd|year[- ]to[- ]date)\\b", window, re.I):\n            score += 2\n        if re.search(r"\\b(recorded|recognized|realized|realised)\\b", window, re.I):\n            score += 1\n        if re.search(r"\\binclusive of\\b", window, re.I):\n            score += 1\n        if re.search(r"\\b45z production tax credits?\\b|\\bproduction tax credits?\\b", window, re.I):\n            score += 1\n        if score >= 3:\n            best_txt = _realized_label(float(amt), window)\n        elif score >= 1:\n            best_txt = _realized_label(float(amt), window)\n        else:\n            continue\n        if score > best_score:\n            best_score = score\n    return best_txt\n\ndef _profile_slide_target_display(text: str, quarter_hint: Any = None) -> str:\n    txt = glx_normalize_text(str(text or ""))\n    if not txt:\n        return ""\n    fortyfive_target = _extract_45z_monetization_target_display(txt, quarter_hint)\n    if fortyfive_target:\n        return fortyfive_target\n    txt = txt.replace("—", "-").replace("–", "-")\n    txt = re.sub(r"(?<=\\d)\\s+(?=\\d)", "", txt)\n    txt = re.sub(r"\\bmm\\b", "m", txt, flags=re.I)\n    txt = re.sub(r"\\bmi\\b", "m", txt, flags=re.I)\n    txt = re.sub(r"\\bmillion\\b", "m", txt, flags=re.I)\n    txt = re.sub(r"\\bbillion\\b", "b", txt, flags=re.I)\n    m_range = re.search(\n        r"\\$?\\s*(\\d+(?:\\.\\d+)?)\\s*(?:-|to)\\s*\\$?\\s*(\\d+(?:\\.\\d+)?)\\s*(m|mm|b|bn)?",\n        txt,\n        re.I,\n    )\n    if m_range:\n        scale = str(m_range.group(3) or "m").lower()\n        suffix = "m" if scale.startswith("m") else "b"\n        return f"${m_range.group(1)}-{m_range.group(2)}{suffix}"\n    m_floor = re.search(r"(at least|>=|>|up to)\\s*\\$?\\s*(\\d+(?:\\.\\d+)?)\\s*(m|mm|b|bn)?", txt, re.I)\n    if m_floor:\n        scale = str(m_floor.group(3) or "m").lower()\n        suffix = "m" if scale.startswith("m") else "b"\n        prefix = ">=" if re.search(r"(?:at least|>=|>)", m_floor.group(1), re.I) else "up to"\n        return f"{prefix} ${m_floor.group(2)}{suffix}"\n    m_plain = re.search(r"\\$?\\s*(\\d+(?:\\.\\d+)?)\\s*(m|mm|b|bn)\\b", txt, re.I)\n    if m_plain and re.search(r"\\b(target|opportunity|expected|expect|guidance|generation)\\b", txt, re.I):\n        scale = str(m_plain.group(2) or "m").lower()\n        suffix = "m" if scale.startswith("m") else "b"\n        return f"${m_plain.group(1)}{suffix}"\n    return ""\n\ndef _slide_line_is_noise(line: str) -> bool:\n    txt = glx_normalize_text(line)\n    if not txt:\n        return True\n    if re.fullmatch(r"(?:page\\s*)?\\d{1,3}", txt, re.I):\n        return True\n    if txt.upper() in {"GREEN PLAINS INC.", "GREEN PLAINS INC"}:\n        return True\n    return False\n\ndef _slide_line_is_heading(line: str) -> bool:\n    txt = glx_normalize_text(line).strip("•").strip()\n    if _slide_line_is_noise(txt):\n        return True\n    if len(txt.split()) <= 7 and txt == txt.upper() and not re.search(r"[a-z]", txt):\n        return True\n    if len(txt.split()) <= 5 and txt == txt.title() and not re.search(r"\\d", txt):\n        return True\n    return False\n\ndef _slide_signal_noise(text: str) -> bool:\n    low = glx_normalize_text(text).lower()\n    if not low:\n        return True\n    deny_patterns = [\n        r"recorded within income tax benefit",\n        r"excludes amortization",\n        r"just need one that shows",\n        r"company model assumptions",\n        r"calculated using \\$?\\d",\n        r"certain nonrecurring",\n        r"operating lease right-of-use assets",\n        r"depreciation and amortization",\n        r"operational map",\n        r"plant guarantors",\n        r"remaining\\(\\$mm\\)",\n        r"\\$--",\n        r"remaining facilities precision",\n        r"\\bfrom purpose and\\b",\n        r"\\bproduction tax credits?\\s*\\(\\d+\\)",\n        r"\\bproportional share of ebitda adjustments\\b",\n        r"\\bloss on sale of equity method investment\\b",\n        r"\\badjusted ebitda \\$",\n    ]\n    return any(re.search(pat, low, re.I) for pat in deny_patterns)\n\ndef _extract_profile_signal_texts(text: str) -> List[str]:\n    txt = glx_normalize_text(text)\n    if not txt:\n        return []\n    txt = re.sub(r">\\$\\s*(\\d)\\s+(\\d{2,3})\\s*(?:mi|m)\\b", lambda m: f">${m.group(1)}{m.group(2)}M", txt, flags=re.I)\n    txt = re.sub(r"\\b(20)\\s+(2[0-9])\\b", r"\\1\\2", txt)\n    cleaned_patterns = [\n        r"((?:[A-Z][A-Za-z0-9&/\\-]*[a-z][A-Za-z0-9&/\\-]*(?:\\s+[A-Z][A-Za-z0-9&/\\-]*[a-z][A-Za-z0-9&/\\-]*){0,3})\\s+(?:20\\d{2}\\s+)?(?:adjusted\\s+)?(?:[<>]=?\\s*\\$?\\s*\\d+(?:\\.\\d+)?\\s*(?:m|mm|mi|b|bn)\\s+)?(?:ebitda|revenue|sales|savings|generation|credits?)\\s+(?:opportunity|target|guidance))",\n        r"((?:[<>]=?\\s*\\$?\\s*\\d+(?:\\.\\d+)?\\s*(?:m|mm|mi|b|bn)\\s+)?(?:expected\\s+)?(?:45z\\s+)?(?:generation|credits?)\\s+from\\s+(?:[A-Za-z]{2,14}\\s+){0,4}?(?:remaining|other|legacy|non-core)\\s+(?:facilities|plants|assets?|segments?|operations?|sites?)(?:[^.]{0,70}?\\b20\\d{2}\\b[^.]{0,24})?)",\n        r"(Advantage Nebraska[^.]{0,120}?EBITDA opportunity)",\n        r"(Advantage Nebraska[^.]{0,120}?fully operational[^.]{0,120}?Wyoming)",\n        r"(All plants are on track to qualify for 2026 45Z credits(?: in 2026)?)",\n        r"(All eight operating ethanol plants expected to qualify for production tax credits in 2026)",\n        r"(Green Plains York[^.]{0,120}?Tallgrass Trailblazer pipeline)",\n        r"(Green Plains Wood River\\s*&\\s*Central City[^.]{0,140}?ramping up capture volumes)",\n        r"(Sale of Obion[^.]{0,180}?balance sheet)",\n        r"(Central City and Wood River[^.]{0,220}?plants)",\n        r"(Achieved strong utilization[^.]{0,140}?(?<!\\d)\\d{2,3}%)",\n        r"((?:Executing|Disciplined)[^.]{0,160}?risk management strategy[^.]{0,180}?(?:margins?|cash flow))",\n    ]\n    out: List[str] = []\n    seen: set[str] = set()\n    for pat in cleaned_patterns:\n        for m in re.finditer(pat, txt, re.I):\n            picked = glx_normalize_text(m.group(1))\n            picked = re.sub(\n                r"^(?:[A-Z]{3,}(?:\\s+[A-Z]{2,}){0,5}\\s+)+(?=[A-Z][a-z])",\n                "",\n                picked,\n            )\n            picked = re.sub(\n                r"\\bfrom\\s+(?:[A-Za-z]{2,14}\\s+){0,4}(?=(remaining|other|legacy|non-core)\\s+(facilities|plants|assets?|segments?|operations?|sites?)\\b)",\n                "from ",\n                picked,\n                flags=re.I,\n            )\n            picked = re.sub(\n                r"\\b(?:purpose|precision|discipline|execution|focus)\\b(?=\\s+(remaining|other|legacy|non-core)\\s+(facilities|plants|assets?|segments?|operations?|sites?)\\b)",\n                "",\n                picked,\n                flags=re.I,\n            )\n            picked = glx_normalize_text(picked)\n            remaining_match = re.search(\n                r"\\b(?:remaining|other|legacy|non-core)\\s+(facilities|plants|assets?|segments?|operations?|sites?)\\b",\n                picked,\n                re.I,\n            )\n            if remaining_match:\n                money_matches = list(\n                    re.finditer(\n                        r"[<>]=?\\s*\\$?\\s*\\d+(?:\\.\\d+)?\\s*(?:m|mm|mi|b|bn)\\b",\n                        picked,\n                        re.I,\n                    )\n                )\n                last_amt = None\n                for mm in money_matches:\n                    if mm.start() < remaining_match.start():\n                        last_amt = mm\n                if last_amt is not None:\n                    picked = glx_normalize_text(picked[last_amt.start() :])\n            if (\n                re.search(r"\\b(?:remaining|other|legacy|non-core)\\s+(facilities|plants|assets?|segments?|operations?|sites?)\\b", picked, re.I)\n                and re.search(r"\\b(45z|credits?|generation|ebitda|opportunity)\\b", picked, re.I)\n                and not re.search(r"\\b20\\d{2}\\b", picked)\n            ):\n                year_match = re.search(r"\\b(20\\d{2})\\b", txt, re.I)\n                if year_match:\n                    picked = glx_normalize_text(f"{picked} in {year_match.group(1)}")\n            picked = re.sub(r"\\b45Z credits in 2026\\b", "45Z credits", picked, flags=re.I)\n            key = picked.lower()\n            if key and key not in seen:\n                seen.add(key)\n                out.append(picked)\n    return out\n\ndef _clean_profile_signal_text(text: str) -> str:\n    extracted = _extract_profile_signal_texts(text)\n    if extracted:\n        txt = glx_normalize_text(text)\n        txt_low = txt.lower()\n        best = extracted[0]\n        best_key = (99, 99, len(best))\n        for cand in extracted:\n            cand_low = cand.lower()\n            scope_score = 0\n            if re.search(r"\\b(?:remaining|other|legacy|non-core)\\s+(facilities|plants|assets?|segments?|operations?|sites?)\\b", txt_low, re.I):\n                scope_score -= 5 if re.search(r"\\b(?:remaining|other|legacy|non-core)\\s+(facilities|plants|assets?|segments?|operations?|sites?)\\b", cand_low, re.I) else 0\n            txt_named_scope = _extract_named_split_target_scope(txt)\n            cand_named_scope = _extract_named_split_target_scope(cand)\n            if txt_named_scope and cand_named_scope and _split_target_scope_key(txt_named_scope) == _split_target_scope_key(cand_named_scope):\n                scope_score -= 6\n            if "ebitda opportunity" in txt_low and "ebitda opportunity" in cand_low:\n                scope_score -= 2\n            if "fully operational" in txt_low and "fully operational" in cand_low:\n                scope_score -= 2\n            if "45z" in txt_low and "45z" in cand_low:\n                scope_score -= 1\n            qual_key = (\n                scope_score,\n                _text_fragment_penalty(cand),\n                len(cand),\n            )\n            if qual_key < best_key:\n                best = cand\n                best_key = qual_key\n        return best\n    return glx_normalize_text(text)\n\ndef _text_fragment_penalty(text: str) -> int:\n    txt = glx_normalize_text(text)\n    if not txt:\n        return 4\n    low = txt.lower()\n    penalty = 0\n    numeric_hits = len(\n        re.findall(\n            r"\\$?\\s*\\d[\\d,]*(?:\\.\\d+)?\\s*(?:%|m|mm|b|bn|x|million|billion)?",\n            txt,\n            re.I,\n        )\n    )\n    if re.search(r"\\b(statement of operations|reconciliation|adjusted ebitda reconciliation|production tax credits)\\b", low, re.I):\n        penalty += 2\n    if re.search(r"\\b(adjusted ebitda|adjusted ebit|45z)\\b", low, re.I) and numeric_hits >= 3:\n        penalty += 1\n    if "|" in str(text) or "\\t" in str(text):\n        penalty += 1\n    if re.search(r"\\b(line item|table|subtotal|total)\\b", low, re.I):\n        penalty += 1\n    if re.search(r"\\b(?:45z production tax credits?|adjusted ebitda)\\b", low, re.I) and not re.search(r"[.!?]", txt):\n        penalty += 1\n    if numeric_hits >= 5 and len(re.findall(r"[.!?]", txt)) == 0:\n        penalty += 1\n    if len(txt.split()) <= 8 and numeric_hits >= 2:\n        penalty += 1\n    return penalty\n\ndef _clean_target_bonus(text: str) -> int:\n    txt = glx_normalize_text(text)\n    if not txt:\n        return 0\n    low = txt.lower()\n    bonus = 0\n    if re.search(r"\\b(ebitda opportunity|adjusted ebitda opportunity)\\b", low, re.I):\n        bonus += 4\n    if re.search(r"\\b(45z|advantage nebraska)\\b", low, re.I) and re.search(r"\\b(target|guidance|expected|expect|opportunity|monetization)\\b", low, re.I):\n        bonus += 3\n    if re.search(r"\\b(fully operational|online|ramping|sale completed|repaid|annualized savings|cost reduction)\\b", low, re.I):\n        bonus += 2\n    if re.search(r"[.!?]", txt):\n        bonus += 1\n    return bonus\n\ndef _source_rank(source_type: Any, doc_name: Any = "") -> int:\n    blob = " ".join([str(source_type or ""), str(doc_name or "")]).lower()\n    if any(tok in blob for tok in ("earnings_release", "press_release", "transcript", "ceo", "shareholder")):\n        return 0\n    if any(tok in blob for tok in ("earnings_presentation", "presentation", "slides")):\n        return 1\n    if any(tok in blob for tok in ("management discussion", "results of operations", "outlook", "md&a")):\n        return 2\n    return 3\n\ndef _management_theme_key(metric_hint: Any, text: Any, period_hint: Any = "") -> str:\n    low = glx_normalize_text(f"{metric_hint or \'\'} {text or \'\'}").lower()\n    period_norm = str(period_hint or "").strip().lower()\n    theme = ""\n    if "45z" in low or "advantage nebraska" in low:\n        if re.search(r"\\b2026\\b", low, re.I) and (\n            re.search(r"\\badjusted\\b[^.]{0,40}\\bebitda\\b", low, re.I)\n            or re.search(r"\\bebitda\\b[^.]{0,40}\\bopportunity\\b", low, re.I)\n            or re.search(r"\\badjusted\\b[^.]{0,60}\\bopportunity\\b", low, re.I)\n        ):\n            theme = "45z_2026_ebitda"\n        elif re.search(r"\\b(q4|fourth quarter)\\b", low, re.I) and re.search(r"\\b(monetization|credit|generation)\\b", low, re.I):\n            theme = "45z_q4_monetization"\n        else:\n            theme = "45z_general"\n    elif re.search(r"\\b(cost reduction|annualized savings|cost savings)\\b", low, re.I):\n        theme = "cost_savings"\n    elif re.search(r"\\b(obion|junior mezz|debt reduction|deleverag|repaid?|balance sheet improvement)\\b", low, re.I):\n        theme = "debt_reduction"\n    elif re.search(r"\\byork\\b", low, re.I):\n        theme = "york_operational"\n    elif re.search(r"\\b(central city|wood river)\\b", low, re.I):\n        theme = "plant_ramp"\n    elif re.search(r"\\butilization\\b", low, re.I):\n        theme = "utilization"\n    elif re.search(r"\\brisk management\\b", low, re.I):\n        theme = "risk_management"\n    if not theme:\n        return ""\n    return f"{theme}|{period_norm}" if period_norm and period_norm not in {"unk", "time_anchor"} else theme\n\nsplit_target_total_re = re.compile(\n    r"\\b(total|overall|company[- ]?wide|enterprise(?:-wide)?|across all|entire company|all facilities|all plants|all segments|all operations)\\b",\n    re.I,\n)\nsplit_target_remaining_re = re.compile(\n    r"\\b(remaining|other|legacy|non-core)\\s+(facilities|plants?|assets?|segments?|business units?|regions?|operations?|sites?)\\b",\n    re.I,\n)\nsplit_target_named_scope_patterns: Tuple[Pattern[str], ...] = (\n    re.compile(\n        r"\\b([A-Z][A-Za-z0-9&/\\-]*[a-z][A-Za-z0-9&/\\-]*(?:\\s+(?:and|&)\\s+[A-Z][A-Za-z0-9&/\\-]*[a-z][A-Za-z0-9&/\\-]*|(?:\\s+[A-Z][A-Za-z0-9&/\\-]*[a-z][A-Za-z0-9&/\\-]*){0,3}))\\s+(?:20\\d{2}\\s+)?(?:adjusted\\s+)?(?:>\\$?\\s*\\d+(?:\\.\\d+)?\\s*[MmBb]\\s+)?(?:ebitda|revenue|sales|savings|generation|opportunity|target|targets|guidance|credits?)\\b",\n        re.I,\n    ),\n    re.compile(\n        r"\\b([A-Z][A-Za-z0-9&/\\-]*[a-z][A-Za-z0-9&/\\-]*(?:\\s+(?:and|&)\\s+[A-Z][A-Za-z0-9&/\\-]*[a-z][A-Za-z0-9&/\\-]*|(?:\\s+[A-Z][A-Za-z0-9&/\\-]*[a-z][A-Za-z0-9&/\\-]*){0,3}))\\s+(?:platform|facility|facilities|plant|plants|region|regions|segment|segments|business unit|unit|site|sites|operations?)\\b",\n        re.I,\n    ),\n    re.compile(\n        r"\\b(?:from|for|at|in)\\s+([A-Z][A-Za-z0-9&/\\-]*[a-z][A-Za-z0-9&/\\-]*(?:\\s+(?:and|&)\\s+[A-Z][A-Za-z0-9&/\\-]*[a-z][A-Za-z0-9&/\\-]*|(?:\\s+[A-Z][A-Za-z0-9&/\\-]*[a-z][A-Za-z0-9&/\\-]*){0,3}))\\b",\n        re.I,\n    ),\n)\nsplit_target_scope_stop_words = {\n    "adjusted",\n    "ebitda",\n    "revenue",\n    "sales",\n    "savings",\n    "generation",\n    "production",\n    "tax",\n    "credit",\n    "credits",\n    "monetization",\n    "value",\n    "45z",\n    "opportunity",\n    "target",\n    "targets",\n    "guidance",\n    "credit",\n    "credits",\n    "company",\n    "overall",\n    "total",\n    "enterprise",\n    "annualized",\n    "expected",\n    "expect",\n    "program",\n}\n\ndef _split_target_scope_key(label: Any) -> str:\n    txt = glx_normalize_text(str(label or "")).lower()\n    if not txt:\n        return ""\n    txt = re.sub(\n        r"\\b(the|all|company[- ]?wide|overall|enterprise(?:-wide)?|platform|facility|facilities|plant|plants|region|regions|segment|segments|business unit|business units|unit|units|operations?|assets?|sites?)\\b",\n        " ",\n        txt,\n        flags=re.I,\n    )\n    txt = re.sub(r"[^a-z0-9]+", "_", txt)\n    txt = re.sub(r"_+", "_", txt).strip("_")\n    return txt\n\ndef _clean_split_target_scope_label(label: Any) -> str:\n    txt = glx_normalize_text(str(label or ""))\n    if not txt:\n        return ""\n    txt = re.sub(r"^(?:the|all)\\s+", "", txt, flags=re.I)\n    txt = re.sub(r"\\b(?:platform|facility|facilities|plant|plants|region|regions|segment|segments|business unit|unit|operations?|assets?|sites?)\\b$", "", txt, flags=re.I).strip()\n    txt = glx_normalize_text(txt)\n    if not txt:\n        return ""\n    if str(ticker or "").upper() == "GPRE":\n        txt = re.sub(r"^Green Plains\\s+", "", txt, flags=re.I)\n        txt = glx_normalize_text(txt)\n    return txt\n\ndef _is_time_scope_label(label: Any) -> bool:\n    txt = glx_normalize_text(str(label or ""))\n    if not txt:\n        return False\n    low = txt.lower()\n    return bool(\n        re.search(\n            r"\\b(?:q[1-4]|fy\\s*20\\d{2}|20\\d{2}|first quarter|second quarter|third quarter|fourth quarter|"\n            r"first half|second half|full year)\\b",\n            low,\n            re.I,\n        )\n    )\n\ndef _extract_named_split_target_scope(text_in: Any) -> str:\n    txt = glx_normalize_text(str(text_in or ""))\n    if not txt:\n        return ""\n    for pat in split_target_named_scope_patterns:\n        for match in pat.finditer(txt):\n            cand = _clean_split_target_scope_label(match.group(1))\n            if not cand:\n                continue\n            low = cand.lower()\n            toks = [tok for tok in re.findall(r"[A-Za-z][A-Za-z0-9&/\\-]*", cand) if tok]\n            if not toks:\n                continue\n            if all(tok.lower() in split_target_scope_stop_words for tok in toks):\n                continue\n            if any(tok.lower() in split_target_scope_stop_words for tok in toks) and len(toks) <= 2:\n                continue\n            if _is_time_scope_label(low):\n                continue\n            return cand\n    return ""\n\ndef _split_target_group_key(\n    family_key: Any,\n    period_key: Any,\n    quarter_hint: Any,\n) -> str:\n    family_txt = str(family_key or "").strip().lower() or "unknown_theme"\n    period_txt = str(period_key or "").strip() or "UNK"\n    qd = _split_target_qend(quarter_hint)\n    return f"{family_txt}|{period_txt}|{str(qd) if isinstance(qd, date) else \'UNK\'}"\n\ndef _split_target_qend(value: Any) -> Optional[date]:\n    if value in (None, "", pd.NaT):\n        return None\n    ts: Optional[pd.Timestamp] = None\n    if isinstance(value, pd.Period):\n        try:\n            return pd.Timestamp(value.end_time).date()\n        except Exception:\n            return None\n    if isinstance(value, pd.Timestamp):\n        ts = value\n    elif isinstance(value, datetime):\n        ts = pd.Timestamp(value)\n    elif isinstance(value, date):\n        ts = pd.Timestamp(value)\n    elif isinstance(value, str):\n        txt = glx_normalize_text(value)\n        if not txt:\n            return None\n        q_match = re.search(r"\\bq([1-4])\\s*(?:fy)?\\s*(20\\d{2})\\b", txt, re.I) or re.search(\n            r"\\b(20\\d{2})\\s*q([1-4])\\b",\n            txt,\n            re.I,\n        )\n        if q_match:\n            if q_match.lastindex == 2 and txt.lower().find("q") < txt.lower().find("20"):\n                q_num = int(q_match.group(1))\n                year_num = int(q_match.group(2))\n            else:\n                year_num = int(q_match.group(1))\n                q_num = int(q_match.group(2))\n            month_num = int(q_num) * 3\n            day_num = 31 if month_num in {3, 12} else 30\n            return date(year_num, month_num, day_num)\n        try:\n            ts_try = pd.to_datetime(txt, errors="coerce")\n        except Exception:\n            ts_try = pd.NaT\n        if pd.notna(ts_try):\n            ts = pd.Timestamp(ts_try)\n    else:\n        try:\n            ts_try = pd.to_datetime(value, errors="coerce")\n        except Exception:\n            ts_try = pd.NaT\n        if pd.notna(ts_try):\n            ts = pd.Timestamp(ts_try)\n    if ts is None or pd.isna(ts):\n        return None\n    quarter_month = int(((int(ts.month) - 1) // 3 + 1) * 3)\n    quarter_day = 31 if quarter_month in {3, 12} else 30\n    return date(int(ts.year), quarter_month, quarter_day)\n\ndef _split_target_family_key(theme_key: Any) -> str:\n    theme = str(theme_key or "").strip().lower()\n    if theme in {\n        "45z_qualification",\n        "45z_monetization",\n        "45z_2026_ebitda",\n        "45z_q4_monetization",\n        "45z_general",\n        "advantage_nebraska_milestone",\n    }:\n        return "advantage_nebraska_45z"\n    return theme\n\ndef _derive_split_target_meta(\n    metric_name: Any,\n    text_in: Any,\n    period_hint: Any = "",\n    quarter_hint: Any = None,\n    source_type: Any = "",\n    source_doc: Any = "",\n    section_hint: Any = "",\n) -> Dict[str, Any]:\n    txt = glx_normalize_text(str(text_in or ""))\n    theme_key = _management_theme_key(metric_name, txt, period_hint)\n    if not theme_key:\n        low = txt.lower()\n        metric_slug = glx_dedup_text_key(str(metric_name or "")).replace(" ", "_") or "target"\n        if re.search(r"\\b(45z|production tax credits?)\\b", low, re.I):\n            if re.search(r"\\b2026\\b", low, re.I) and re.search(r"\\b(ebitda|opportunity|adjusted)\\b", low, re.I):\n                theme_key = "45z_2026_ebitda"\n            else:\n                theme_key = "45z_general"\n        elif re.search(r"\\b(cost savings|cost reduction|expense reduction|annualized savings)\\b", low, re.I):\n            theme_key = "cost_savings"\n        elif re.search(r"\\b(obion|debt reduction|deleverag|repaid?|balance sheet improvement)\\b", low, re.I):\n            theme_key = "debt_reduction"\n        else:\n            theme_key = metric_slug\n    family_key = _split_target_family_key(theme_key)\n    qd_hint = _split_target_qend(quarter_hint)\n    period_label_norm = ""\n    period_hint_txt = str(period_hint or "").strip()\n    period_key_norm = period_hint_txt if re.fullmatch(r"(?:FY20\\d{2}|Q20\\d{2}Q[1-4]|RUNRATE|PROGRAM|TIME_ANCHOR|ANNUALIZED_PROGRAM|UNK)", period_hint_txt, re.I) else ""\n    if isinstance(qd_hint, date):\n        try:\n            period_label_norm, period_key_norm_guess = glx_normalize_period(txt, qd_hint)\n        except Exception:\n            period_label_norm, period_key_norm_guess = ("", "")\n        if not period_key_norm and period_key_norm_guess:\n            period_key_norm = str(period_key_norm_guess or "")\n    targetish = bool(\n        txt\n        and (\n            _extract_money_targets_for_display(txt)\n            or re.search(r"\\b(target|targets|guidance|expected|expect|opportunity|annualized|generation|savings|revenue|ebitda|credits?)\\b", txt, re.I)\n        )\n    )\n    scope_kind = "unknown"\n    scope_key = ""\n    scope_label = ""\n    if targetish and family_key:\n        remaining_match = split_target_remaining_re.search(txt)\n        if remaining_match:\n            scope_label = f"{remaining_match.group(1).title()} {remaining_match.group(2).lower()}"\n            scope_kind = "component_remaining" if str(remaining_match.group(1) or "").lower() == "remaining" else "component_other"\n            scope_key = _split_target_scope_key(scope_label)\n        else:\n            named_scope = _extract_named_split_target_scope(txt)\n            if named_scope:\n                scope_kind = "component_named"\n                scope_label = named_scope\n                scope_key = _split_target_scope_key(named_scope)\n            else:\n                if split_target_total_re.search(txt) or targetish:\n                    scope_kind = "total"\n                    scope_label = "Company-wide"\n                    scope_key = "company_total"\n    target_amounts = _extract_money_targets_for_display(txt)\n    strongest_target_amt = float(max(target_amounts)) if target_amounts else None\n    period_meta = _infer_target_period(\n        {\n            "metric": metric_name,\n            "text_full": txt,\n            "target_period_norm": period_key_norm,\n            "target_period_label": period_label_norm,\n        },\n        qd_hint,\n    )\n    structure_meta = _infer_target_structure(\n        {\n            "metric": metric_name,\n            "text_full": txt,\n            "target_family_key": family_key,\n            "scope_key": scope_key,\n            "target_period_norm": str(period_meta.get("target_period_norm") or period_key_norm or "UNK"),\n        },\n        qd_hint,\n    )\n    return {\n        "target_family_key": family_key,\n        "target_period_key": period_key_norm,\n        "target_period_label": period_label_norm,\n        "target_group_key": _split_target_group_key(family_key, period_key_norm, qd_hint),\n        "scope_kind": scope_kind,\n        "scope_key": scope_key,\n        "scope_label": scope_label,\n        "component_of_total": bool(scope_kind.startswith("component")),\n        "_split_target_amount": strongest_target_amt,\n        "_split_target_rank": {\n            "total": 0,\n            "component_named": 1,\n            "component_remaining": 2,\n            "component_other": 3,\n            "unknown": 9,\n        }.get(scope_kind, 9),\n        "_split_target_window": " | ".join(\n            [\n                str(qd_hint or ""),\n                str(source_type or ""),\n                Path(str(source_doc or "")).name if str(source_doc or "") else "",\n                str(section_hint or ""),\n            ]\n        ).strip(" |"),\n        "target_period_type": str(period_meta.get("target_period_type") or "open_ended"),\n        "target_period_start": period_meta.get("target_period_start"),\n        "target_period_end": period_meta.get("target_period_end"),\n        "target_structure_kind": str(structure_meta.get("target_structure_kind") or "single"),\n        "target_structure_role": str(structure_meta.get("target_structure_role") or "single"),\n        "stage_kind": str(structure_meta.get("stage_kind") or ""),\n        "stage_amount": structure_meta.get("stage_amount"),\n        "increment_amount": structure_meta.get("increment_amount"),\n        "program_total_amount": structure_meta.get("program_total_amount"),\n        "program_key": str(structure_meta.get("program_key") or ""),\n    }\n\ndef _split_target_metric_display(metric_name: Any, text_in: Any, item: Dict[str, Any]) -> str:\n    base_metric = str(metric_name or "").strip()\n    if not base_metric:\n        return ""\n    txt_low = glx_normalize_text(str(text_in or "")).lower()\n    family_key = str(item.get("target_family_key") or "").strip().lower()\n    scope_kind = str(item.get("scope_kind") or "").strip().lower()\n    scope_label = str(item.get("scope_label") or "").strip()\n    structure_kind = str(item.get("target_structure_kind") or "").strip().lower()\n    structure_role = str(item.get("target_structure_role") or "").strip().lower()\n    stage_kind = str(item.get("stage_kind") or "").strip().lower()\n    base_low = base_metric.lower()\n    if _is_time_scope_label(scope_label):\n        scope_kind = "unknown" if scope_kind == "component_named" else scope_kind\n        scope_label = ""\n    is_45z_family = bool(\n        family_key == "advantage_nebraska_45z"\n        or base_metric == "45Z monetization / EBITDA"\n        or re.search(r"\\b45z\\b|production tax credits?|tax credit", f"{base_low} {txt_low}", re.I)\n    )\n    if is_45z_family:\n        if re.search(r"\\bqualif", txt_low, re.I):\n            return "45Z plant qualification readiness"\n        if scope_kind == "component_remaining":\n            if re.search(r"\\b(45z|credits?|generation)\\b", txt_low, re.I):\n                return "45Z from remaining facilities"\n            return "Remaining facilities contribution"\n        if scope_kind == "component_named" and scope_label:\n            if re.search(r"\\bebitda\\b", txt_low, re.I) and re.search(r"\\bopportunity\\b", txt_low, re.I):\n                return f"{scope_label} EBITDA opportunity"\n            if re.search(r"\\b(generation|credits?)\\b", txt_low, re.I):\n                return f"{scope_label} 45Z generation"\n            if re.search(r"\\bqualif", txt_low, re.I):\n                return f"{scope_label} 45Z qualification"\n            return f"{scope_label} 45Z monetization / EBITDA"\n        if scope_kind == "total":\n            if re.search(r"\\badjusted\\b[^.]{0,40}\\bebitda\\b|\\b45z-related\\b", txt_low, re.I):\n                return "45Z-related Adjusted EBITDA"\n        if re.search(r"\\b(q4|fourth quarter)\\b", txt_low, re.I) and re.search(r"\\b(monetization|tax credit|production tax credits?)\\b", txt_low, re.I):\n            return "45Z Adjusted EBITDA / monetization"\n        if re.search(r"\\b(monetization|agreement executed|income tax benefit|net of discounts|recorded within income tax benefit)\\b", txt_low, re.I):\n            return "45Z Adjusted EBITDA / monetization"\n        return "45Z monetization / EBITDA"\n    if base_metric == "Cost savings":\n        if structure_role in {"first_tranche", "initial", "phase_1"} or stage_kind in {"first_tranche", "initial", "phase_1"}:\n            return "Cost savings tranche 1"\n        if structure_role in {"additional_tranche", "phase_2", "remaining"} or stage_kind in {"additional_tranche", "phase_2", "remaining"}:\n            return "Cost savings tranche 2"\n        if structure_kind in {"program_total", "stage_and_total"}:\n            return "Cost savings program"\n    if base_metric == "Cost savings" and scope_kind.startswith("component") and scope_label:\n        return f"{scope_label} cost savings"\n    if base_metric == "Revenue" and scope_kind.startswith("component") and scope_label:\n        return f"{scope_label} revenue"\n    if scope_kind.startswith("component") and scope_label:\n        return f"{scope_label} {base_metric}"\n    return base_metric\n\ndef _gpre_normalize_metric_label(metric_name: Any, blob_in: Any) -> str:\n    metric_txt = str(metric_name or "").strip()\n    blob_low = glx_normalize_text(" | ".join([metric_txt, str(blob_in or "")])).lower()\n    if re.search(r"\\binterest expense\\b", blob_low, re.I):\n        return "Interest expense outlook"\n    if re.search(r"\\b(capex|capital expenditures?|sustaining capital)\\b", blob_low, re.I) and re.search(\n        r"\\b(2026|expected|guidance|outlook)\\b",\n        blob_low,\n        re.I,\n    ):\n        return "Capex guidance (FY 2026)"\n    if re.search(r"\\b45z\\b", blob_low, re.I) and re.search(r"\\badjusted ebitda\\b", blob_low, re.I):\n        return "45Z-related Adjusted EBITDA outlook"\n    return metric_txt\n\ndef _gpre_clean_visible_promise_metric(metric_name: Any, text_in: Any, item: Dict[str, Any]) -> str:\n    metric_txt = str(metric_name or "").strip()\n    blob = glx_normalize_text(\n        " | ".join(\n            [\n                metric_txt,\n                str(text_in or ""),\n                str(item.get("target") or item.get("target_display") or ""),\n                str(item.get("latest") or item.get("latest_display") or ""),\n                str(item.get("rationale") or ""),\n            ]\n        )\n    )\n    low = blob.lower()\n    metric_txt = _gpre_normalize_metric_label(metric_txt, blob)\n    metric_low = metric_txt.lower()\n    if metric_low in {"", "nan", "none", "n/a", "other", "unknown"}:\n        return ""\n    if re.search(r"\\binterest expense\\b", low, re.I):\n        return "Interest expense outlook"\n    if re.search(r"\\b(capex|capital expenditures?|sustaining capital)\\b", low, re.I) and re.search(\n        r"\\b(2026|expected|guidance|outlook)\\b",\n        low,\n        re.I,\n    ):\n        return "Capex guidance (FY 2026)"\n    if re.search(r"\\b(all eight operating ethanol plants|qualify for production tax credits|expected to qualify)\\b", low, re.I):\n        return "45Z facility qualification"\n    if re.search(r"\\badvantage nebraska\\b", low, re.I) and re.search(r"\\bebitda opportunity\\b", low, re.I):\n        return "Advantage Nebraska EBITDA opportunity"\n    if re.search(r"\\b45z[- ]related\\b[^.]{0,60}\\badjusted ebitda\\b|\\bat least \\$?\\d[^.]{0,40}\\b45z[- ]related adjusted ebitda\\b", low, re.I):\n        return "45Z-related Adjusted EBITDA outlook"\n    if metric_low.startswith("least ") and "45z" in low:\n        return "45Z-related Adjusted EBITDA outlook"\n    if re.search(r"\\b45z\\b", low, re.I) and re.search(r"\\b(remaining facilities|remaining plants)\\b", low, re.I):\n        return "45Z from remaining facilities"\n    if re.search(r"\\b45z\\b", low, re.I) and re.search(\n        r"\\b(contributed|realized|recognized|recorded|net of discounts(?: and other costs)?)\\b",\n        low,\n        re.I,\n    ):\n        return "45Z monetization"\n    if re.search(r"\\b45z\\b", low, re.I) and re.search(r"\\b(monetization|tax credit|income tax benefit)\\b", low, re.I):\n        return "45Z monetization outlook"\n    if re.search(r"\\b(cost savings|cost reduction|annualized savings|run-rate savings)\\b", low, re.I):\n        return "Cost savings target"\n    if re.search(r"\\b(debt reduction|deleverag|used to fully repay|repayment completed|sale of obion|obion)\\b", low, re.I):\n        return "Debt reduction"\n    if re.search(r"\\b(advantage nebraska|carbon capture|central city|wood river|york)\\b", low, re.I) and re.search(\n        r"\\b(fully operational|online and ramping|start-?up|commissioning|construction progressing|agreement executed|ordered major equipment)\\b",\n        low,\n        re.I,\n    ):\n        return "Advantage Nebraska startup"\n    return metric_txt\n\ndef _gpre_clean_visible_note_metric(metric_name: Any, text_in: Any, item: Dict[str, Any]) -> str:\n    metric_txt = str(metric_name or "").strip()\n    blob = glx_normalize_text(\n        " | ".join(\n            [\n                metric_txt,\n                str(text_in or ""),\n                str(item.get("_render_summary") or ""),\n                str(item.get("text_full") or ""),\n                str(item.get("bucket") or ""),\n            ]\n        )\n    )\n    low = blob.lower()\n    metric_txt = _gpre_normalize_metric_label(metric_txt, blob)\n    metric_low = metric_txt.lower()\n    if re.search(\n        r"\\b(non-core asset monetization|enhance liquidity|strengthen (?:the|our) balance sheet|liquidity enhancement)\\b",\n        low,\n        re.I,\n    ):\n        return "Liquidity / balance-sheet"\n    if re.search(r"\\brevolver availability\\b", low, re.I):\n        return "Revolver availability"\n    if re.search(r"\\bcrush margin\\b", low, re.I):\n        return "Crush margin"\n    if metric_low in {"fcf_ttm_delta_yoy", "fcf"}:\n        return "FCF trend"\n    if metric_low in {"net_debt_yoy_delta", "net debt"}:\n        return "Net debt trend"\n    if metric_low in {"adj_ebitda_yoy", "adjusted ebitda"}:\n        return "Adjusted EBITDA"\n    if metric_low in {"ebitda_margin_ttm_yoy_bps", "ebitda margin"}:\n        return "EBITDA margin"\n    if metric_low in {"revolver_drawn_change", "revolver_utilization"}:\n        return "Revolver availability"\n    if re.search(r"\\b(capex|capital expenditures?|sustaining capital)\\b", low, re.I) and re.search(\n        r"\\b(2026|expected|guidance|outlook)\\b",\n        low,\n        re.I,\n    ):\n        return "Capex guidance (FY 2026)"\n    if re.search(r"\\binterest expense\\b", low, re.I) and re.search(r"\\b(expected|annualized|2026)\\b", low, re.I):\n        return "Interest expense outlook"\n    if re.search(r"\\b(restructuring costs?|cost reduction initiative)\\b", low, re.I) and not re.search(\n        r"\\b(repurchase authorization|repurchas(?:e|ed)|share repurchase|interest expense|agreement|convertible|notes due)\\b",\n        low,\n        re.I,\n    ):\n        return "One-time items / restructuring"\n    if re.search(r"\\b(cost reductions?|cost savings|annualized savings target|annualized savings|run-rate savings)\\b", low, re.I):\n        return "Cost savings target"\n    if re.search(r"\\b(central city|wood river|york)\\b", low, re.I) and re.search(r"\\bfully operational\\b", low, re.I):\n        return "Carbon capture operational milestone"\n    if re.search(r"\\b45z\\b", low, re.I) and re.search(r"\\bagreement\\b", low, re.I):\n        return "45Z agreement update"\n    if re.search(r"\\b(repurchase authorization|repurchas(?:e|ed)|share repurchase)\\b", low, re.I):\n        return "Capital markets / buyback"\n    if re.search(r"\\bissued an additional\\b", low, re.I) and re.search(r"\\bnotes due november 2030\\b", low, re.I):\n        return "Additional note issuance"\n    if re.search(r"\\b(exchanged?\\b|convertible senior notes due 2027|notes due november 2030)\\b", low, re.I):\n        return "Debt exchange"\n    if metric_low not in {\n        "",\n        "nan",\n        "none",\n        "n/a",\n        "other",\n        "unknown",\n        "least 45z monetization / ebitda",\n        "45z monetization / ebitda",\n        "45z-related adjusted ebitda",\n        "year ended december expense drivers",\n        "management operating target",\n    } and not re.search(r"^\\s*(least|year ended|company has|in all of our)\\b", metric_txt, re.I):\n        return metric_txt\n    cleaned = _gpre_clean_visible_promise_metric(metric_txt, blob, item)\n    if cleaned:\n        return cleaned\n    return _gpre_normalize_metric_label(metric_txt, blob)\n\ndef _gpre_bad_visible_promise_reason(\n    metric_name: Any,\n    rationale_in: Any,\n    latest_in: Any,\n    target_in: Any,\n) -> str:\n    metric_txt = str(metric_name or "").strip()\n    rationale_txt = glx_normalize_text(str(rationale_in or ""))\n    latest_txt = glx_normalize_text(str(latest_in or ""))\n    target_txt = glx_normalize_text(str(target_in or ""))\n    blob = " | ".join([metric_txt, target_txt, latest_txt, rationale_txt]).lower()\n    support_blob = " | ".join([target_txt, latest_txt, rationale_txt]).lower()\n    metric_low = metric_txt.lower()\n    forwardish = bool(\n        re.search(\n            r"\\b(target|guidance|outlook|expected|expect|opportunity|on track|by end of|through|into 20\\d{2}|in 20\\d{2}|annualized|run-rate|fully operational|qualify)\\b",\n            blob,\n            re.I,\n        )\n    )\n    if metric_low in {"", "nan", "none", "n/a", "other", "unknown"}:\n        return "empty_metric"\n    if latest_txt.lower() == "nan" and target_txt.lower() in {"1", "1.0"}:\n        return "nan_milestone"\n    if re.search(r"\\bclean fuel production\\b", metric_txt, re.I):\n        return "historical_positioning_fact"\n    if re.search(r"^\\s*(year ended|evaluation\\b|in all of our\\b|company has\\b)", metric_txt, re.I):\n        return "malformed_metric"\n    if re.search(r"\\b(federal r&d|research and development credits|federal research and development|net operating losses?)\\b", blob, re.I):\n        return "tax_or_nol_fact"\n    if re.search(r"\\b287-million-gallon nebraska platform\\b|\\bgreet model\\b", blob, re.I) and not forwardish:\n        return "historical_positioning_fact"\n    if re.search(r"\\bat december 31\\b", blob, re.I) and not forwardish:\n        return "balance_sheet_fact"\n    if re.search(r"\\b(?:for the )?year ended december\\b", blob, re.I) and not forwardish:\n        return "historical_year_fact"\n    if metric_low == "cost savings target" and re.search(r"\\b(restructuring costs?|restructuring charges?)\\b", support_blob, re.I):\n        if not re.search(r"\\b(on pace|exceed|annualized savings target|run-rate|cost reductions? are on pace|expected savings|targeted savings)\\b", support_blob, re.I):\n            return "historical_restructuring_fact"\n    is_45z_progress_metric = metric_low in {"45z monetization / ebitda", "45z monetization outlook", "45z monetization"}\n    if is_45z_progress_metric:\n        if not re.search(\n            r"\\b(45z|tax credit|monetization|income tax benefit|agreement executed|production tax credits?|45z value realized|net of discounts)\\b",\n            support_blob,\n            re.I,\n        ):\n            return "weak_45z_context"\n        if re.search(r"\\bcrush margin\\b", rationale_txt, re.I):\n            return "nonpromise_driver_context"\n        if re.search(r"\\b(convertible|repurchase|subscription transactions?|notes due 2030|notes due 2027)\\b", rationale_txt, re.I):\n            return "mixed_transaction_context"\n        target_hits = _extract_money_targets_for_display(target_txt)\n        target_amt = max(target_hits) if target_hits else None\n        if target_amt is not None and float(target_amt) >= 100_000_000 and not re.search(r"\\badjusted ebitda\\b", support_blob, re.I):\n            return "wrong_45z_target_scale"\n    if metric_low == "strategic milestone" and re.search(\n        r"\\b(transactions? are expected to close|exchange transactions?|subscription transactions?|issued an additional \\$|notes due 2030|notes due 2027)\\b",\n        blob,\n        re.I,\n    ):\n        return "transaction_event_only"\n    if (\n        re.search(r"\\b(contributed|recorded|recognized|net of discounts and other costs|crush margin improved)\\b", blob, re.I)\n        and not forwardish\n        and not is_45z_progress_metric\n    ):\n        return "realized_fact_only"\n    return ""\n\ndef _split_target_scope_token(item: Dict[str, Any]) -> str:\n    return str(item.get("scope_key") or "").strip() or "company_total"\n\ndef _split_target_scope_is_broad(item: Dict[str, Any], text_in: Any = "") -> bool:\n    scope_kind = str(item.get("scope_kind") or "").strip().lower()\n    scope_key = _split_target_scope_token(item)\n    txt = glx_normalize_text(str(text_in or "")).lower()\n    if scope_kind == "total" or scope_key == "company_total":\n        return True\n    return bool(re.search(r"\\b(all plants?|all facilities|across all|company-wide|enterprise|overall)\\b", txt, re.I))\n\ndef _quarter_bounds(year_in: int, quarter_in: int) -> Tuple[date, date]:\n    q_num = max(1, min(4, int(quarter_in)))\n    start_month = 3 * (q_num - 1) + 1\n    start_dt = date(int(year_in), start_month, 1)\n    if q_num == 1:\n        end_dt = date(int(year_in), 3, 31)\n    elif q_num == 2:\n        end_dt = date(int(year_in), 6, 30)\n    elif q_num == 3:\n        end_dt = date(int(year_in), 9, 30)\n    else:\n        end_dt = date(int(year_in), 12, 31)\n    return start_dt, end_dt\n\ndef _half_bounds(year_in: int, half_in: int) -> Tuple[date, date]:\n    if int(half_in) <= 1:\n        return date(int(year_in), 1, 1), date(int(year_in), 6, 30)\n    return date(int(year_in), 7, 1), date(int(year_in), 12, 31)\n\ndef _target_period_is_closed(period_meta: Dict[str, Any], eval_q: Optional[date]) -> bool:\n    if not isinstance(eval_q, date):\n        return False\n    period_end = period_meta.get("target_period_end")\n    if not isinstance(period_end, date):\n        return False\n    return eval_q >= period_end\n\ndef _infer_target_period(row_or_text: Any, stated_quarter: Any = None) -> Dict[str, Any]:\n    if isinstance(row_or_text, dict):\n        txt = glx_normalize_text(\n            " | ".join(\n                [\n                    str(row_or_text.get("target") or row_or_text.get("target_display") or ""),\n                    str(row_or_text.get("text_full") or row_or_text.get("text_snippet") or row_or_text.get("text") or ""),\n                    str(row_or_text.get("rationale") or ""),\n                    str(row_or_text.get("_source_snip") or ""),\n                ]\n            )\n        )\n        explicit_norm = str(\n            row_or_text.get("target_period_norm")\n            or row_or_text.get("period_key")\n            or row_or_text.get("target_period_key")\n            or row_or_text.get("target_period")\n            or ""\n        ).strip()\n        explicit_label = str(\n            row_or_text.get("target_period_label")\n            or row_or_text.get("period_label")\n            or ""\n        ).strip()\n        promise_type = str(row_or_text.get("promise_type") or "").strip().lower()\n        qd_hint = _split_target_qend(\n            stated_quarter\n            or row_or_text.get("quarter")\n            or row_or_text.get("first_seen_evidence_quarter_end")\n            or row_or_text.get("first_seen_quarter_end")\n            or row_or_text.get("last_seen_evidence_quarter_end")\n            or row_or_text.get("last_seen_quarter_end")\n        )\n    else:\n        txt = glx_normalize_text(str(row_or_text or ""))\n        explicit_norm = ""\n        explicit_label = ""\n        promise_type = ""\n        qd_hint = _split_target_qend(stated_quarter)\n    low = txt.lower()\n\n    def _pack(\n        period_type: str,\n        label: str,\n        norm: str,\n        start_dt: Optional[date],\n        end_dt: Optional[date],\n    ) -> Dict[str, Any]:\n        return {\n            "target_period_type": period_type,\n            "target_period_label": str(label or ""),\n            "target_period_norm": str(norm or ""),\n            "target_period_start": start_dt,\n            "target_period_end": end_dt,\n        }\n\n    norm_upper = explicit_norm.upper().replace(" ", "")\n    m_q_norm = re.fullmatch(r"Q(20\\d{2})Q([1-4])", norm_upper)\n    if m_q_norm:\n        yy = int(m_q_norm.group(1))\n        qq = int(m_q_norm.group(2))\n        start_dt, end_dt = _quarter_bounds(yy, qq)\n        return _pack("quarter", explicit_label or f"Q{qq} {yy}", f"Q{yy}Q{qq}", start_dt, end_dt)\n    m_fy_norm = re.fullmatch(r"FY(20\\d{2})", norm_upper)\n    if m_fy_norm:\n        yy = int(m_fy_norm.group(1))\n        return _pack("year", explicit_label or f"FY {yy}", f"FY{yy}", date(yy, 1, 1), date(yy, 12, 31))\n    if norm_upper == "FY+1" and isinstance(qd_hint, date):\n        yy = int(qd_hint.year) + 1\n        return _pack("year", explicit_label or f"FY {yy}", f"FY{yy}", date(yy, 1, 1), date(yy, 12, 31))\n    m_half_norm = re.fullmatch(r"(?:H([12])|([12])H)(20\\d{2}|\\d{2})", norm_upper)\n    if m_half_norm:\n        hh = int(m_half_norm.group(1) or m_half_norm.group(2))\n        yy_raw = str(m_half_norm.group(3))\n        yy = int(yy_raw) if len(yy_raw) == 4 else int(f"20{yy_raw}")\n        start_dt, end_dt = _half_bounds(yy, hh)\n        return _pack("half", explicit_label or f"H{hh} {yy}", f"H{hh}{yy}", start_dt, end_dt)\n    m_end_norm = re.fullmatch(r"BY_END_(20\\d{2})", norm_upper)\n    if m_end_norm:\n        yy = int(m_end_norm.group(1))\n        return _pack("year", explicit_label or f"by year-end {yy}", f"BY_END_{yy}", date(yy, 1, 1), date(yy, 12, 31))\n\n    q_match = re.search(\n        r"\\b(?:q([1-4])\\s*(20\\d{2})|(first|second|third|fourth)\\s+quarter(?:\\s+of)?\\s*(20\\d{2})?)\\b",\n        txt,\n        re.I,\n    )\n    if q_match:\n        if q_match.group(1) and q_match.group(2):\n            qq = int(q_match.group(1))\n            yy = int(q_match.group(2))\n        else:\n            quarter_map = {"first": 1, "second": 2, "third": 3, "fourth": 4}\n            qq = quarter_map.get(str(q_match.group(3) or "").lower(), 0)\n            yy = int(q_match.group(4)) if q_match.group(4) else (int(qd_hint.year) if isinstance(qd_hint, date) else 0)\n        if qq and yy:\n            start_dt, end_dt = _quarter_bounds(yy, qq)\n            return _pack("quarter", f"Q{qq} {yy}", f"Q{yy}Q{qq}", start_dt, end_dt)\n\n    half_match = re.search(\n        r"\\b(?:(first|second)\\s+half(?:\\s+of)?\\s*(20\\d{2})?|([12])H\\s*\'?(\\d{2,4}))\\b",\n        txt,\n        re.I,\n    )\n    if half_match:\n        hh = 1 if str(half_match.group(1) or "").lower() == "first" else 2 if str(half_match.group(1) or "").lower() == "second" else int(half_match.group(3) or 0)\n        yy_raw = str(half_match.group(2) or half_match.group(4) or "")\n        yy = int(yy_raw) if len(yy_raw) == 4 else int(f"20{yy_raw}") if yy_raw else (int(qd_hint.year) if isinstance(qd_hint, date) else 0)\n        if hh and yy:\n            start_dt, end_dt = _half_bounds(yy, hh)\n            return _pack("half", f"H{hh} {yy}", f"H{hh}{yy}", start_dt, end_dt)\n\n    end_match = re.search(r"\\bby\\s+(?:the\\s+)?end\\s+of\\s+(20\\d{2})\\b", low, re.I)\n    if end_match:\n        yy = int(end_match.group(1))\n        return _pack("year", f"by year-end {yy}", f"BY_END_{yy}", date(yy, 1, 1), date(yy, 12, 31))\n\n    fy_match = re.search(r"\\b(?:fy|fiscal year|full year)\\s*(20\\d{2}|\\d{2})\\b", low, re.I)\n    if fy_match:\n        yy_raw = str(fy_match.group(1))\n        yy = int(yy_raw) if len(yy_raw) == 4 else int(f"20{yy_raw}")\n        return _pack("year", f"FY {yy}", f"FY{yy}", date(yy, 1, 1), date(yy, 12, 31))\n\n    year_match = re.search(r"\\b(?:in|for|through)\\s+(20\\d{2})\\b", low, re.I)\n    if year_match:\n        yy = int(year_match.group(1))\n        return _pack("year", explicit_label or f"FY {yy}", f"FY{yy}", date(yy, 1, 1), date(yy, 12, 31))\n\n    if isinstance(qd_hint, date):\n        if re.search(r"\\bnext quarter\\b", low, re.I):\n            q_ts = pd.Timestamp(qd_hint) + pd.offsets.QuarterEnd(1)\n            q_end = pd.Timestamp(q_ts).to_period("Q").end_time.date()\n            qq = pd.Timestamp(q_end).quarter\n            yy = int(q_end.year)\n            start_dt, end_dt = _quarter_bounds(yy, qq)\n            return _pack("quarter", f"Q{qq} {yy}", f"Q{yy}Q{qq}", start_dt, end_dt)\n        if re.search(r"\\b(?:this|current)\\s+quarter\\b", low, re.I):\n            qq = pd.Timestamp(qd_hint).quarter\n            yy = int(qd_hint.year)\n            start_dt, end_dt = _quarter_bounds(yy, qq)\n            return _pack("quarter", f"Q{qq} {yy}", f"Q{yy}Q{qq}", start_dt, end_dt)\n        if re.search(r"\\bnext (?:fiscal year|year)\\b", low, re.I):\n            yy = int(qd_hint.year) + 1\n            return _pack("year", f"FY {yy}", f"FY{yy}", date(yy, 1, 1), date(yy, 12, 31))\n        if re.search(r"\\b(?:this|current|full)\\s+year\\b", low, re.I):\n            yy = int(qd_hint.year)\n            return _pack("year", f"FY {yy}", f"FY{yy}", date(yy, 1, 1), date(yy, 12, 31))\n\n    if promise_type == "milestone":\n        return _pack("milestone", explicit_label or "", explicit_norm or "", None, None)\n    return _pack("open_ended", explicit_label or "", explicit_norm or "", None, None)\n\ndef _extract_target_amounts_with_spans(text_in: Any) -> List[Tuple[float, int, int]]:\n    txt = glx_normalize_text(str(text_in or ""))\n    if not txt:\n        return []\n    out: List[Tuple[float, int, int]] = []\n    for m in re.finditer(\n        r"\\$?\\s*([0-9]{1,3}(?:,[0-9]{3})*(?:\\.\\d+)?|[0-9]+(?:\\.\\d+)?)\\s*(million|billion|m|mm|mi|bn|b)\\b",\n        txt,\n        re.I,\n    ):\n        amt = _coerce_amount_with_unit_local(m.group(1), m.group(2))\n        if amt is None:\n            continue\n        out.append((float(amt), m.start(), m.end()))\n    return out\n\ndef _nearest_amount_for_pattern(text_in: Any, pattern: str, *, after_only: bool = False) -> Optional[float]:\n    txt = glx_normalize_text(str(text_in or ""))\n    if not txt:\n        return None\n    patt = re.search(pattern, txt, re.I)\n    if not patt:\n        return None\n    amounts = _extract_target_amounts_with_spans(txt)\n    if not amounts:\n        return None\n    best_amt: Optional[float] = None\n    best_dist: Optional[int] = None\n    ref_pos = patt.start()\n    for amt, start_idx, end_idx in amounts:\n        if after_only and start_idx < patt.end():\n            continue\n        dist = min(abs(start_idx - ref_pos), abs(end_idx - ref_pos))\n        if best_dist is None or dist < best_dist:\n            best_dist = dist\n            best_amt = float(amt)\n    return best_amt\n\ndef _infer_target_structure(row_or_text: Any, stated_quarter: Any = None) -> Dict[str, Any]:\n    if isinstance(row_or_text, dict):\n        txt = glx_normalize_text(\n            " | ".join(\n                [\n                    str(row_or_text.get("target") or row_or_text.get("target_display") or ""),\n                    str(row_or_text.get("text_full") or row_or_text.get("text_snippet") or row_or_text.get("text") or ""),\n                    str(row_or_text.get("rationale") or ""),\n                    str(row_or_text.get("_source_snip") or ""),\n                ]\n            )\n        )\n        family_key = str(row_or_text.get("target_family_key") or row_or_text.get("theme_key") or "").strip().lower()\n        scope_key = _split_target_scope_token(row_or_text)\n        period_norm = str(\n            row_or_text.get("target_period_norm")\n            or row_or_text.get("target_period_key")\n            or row_or_text.get("period_key")\n            or ""\n        ).strip()\n        current_target = str(row_or_text.get("target") or row_or_text.get("target_display") or "").strip()\n    else:\n        txt = glx_normalize_text(str(row_or_text or ""))\n        family_key = ""\n        scope_key = "company_total"\n        period_norm = ""\n        current_target = ""\n    low = txt.lower()\n    amounts = [amt for amt, _, _ in _extract_target_amounts_with_spans(txt)]\n    strongest_amt = max(amounts) if amounts else None\n\n    first_stage_amt = _nearest_amount_for_pattern(txt, r"\\b(first tranche|first phase|phase 1|phase one|initial)\\b")\n    realized_anchor_amt = _nearest_amount_for_pattern(txt, r"\\b(realized|realised|implemented|achieved|to date)\\b")\n    if first_stage_amt is None and amounts and re.search(r"\\b(first tranche|first phase|phase 1|phase one|initial)\\b", low, re.I):\n        first_stage_amt = float(min(amounts))\n    additional_amt = _nearest_amount_for_pattern(txt, r"\\b(additional|another|incremental|second tranche|phase 2|phase two)\\b")\n    if additional_amt is None and amounts and re.search(r"\\b(additional|another|incremental|second tranche|phase 2|phase two)\\b", low, re.I):\n        additional_amt = float(min(amounts))\n    remaining_amt = _nearest_amount_for_pattern(txt, r"\\bremaining\\b")\n    total_amt = _nearest_amount_for_pattern(\n        txt,\n        r"\\b(total program|full program|program total|up to|overall program|annualized program)\\b",\n    )\n    if total_amt is None and re.search(r"\\bannualized program\\b", low, re.I) and amounts:\n        total_amt = float(max(amounts))\n    if total_amt is None and re.search(r"\\bup to\\b", low, re.I) and amounts:\n        total_amt = float(max(amounts))\n    if (\n        total_amt is None\n        and realized_anchor_amt is not None\n        and additional_amt is not None\n        and re.search(r"\\b(additional|another|incremental|second tranche|phase 2|phase two)\\b", low, re.I)\n    ):\n        total_amt = float(realized_anchor_amt) + float(additional_amt)\n\n    stage_kind = ""\n    stage_amount = None\n    increment_amount = None\n    program_total_amount = total_amt\n    if first_stage_amt is not None and re.search(r"\\b(first tranche|first phase|phase 1)\\b", low, re.I):\n        stage_kind = "first_tranche"\n        stage_amount = first_stage_amt\n    elif first_stage_amt is not None and re.search(r"\\binitial\\b", low, re.I):\n        stage_kind = "initial"\n        stage_amount = first_stage_amt\n    elif additional_amt is not None and re.search(r"\\b(second tranche|phase 2|phase two)\\b", low, re.I):\n        stage_kind = "phase_2"\n        stage_amount = additional_amt\n        increment_amount = additional_amt\n    elif additional_amt is not None:\n        stage_kind = "additional_tranche"\n        stage_amount = additional_amt\n        increment_amount = additional_amt\n    elif remaining_amt is not None and re.search(r"\\bremaining\\b", low, re.I):\n        stage_kind = "remaining"\n        stage_amount = remaining_amt\n\n    if program_total_amount is None and strongest_amt is not None and re.search(r"\\b(program|annualized savings|annualized program|full target|full program)\\b", low, re.I):\n        program_total_amount = strongest_amt\n\n    if stage_kind and program_total_amount is not None:\n        structure_kind = "stage_and_total"\n    elif stage_kind:\n        structure_kind = "stage"\n    elif program_total_amount is not None:\n        structure_kind = "program_total"\n    else:\n        structure_kind = "single"\n\n    current_target_hits = _extract_money_targets_for_display(current_target)\n    current_target_amt = float(max(current_target_hits)) if current_target_hits else None\n    if structure_kind in {"program_total", "stage_and_total"} and program_total_amount is not None:\n        if current_target_amt is not None and abs(float(current_target_amt) - float(program_total_amount)) <= max(1e5, abs(float(program_total_amount)) * 0.02):\n            role = "program_total"\n        elif stage_kind:\n            role = stage_kind\n        else:\n            role = "program_total"\n    elif stage_kind:\n        role = stage_kind\n    else:\n        role = "single"\n\n    if not family_key:\n        family_key = _split_target_family_key(_management_theme_key("", txt, period_norm))\n    if not period_norm:\n        period_norm = _infer_target_period({"text_full": txt}, stated_quarter).get("target_period_norm") or "UNK"\n    program_key = ""\n    if structure_kind != "single":\n        program_key = "|".join(\n            [\n                str(family_key or "unknown_theme"),\n                str(scope_key or "company_total"),\n                str(period_norm or "UNK"),\n                "program",\n            ]\n        )\n\n    return {\n        "target_structure_kind": structure_kind,\n        "target_structure_role": role,\n        "stage_kind": stage_kind,\n        "stage_amount": stage_amount,\n        "increment_amount": increment_amount,\n        "program_total_amount": program_total_amount,\n        "program_key": program_key,\n    }\n\ndef _split_target_identity_key(\n    item: Dict[str, Any],\n    metric_name: Any = "",\n    period_key: Any = "",\n    quarter_hint: Any = None,\n) -> Tuple[str, str, str, str, str]:\n    group_key = str(item.get("target_group_key") or "").strip()\n    if not group_key:\n        split_meta = _derive_split_target_meta(\n            metric_name or item.get("metric") or item.get("metric_ref") or "",\n            " | ".join(\n                [\n                    str(item.get("text_full") or item.get("text_snippet") or item.get("text") or ""),\n                    str(item.get("target_display") or item.get("target") or ""),\n                ]\n            ),\n            period_key or item.get("target_period_norm") or item.get("period_key") or "",\n            quarter_hint or item.get("quarter"),\n            dict(item.get("source") or {}).get("source_type"),\n            dict(item.get("source") or {}).get("doc"),\n            dict(item.get("source") or {}).get("section"),\n        )\n        group_key = str(split_meta.get("target_group_key") or "").strip()\n    if not group_key:\n        family_key = str(\n            item.get("target_family_key")\n            or item.get("theme_key")\n            or _management_theme_key(metric_name or item.get("metric") or item.get("metric_ref") or "", item.get("text_full") or item.get("text_snippet") or "", period_key or item.get("period_key") or "")\n            or "unknown_theme"\n        ).strip()\n        group_key = _split_target_group_key(\n            family_key,\n            period_key or item.get("target_period_norm") or item.get("period_key") or "UNK",\n            quarter_hint or item.get("quarter"),\n        )\n    structure_kind = str(item.get("target_structure_kind") or "").strip().lower()\n    stage_kind = str(item.get("stage_kind") or "").strip().lower()\n    program_key = str(item.get("program_key") or "").strip()\n    role = str(item.get("target_structure_role") or "").strip().lower()\n    if not (structure_kind or stage_kind or program_key or role):\n        struct_meta = _infer_target_structure(\n            {\n                "target": item.get("target") or item.get("target_display") or "",\n                "text_full": item.get("text_full") or item.get("text_snippet") or item.get("text") or "",\n                "metric": metric_name or item.get("metric") or item.get("metric_ref") or "",\n                "target_family_key": item.get("target_family_key") or item.get("theme_key") or "",\n                "scope_key": item.get("scope_key") or "",\n                "target_period_norm": period_key or item.get("target_period_norm") or item.get("period_key") or "",\n            },\n            quarter_hint or item.get("quarter"),\n        )\n        structure_kind = str(struct_meta.get("target_structure_kind") or "").strip().lower()\n        stage_kind = str(struct_meta.get("stage_kind") or "").strip().lower()\n        program_key = str(struct_meta.get("program_key") or "").strip()\n        role = str(struct_meta.get("target_structure_role") or "").strip().lower()\n    return (\n        group_key,\n        _split_target_scope_token(item),\n        str(item.get("promise_type") or item.get("guidance_type") or "operational"),\n        program_key,\n        role or stage_kind or structure_kind or "single",\n    )\n\ndef _candidate_quality_key(\n    text: Any,\n    source_type: Any,\n    doc_name: Any = "",\n    doc_priority: Any = 0,\n    score: Any = 0.0,\n) -> Tuple[int, int, int, int, float, int]:\n    txt = glx_normalize_text(text)\n    doc_pri_num = pd.to_numeric(doc_priority, errors="coerce")\n    score_num = pd.to_numeric(score, errors="coerce")\n    return (\n        _source_rank(source_type, doc_name),\n        _text_fragment_penalty(txt),\n        -_clean_target_bonus(txt),\n        -int(doc_pri_num) if pd.notna(doc_pri_num) else 0,\n        -float(score_num) if pd.notna(score_num) else 0.0,\n        len(txt),\n    )\n\ndef _slide_excerpt(lines: List[str], idx: int) -> str:\n    if idx < 0 or idx >= len(lines):\n        return ""\n    cur = glx_normalize_text(lines[idx])\n    if not cur or _slide_line_is_noise(cur):\n        return ""\n    start = idx\n    if not cur.startswith("•"):\n        for j in range(idx - 1, max(-1, idx - 3), -1):\n            prev = glx_normalize_text(lines[j])\n            if not prev or _slide_line_is_noise(prev) or _slide_line_is_heading(prev):\n                break\n            if prev.startswith("•"):\n                start = j\n                break\n            if len(prev) <= 48:\n                start = j\n                continue\n            break\n    parts: List[str] = []\n    for j in range(start, min(len(lines), start + 8)):\n        line = glx_normalize_text(lines[j])\n        if not line or _slide_line_is_noise(line):\n            if parts:\n                break\n            continue\n        if j > start and line.startswith("•"):\n            break\n        if j > idx and _slide_line_is_heading(line):\n            break\n        line = line.lstrip("•").strip()\n        merged = glx_normalize_text(" ".join(parts + [line]))\n        if len(merged) > 260 and parts:\n            break\n        parts.append(line)\n        merged_low = glx_normalize_text(" ".join(parts)).lower()\n        if j >= idx and re.search(r"[.!?]$", line):\n            break\n        if re.search(r"\\b(ebitda opportunity|sequestering co2 in wyoming|qualify for (?:2026 )?45z credits|sale completed|fully repay|tallgrass trailblazer pipeline|ramping up capture volumes)\\b", merged_low, re.I):\n            break\n    text = glx_normalize_text(" ".join(parts))\n    text = re.sub(r"(?<=\\d)\\s+(?=\\d)", "", text)\n    text = re.sub(r"(?<=\\d)\\s+(?=[MmBb]\\b)", "", text)\n    text = text.replace("|", " ")\n    text = glx_normalize_text(text)\n    text = re.sub(r"\\s+\\.\\s+", ". ", text)\n    return _clean_profile_signal_text(text)\n\ndef _profile_slide_signals_cache_path() -> Optional[Path]:\n    root = cache_root if isinstance(cache_root, Path) else None\n    if root is None:\n        return None\n    safe_ticker = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(profile_ticker or ticker or "ticker")).strip("_")\n    if not safe_ticker:\n        safe_ticker = "ticker"\n    return root / f"writer_profile_slide_signals_{safe_ticker.lower()}.json"\n\ndef _profile_slide_signals_signature(\n    priority_terms: Tuple[str, ...],\n    slide_paths: List[Path],\n) -> str:\n    payload_paths: List[Dict[str, Any]] = []\n    for path_in in slide_paths:\n        try:\n            stat = path_in.stat()\n            mtime_ns = int(getattr(stat, "st_mtime_ns", int(stat.st_mtime * 1_000_000_000)))\n            size = int(stat.st_size)\n        except Exception:\n            mtime_ns = 0\n            size = 0\n        try:\n            path_key = str(path_in.resolve())\n        except Exception:\n            path_key = str(path_in)\n        payload_paths.append({"path": path_key, "mtime_ns": mtime_ns, "size": size})\n    payload = {\n        "version": "profile_slide_signals_v1",\n        "ticker": str(profile_ticker or ticker or "").upper(),\n        "priority_terms": list(priority_terms),\n        "slides": payload_paths,\n    }\n    return hashlib.sha1(json.dumps(payload, sort_keys=True, ensure_ascii=True).encode("utf-8")).hexdigest()\n\ndef _profile_slide_signal_jsonable(value_in: Any) -> Any:\n    if isinstance(value_in, dict):\n        return {str(k): _profile_slide_signal_jsonable(v) for k, v in value_in.items()}\n    if isinstance(value_in, (list, tuple)):\n        return [_profile_slide_signal_jsonable(v) for v in value_in]\n    if isinstance(value_in, (pd.Timestamp, datetime, date)):\n        try:\n            return pd.Timestamp(value_in).date().isoformat()\n        except Exception:\n            return str(value_in)\n    if isinstance(value_in, Path):\n        return str(value_in)\n    return value_in\n\ndef _read_profile_slide_signals_cache(signature: str) -> Optional[List[Dict[str, Any]]]:\n    cache_path = _profile_slide_signals_cache_path()\n    if cache_path is None or not cache_path.exists():\n        return None\n    try:\n        payload = json.loads(cache_path.read_text(encoding="utf-8"))\n    except Exception:\n        return None\n    if str(payload.get("signature") or "") != signature:\n        return None\n    rows_in = payload.get("rows")\n    if not isinstance(rows_in, list):\n        return None\n    out_rows: List[Dict[str, Any]] = []\n    for row_in in rows_in:\n        if not isinstance(row_in, dict):\n            continue\n        row = dict(row_in)\n        qd = parse_date(row.get("quarter"))\n        if qd is None:\n            continue\n        row["quarter"] = qd\n        out_rows.append(row)\n    return out_rows\n\ndef _write_profile_slide_signals_cache(signature: str, rows: List[Dict[str, Any]]) -> None:\n    cache_path = _profile_slide_signals_cache_path()\n    if cache_path is None:\n        return\n    payload = {\n        "signature": signature,\n        "rows": [_profile_slide_signal_jsonable(dict(row or {})) for row in rows],\n    }\n    try:\n        cache_path.parent.mkdir(parents=True, exist_ok=True)\n        cache_path.write_text(json.dumps(payload, ensure_ascii=True, sort_keys=True), encoding="utf-8")\n    except Exception:\n        return\n\ndef _load_profile_slide_signals() -> List[Dict[str, Any]]:\n    global profile_slide_signals_cache\n    if profile_slide_signals_cache is not None:\n        return list(profile_slide_signals_cache)\n    priority_terms = tuple(\n        sorted(\n            {\n                str(t).lower().strip()\n                for t in (\n                    list(getattr(company_profile, "quarter_note_priority_terms", ()) or [])\n                    + list(getattr(company_profile, "promise_priority_terms", ()) or [])\n                )\n                if str(t).strip()\n            }\n        )\n    )\n    if not priority_terms:\n        profile_slide_signals_cache = []\n        return []\n    slide_paths_by_kind = {kind: _slide_text_paths(kind=kind) for kind in ("text", "ocr")}\n    slide_kinds = [kind for kind, paths in slide_paths_by_kind.items() if paths]\n    if not slide_kinds:\n        profile_slide_signals_cache = []\n        return []\n    signature = _profile_slide_signals_signature(\n        priority_terms,\n        [path_in for kind in ("text", "ocr") for path_in in slide_paths_by_kind.get(kind, [])],\n    )\n    cached_rows = _read_profile_slide_signals_cache(signature)\n    if cached_rows is not None:\n        profile_slide_signals_cache = cached_rows\n        return list(cached_rows)\n    text_quarters: set[date] = set()\n    for path in slide_paths_by_kind.get("text", []):\n        qd = _parse_quarter_from_filename(path.name)\n        if qd is not None:\n            text_quarters.add(qd)\n    legal_re = re.compile(\n        r"\\b(safe harbor|forward-looking statements|private securities litigation reform act|indenture|administrative agent|proxy statement)\\b",\n        re.I,\n    )\n    progress_re = re.compile(r"\\b(on track|ramping|in progress|advancing|continuing)\\b", re.I)\n    complete_re = re.compile(r"\\b(fully operational|online|completed|started up|executed|sale completed|repaid|fully repay)\\b", re.I)\n    target_re = re.compile(r"\\b(target|guidance|expected|expect|anticipate|annualized|monetization|opportunity)\\b", re.I)\n    out_rows: List[Dict[str, Any]] = []\n    seen_keys: set[Tuple[date, str]] = set()\n    for slide_kind in slide_kinds:\n        slide_paths = sorted(slide_paths_by_kind.get(slide_kind, []), key=lambda p: p.stat().st_mtime if p.exists() else 0, reverse=True)\n        for path in slide_paths:\n            qd = _parse_quarter_from_filename(path.name)\n            if qd is None:\n                continue\n            ocr_fallback_only = bool(slide_kind == "ocr" and qd in text_quarters)\n            raw_text = _read_cached_doc_raw(path)\n            if not raw_text:\n                continue\n            lines = [glx_normalize_text(x) for x in raw_text.splitlines()]\n            lines = [x for x in lines if x]\n            for txt in _extract_profile_signal_texts(" ".join(lines)):\n                low = txt.lower()\n                if legal_re.search(low) or _slide_signal_noise(txt):\n                    continue\n                hits = sum(1 for term in priority_terms if term and term in low)\n                metric_label = _profile_slide_metric(txt)\n                theme_key = _management_theme_key(metric_label, txt)\n                fragment_penalty = _text_fragment_penalty(txt)\n                status_hint = ""\n                if complete_re.search(low):\n                    status_hint = "completed"\n                elif progress_re.search(low):\n                    status_hint = "in progress"\n                elif target_re.search(low) and re.search(r"\\$\\s*\\d|\\b\\d+\\s*%\\b|\\b20\\d{2}\\b", txt):\n                    status_hint = "on_track"\n                score = 90.0 + float(hits * 4) - float(fragment_penalty * 4.0) + float(_clean_target_bonus(txt))\n                rec = {\n                    "quarter": qd,\n                    "text": txt,\n                    "category": _profile_slide_category(txt),\n                    "metric": metric_label,\n                    "source_type": "earnings_presentation",\n                    "source_doc": str(path),\n                    "status_hint": status_hint,\n                    "target_display": _profile_slide_target_display(txt, qd),\n                    "is_numeric_target": bool(re.search(r"\\$\\s*\\d|\\b\\d+\\s*%\\b|\\b20\\d{2}\\b", txt) and target_re.search(low)),\n                    "is_milestone": bool(complete_re.search(low) or progress_re.search(low)),\n                    "theme_key": theme_key,\n                    "fragment_penalty": fragment_penalty,\n                    "doc_priority": 1,\n                    "score": score,\n                }\n                rec.update(\n                    _derive_split_target_meta(\n                        metric_label,\n                        txt,\n                        rec.get("target_display") or "",\n                        qd,\n                        "earnings_presentation",\n                        str(path),\n                        "",\n                    )\n                )\n                rec["metric_display"] = _split_target_metric_display(metric_label, txt, rec)\n                out_rows.append(rec)\n            if ocr_fallback_only:\n                continue\n            for idx, line in enumerate(lines):\n                if len(line) < 20:\n                    continue\n                txt = _slide_excerpt(lines, idx) or glx_normalize_text(line)\n                low = txt.lower()\n                if legal_re.search(low):\n                    continue\n                if _slide_signal_noise(txt):\n                    continue\n                hits = sum(1 for term in priority_terms if term and term in low)\n                if hits <= 0:\n                    continue\n                is_numeric = bool(re.search(r"\\$\\s*\\d|\\b\\d+\\s*%\\b|\\b\\d{4}\\b", txt))\n                is_milestone = bool(complete_re.search(low) or progress_re.search(low))\n                explicit_driver_signal = bool(\n                    ("utilization" in low and re.search(r"(?<!\\d)\\d{2,3}%", txt))\n                    or ("risk management" in low and re.search(r"\\b(margin|margins|cash flow|lock in favorable)\\b", low, re.I))\n                )\n                if not (is_numeric or is_milestone or hits >= 2 or explicit_driver_signal):\n                    continue\n                metric_label = _profile_slide_metric(txt)\n                theme_key = _management_theme_key(metric_label, txt)\n                fragment_penalty = _text_fragment_penalty(txt)\n                if fragment_penalty >= 4 and not (target_re.search(low) or is_milestone):\n                    continue\n                key = (qd, metric_label + "|" + txt[:140].lower())\n                if key in seen_keys:\n                    continue\n                seen_keys.add(key)\n                status_hint = ""\n                if complete_re.search(low):\n                    status_hint = "completed"\n                elif progress_re.search(low):\n                    status_hint = "in progress"\n                elif target_re.search(low) and is_numeric:\n                    status_hint = "on_track"\n                score = 82.0 + float(hits * 4) - max(0.0, (len(txt) - 180) / 18.0) - float(fragment_penalty * 6.0)\n                if "ebitda opportunity" in low or ("adjusted" in low and "ebitda" in low):\n                    score += 12.0\n                if "fully operational" in low or "online and ramping up" in low:\n                    score += 4.0\n                if "fully repay" in low or "sale of obion" in low:\n                    score += 6.0\n                if "utilization" in low and re.search(r"(?<!\\d)\\d{2,3}%", txt):\n                    score += 5.0\n                if "risk management" in low and re.search(r"\\b(margin|margins|cash flow|lock in favorable)\\b", low, re.I):\n                    score += 5.0\n                score += float(_clean_target_bonus(txt))\n                rec = {\n                    "quarter": qd,\n                    "text": txt,\n                    "category": _profile_slide_category(txt),\n                    "metric": metric_label,\n                    "source_type": "earnings_presentation",\n                    "source_doc": str(path),\n                    "status_hint": status_hint,\n                    "target_display": _profile_slide_target_display(txt, qd),\n                    "is_numeric_target": bool(is_numeric and target_re.search(low)),\n                    "is_milestone": bool(is_milestone),\n                    "theme_key": theme_key,\n                    "fragment_penalty": fragment_penalty,\n                    "score": score,\n                }\n                rec.update(\n                    _derive_split_target_meta(\n                        metric_label,\n                        txt,\n                        rec.get("target_display") or "",\n                        qd,\n                        "earnings_presentation",\n                        str(path),\n                        "",\n                    )\n                )\n                rec["metric_display"] = _split_target_metric_display(metric_label, txt, rec)\n                out_rows.append(rec)\n    best_by_theme: Dict[Tuple[date, str, str], Dict[str, Any]] = {}\n    deduped_rows: List[Dict[str, Any]] = []\n    for rec in out_rows:\n        theme_key = str(rec.get("theme_key") or "").strip()\n        if not theme_key:\n            deduped_rows.append(rec)\n            continue\n        scope_key = str(rec.get("scope_key") or "").strip()\n        dkey = (rec.get("quarter"), theme_key, scope_key or "company_total")\n        prev = best_by_theme.get(dkey)\n        if prev is None or _candidate_quality_key(\n            rec.get("text"),\n            rec.get("source_type"),\n            rec.get("source_doc"),\n            rec.get("doc_priority"),\n            rec.get("score"),\n        ) < _candidate_quality_key(\n            prev.get("text"),\n            prev.get("source_type"),\n            prev.get("source_doc"),\n            prev.get("doc_priority"),\n            prev.get("score"),\n        ):\n            best_by_theme[dkey] = rec\n    deduped_rows.extend(best_by_theme.values())\n    profile_slide_signals_cache = sorted(\n        deduped_rows,\n        key=lambda z: (\n            z.get("quarter") or date.min,\n            _candidate_quality_key(\n                z.get("text"),\n                z.get("source_type"),\n                z.get("source_doc"),\n                z.get("doc_priority"),\n                z.get("score"),\n            ),\n        ),\n        reverse=False,\n    )\n    _write_profile_slide_signals_cache(signature, profile_slide_signals_cache)\n    return list(profile_slide_signals_cache)\n\ndef _load_profile_slide_signals_by_quarter() -> Dict[date, List[Dict[str, Any]]]:\n    global profile_slide_signals_by_quarter_cache\n    if profile_slide_signals_by_quarter_cache is not None:\n        if ctx_ref is not None:\n            ctx_ref.derived.profile_slide_signals_by_quarter = profile_slide_signals_by_quarter_cache\n        return profile_slide_signals_by_quarter_cache\n    with _timed_writer_substage("write_excel.derive.driver_inputs.template_signal_index"):\n        grouped: Dict[date, List[Dict[str, Any]]] = {}\n        for rec in _load_profile_slide_signals():\n            qd = rec.get("quarter")\n            if not isinstance(qd, date):\n                continue\n            grouped.setdefault(qd, []).append(rec)\n        for qd, rows in grouped.items():\n            grouped[qd] = sorted(\n                rows,\n                key=lambda rec: (\n                    -float(rec.get("score") or 0.0),\n                    int(rec.get("fragment_penalty") or 0),\n                    str(rec.get("source_doc") or ""),\n                ),\n            )\n        profile_slide_signals_by_quarter_cache = grouped\n    if ctx_ref is not None:\n        ctx_ref.derived.profile_slide_signals_by_quarter = profile_slide_signals_by_quarter_cache\n    return profile_slide_signals_by_quarter_cache\n\ndef _profile_slide_signals_for_quarter(qd: date) -> List[Dict[str, Any]]:\n    if not isinstance(qd, date):\n        return []\n    return list(_load_profile_slide_signals_by_quarter().get(qd, []))\n\ndef _local_slide_driver_fallback(qd: date, driver_kind: str) -> str:\n    if not isinstance(qd, date):\n        return ""\n    driver_kind_low = str(driver_kind or "").strip().lower()\n    if driver_kind_low == "risk_management":\n        official_note = "Disciplined risk management strategy continues to support first quarter margins and cash flow."\n        qd_token = pd.to_datetime(qd, errors="coerce")\n        qd_token_str = qd_token.strftime("%Y%m%d") if pd.notna(qd_token) else ""\n        for root in _cache_roots():\n            candidates = _sec_cache_html_paths_for_token_local(root, qd_token_str) if qd_token_str else []\n            if not candidates:\n                continue\n            for path in candidates:\n                try:\n                    joined = glx_normalize_text(" ".join([_read_cached_doc_raw(path), _read_cached_doc_text(path)]))\n                except Exception:\n                    joined = ""\n                if joined and re.search(r"\\bdisciplined risk management strategy continues to support first quarter margins and cash flow\\b", joined, re.I):\n                    return official_note\n    for path in _slide_text_paths(kind="text", quarter=qd):\n        raw_slide_txt = _read_cached_doc_raw(path)\n        if not raw_slide_txt:\n            continue\n            lines = [glx_normalize_text(x).lstrip("•").strip() for x in raw_slide_txt.splitlines()]\n            for idx, line_txt in enumerate(lines):\n                if not line_txt:\n                    continue\n                if driver_kind_low == "utilization":\n                    if re.search(r"(?<!\\d)\\d{2,3}%", line_txt) and re.search(\n                        r"\\b(utilization|stated capacity|operating rate|capacity utilization)\\b",\n                        line_txt,\n                        re.I,\n                    ):\n                        return line_txt\n                    pct_match = re.search(r"(?<!\\d)(\\d{2,3})%\\*?", line_txt)\n                    if pct_match:\n                        nearby = " ".join([x for x in lines[max(0, idx - 1) : min(len(lines), idx + 3)] if x])\n                        if re.search(r"\\b(of\\s+)?(production|stated)\\s+capacity\\b", nearby, re.I) and re.search(\n                            r"\\b(ethanol|operating plants|production at|utilization)\\b",\n                            nearby,\n                            re.I,\n                        ):\n                            note_txt = f"Production at {pct_match.group(1)}% of stated capacity"\n                            if re.search(r"\\bexcluding\\s+fairmont\\b", " ".join(lines[idx : min(len(lines), idx + 7)]), re.I):\n                                note_txt = f"{note_txt} (excluding Fairmont)"\n                            return note_txt\n                elif driver_kind_low == "risk_management":\n                    if re.search(r"\\brisk management\\b", line_txt, re.I) and re.search(\n                        r"\\b(margins?|cash flow|lock in favorable|protect downside|economics)\\b",\n                        line_txt,\n                        re.I,\n                    ):\n                        return line_txt\n                elif driver_kind_low == "rin_impact":\n                    if re.search(r"\\baccumulated rins?\\b|\\brins?\\s+of\\s+\\$", line_txt, re.I):\n                        return line_txt\n        lines = [re.sub(r"^[\\u2022*]+\\s*", "", glx_normalize_text(x)).strip() for x in raw_slide_txt.splitlines()]\n        for idx, line_txt in enumerate(lines):\n            if not line_txt:\n                continue\n            if driver_kind_low == "utilization":\n                if re.search(r"(?<!\\d)\\d{2,3}%", line_txt) and re.search(\n                    r"\\b(utilization|stated capacity|operating rate|capacity utilization)\\b",\n                    line_txt,\n                    re.I,\n                ):\n                    return line_txt\n                pct_match = re.search(r"(?<!\\d)(\\d{2,3})%\\*?", line_txt)\n                if pct_match:\n                    nearby = " ".join([x for x in lines[max(0, idx - 1) : min(len(lines), idx + 3)] if x])\n                    if re.search(r"\\b(of\\s+)?(production|stated)\\s+capacity\\b", nearby, re.I) and re.search(\n                        r"\\b(ethanol|operating plants|production at|utilization)\\b",\n                        nearby,\n                        re.I,\n                    ):\n                        note_txt = f"Production at {pct_match.group(1)}% of stated capacity"\n                        if re.search(r"\\bexcluding\\s+fairmont\\b", " ".join(lines[idx : min(len(lines), idx + 7)]), re.I):\n                            note_txt = f"{note_txt} (excluding Fairmont)"\n                        return note_txt\n            elif driver_kind_low == "risk_management":\n                if re.search(r"\\brisk management\\b", line_txt, re.I) and re.search(\n                    r"\\b(margins?|cash flow|lock in favorable|protect downside|economics)\\b",\n                    line_txt,\n                    re.I,\n                ):\n                    return line_txt\n            elif driver_kind_low == "rin_impact":\n                if re.search(r"\\baccumulated rins?\\b|\\brins?\\s+of\\s+\\$", line_txt, re.I):\n                    return line_txt\n    return ""\n\n_gpre_official_risk_management_note_cache: Dict[date, Dict[str, Any]] = {}\n_gpre_transcript_risk_management_note_cache: Dict[date, Dict[str, Any]] = {}\n_gpre_official_45z_realized_note_cache: Dict[date, Dict[str, Any]] = {}\n\ndef _quarter_matches_source_event_window_local(\n    qd: Optional[date],\n    *,\n    enabled: bool = True,\n    start: Optional[date] = None,\n    end: Optional[date] = None,\n    months: Optional[Iterable[int]] = None,\n    exact_quarters: Optional[Iterable[date]] = None,\n) -> bool:\n    """Cheap guard for source-cache scans that can only match known quarters.\n\n    Ticker-specific rescue helpers often search broad SEC/source-material\n    caches for one event family. The expensive text scan should only run for\n    quarters where that event can plausibly exist; the helper still leaves\n    source-text matching and provenance checks to the caller.\n    """\n    if not enabled or not isinstance(qd, date):\n        return False\n    if exact_quarters is not None:\n        return any(qd == q_exact for q_exact in exact_quarters)\n    if start is not None and qd < start:\n        return False\n    if end is not None and qd > end:\n        return False\n    if months is not None and qd.month not in set(int(m) for m in months):\n        return False\n    return True\n\ndef _gpre_official_risk_management_note_local(qd: Optional[date]) -> Dict[str, Any]:\n    if not _quarter_matches_source_event_window_local(\n        qd,\n        enabled=is_gpre_profile,\n        start=date(2026, 3, 31),\n        months=(3,),\n    ):\n        return {}\n    cached = _gpre_official_risk_management_note_cache.get(qd)\n    if cached is not None:\n        return dict(cached)\n\n    def _cache_risk_note_local(note_in: Dict[str, Any]) -> Dict[str, Any]:\n        _gpre_official_risk_management_note_cache[qd] = dict(note_in or {})\n        return dict(note_in or {})\n\n    official_note = "Disciplined risk management strategy continues to support first quarter margins and cash flow."\n    official_note_re = r"\\bdisciplined risk management strategy continues to support first quarter margins and cash flow\\b"\n    qd_token = pd.to_datetime(qd, errors="coerce")\n    qd_token_str = qd_token.strftime("%Y%m%d") if pd.notna(qd_token) else ""\n    quarter_num = ((int(qd.month) - 1) // 3) + 1\n    quarter_caption = {\n        1: "First Quarter",\n        2: "Second Quarter",\n        3: "Third Quarter",\n        4: "Fourth Quarter",\n    }.get(int(quarter_num), "")\n    quarter_path_token = f"q{quarter_num}{qd.year}"\n    for root in _cache_roots():\n        candidates = _sec_cache_html_paths_for_token_local(root, qd_token_str) if qd_token_str else []\n        if not candidates:\n            candidates = _sec_cache_html_paths_local(root)\n        for path in candidates:\n            if not _path_belongs_to_ticker(path, ticker, ticker_roots):\n                continue\n            try:\n                joined = glx_normalize_text(" ".join([_read_cached_doc_raw(path), _read_cached_doc_text(path)]))\n            except Exception:\n                joined = ""\n            if not joined:\n                continue\n            q_raw = _infer_doc_quarter_local(path, joined)\n            path_low = str(path.name).lower()\n            path_matches_q = bool(qd_token_str and qd_token_str in path_low) or bool(quarter_path_token and quarter_path_token in path_low)\n            text_matches_q = bool(\n                quarter_caption\n                and re.search(rf"\\b{quarter_caption}\\b[\\s\\S]{{0,80}}?\\b{qd.year}\\b", joined, re.I)\n            )\n            if isinstance(q_raw, date):\n                if q_raw != qd and not path_matches_q:\n                    continue\n            elif not path_matches_q and not text_matches_q:\n                continue\n            if re.search(official_note_re, joined, re.I):\n                return _cache_risk_note_local({\n                    "text": official_note,\n                    "source": {\n                        "source_type": "earnings_release",\n                        "doc": str(path),\n                        "form": "8-K",\n                    },\n                })\n    for root in _cache_roots():\n        for path in _sec_cache_html_paths_local(root):\n            if not _path_belongs_to_ticker(path, ticker, ticker_roots):\n                continue\n            try:\n                joined = glx_normalize_text(" ".join([_read_cached_doc_raw(path), _read_cached_doc_text(path)]))\n            except Exception:\n                joined = ""\n            if not joined:\n                continue\n            q_raw = _infer_doc_quarter_local(path, joined)\n            path_low = str(path.name).lower()\n            path_matches_q = bool(qd_token_str and qd_token_str in path_low) or bool(quarter_path_token and quarter_path_token in path_low)\n            text_matches_q = bool(\n                quarter_caption\n                and re.search(rf"\\b{quarter_caption}\\b[\\s\\S]{{0,80}}?\\b{qd.year}\\b", joined, re.I)\n            )\n            if isinstance(q_raw, date):\n                if q_raw != qd and not path_matches_q:\n                    continue\n            elif not path_matches_q and not text_matches_q:\n                continue\n            if re.search(official_note_re, joined, re.I):\n                return _cache_risk_note_local({\n                    "text": official_note,\n                    "source": {\n                        "source_type": "earnings_release",\n                        "doc": str(path),\n                        "form": "8-K",\n                    },\n                })\n    return _cache_risk_note_local({})\n\ndef _gpre_transcript_risk_management_note_local(qd: Optional[date]) -> Dict[str, Any]:\n    if not is_gpre_profile or not isinstance(qd, date):\n        return {}\n    cached = _gpre_transcript_risk_management_note_cache.get(qd)\n    if cached is not None:\n        return dict(cached)\n\n    def _cache_transcript_note_local(note_in: Dict[str, Any]) -> Dict[str, Any]:\n        _gpre_transcript_risk_management_note_cache[qd] = dict(note_in or {})\n        return dict(note_in or {})\n\n    transcript_targets: Dict[date, Tuple[Tuple[str, ...], str]] = {\n        date(2025, 9, 30): (\n            ("75% hedged on crush in the fourth quarter", "put positions on for q1 in 2026"),\n            "Management said Q4 crush was about 75% hedged and positions had been put on for Q1 2026.",\n        ),\n        date(2025, 12, 31): (\n            ("significant portion of our q1 production margin logged in",),\n            "Management said a significant portion of Q1 production margin was already logged in.",\n        ),\n    }\n    target = transcript_targets.get(qd)\n    if target is None:\n        return _cache_transcript_note_local({})\n    must_terms, summary_text = target\n    for rec in _load_operating_driver_source_records_by_quarter().get(qd, []) or []:\n        source_type = str(rec.get("source_type") or "").strip().lower()\n        if source_type != "transcript":\n            continue\n        text_low = str(rec.get("_text_low") or "").strip().lower()\n        if not text_low or any(term not in text_low for term in must_terms):\n            continue\n        excerpt = ""\n        sentences = [str(s).strip() for s in glx_split_sentences(str(rec.get("text") or "")) if str(s).strip()]\n        matched = [s for s in sentences if any(str(term or "").strip().lower() in s.lower() for term in must_terms)]\n        if matched:\n            excerpt = _ensure_terminal_period(qn_compact_snippet(" ".join(matched[:2]), 280))\n        else:\n            excerpt = _ensure_terminal_period(qn_compact_snippet(str(rec.get("text") or ""), 280))\n        return _cache_transcript_note_local({\n            "text": summary_text,\n            "comment_full_text": excerpt,\n            "source": {\n                "source_type": "transcript",\n                "doc": str(rec.get("source_doc") or ""),\n                "form": "transcript",\n            },\n        })\n    return _cache_transcript_note_local({})\n\ndef _gpre_official_45z_realized_note_local(qd: Optional[date]) -> Dict[str, Any]:\n    if not _quarter_matches_source_event_window_local(\n        qd,\n        enabled=is_gpre_profile,\n        start=date(2025, 1, 1),\n    ):\n        return {}\n    cached = _gpre_official_45z_realized_note_cache.get(qd)\n    if cached is not None:\n        return dict(cached)\n\n    def _cache_45z_note_local(note_in: Dict[str, Any]) -> Dict[str, Any]:\n        _gpre_official_45z_realized_note_cache[qd] = dict(note_in or {})\n        return dict(note_in or {})\n\n    qd_token = pd.to_datetime(qd, errors="coerce")\n    qd_token_str = qd_token.strftime("%Y%m%d") if pd.notna(qd_token) else ""\n    quarter_num = ((int(qd.month) - 1) // 3) + 1\n    quarter_caption = {\n        1: "First Quarter",\n        2: "Second Quarter",\n        3: "Third Quarter",\n        4: "Fourth Quarter",\n    }.get(int(quarter_num), "")\n    quarter_path_token = f"q{quarter_num}{qd.year}"\n    for root in _cache_roots():\n        candidates = _sec_cache_html_paths_for_token_local(root, qd_token_str) if qd_token_str else []\n        if not candidates:\n            candidates = _sec_cache_html_paths_local(root)\n        for path in candidates:\n            if not _path_belongs_to_ticker(path, ticker, ticker_roots):\n                continue\n            try:\n                joined = glx_normalize_text(" ".join([_read_cached_doc_raw(path), _read_cached_doc_text(path)]))\n            except Exception:\n                joined = ""\n            if not joined:\n                continue\n            q_raw = _infer_doc_quarter_local(path, joined)\n            path_low = str(path.name).lower()\n            path_matches_q = bool(qd_token_str and qd_token_str in path_low) or bool(quarter_path_token and quarter_path_token in path_low)\n            text_matches_q = bool(\n                quarter_caption\n                and re.search(rf"\\b{quarter_caption}\\b[\\s\\S]{{0,80}}?\\b{qd.year}\\b", joined, re.I)\n            )\n            if isinstance(q_raw, date):\n                if q_raw != qd and not path_matches_q:\n                    continue\n            elif not path_matches_q and not text_matches_q:\n                continue\n            monet_match = re.search(\n                r"\\$?\\s*(\\d+(?:\\.\\d+)?)\\s*(?:million|m)\\s+in\\s+45z\\s+production\\s+tax\\s+credit\\s+value\\s+net\\s+of\\s+discounts\\s+and\\s+other\\s+costs",\n                joined,\n                re.I,\n            )\n            if monet_match:\n                amt = float(monet_match.group(1)) * 1_000_000.0\n                period_suffix = " in Q4" if int(quarter_num) == 4 else ""\n                return _cache_45z_note_local({\n                    "text": _ensure_terminal_period(\n                        f"45Z production tax credits contributed {_fmt_short_money_value_local(amt)} net of discounts and other costs{period_suffix}"\n                    ),\n                    "source": {\n                        "source_type": "earnings_release",\n                        "doc": str(path),\n                        "form": "8-K",\n                    },\n                })\n    return _cache_45z_note_local({})\n\ndef _local_slide_45z_realized_text(qd: date) -> str:\n    if not isinstance(qd, date):\n        return ""\n    for path in _slide_text_paths(kind="text", quarter=qd):\n        raw_txt = _read_cached_doc_raw(path)\n        if not raw_txt:\n            continue\n        latest_txt = _extract_45z_realized_progress_text(raw_txt, qd)\n        if latest_txt:\n            return latest_txt\n    return ""'


@dataclass(frozen=True)
class ProfileSignalSupportDeps:
    runtime: MutableMapping[str, Any]


class ProfileSignalSupport:
    def __init__(self, deps: ProfileSignalSupportDeps) -> None:
        self.runtime = deps.runtime
        self._scope: dict[str, Any] | None = None
        self._owned_names: set[str] = set()

    def _base_scope(self) -> dict[str, Any]:
        return {
            "Any": Any,
            "Dict": Dict,
            "Iterable": Iterable,
            "List": List,
            "Mapping": Mapping,
            "MutableMapping": MutableMapping,
            "Optional": Optional,
            "Pattern": Pattern,
            "Tuple": Tuple,
            "Path": Path,
            "date": date,
            "datetime": datetime,
            "hashlib": hashlib,
            "json": json,
            "math": math,
            "os": os,
            "pd": pd,
            "re": re,
        }

    def _ensure_scope(self) -> dict[str, Any]:
        if self._scope is None:
            scope = self._base_scope()
            scope.update(self.runtime)
            scope.setdefault("profile_slide_signals_cache", self.runtime.get("profile_slide_signals_cache"))
            scope.setdefault(
                "profile_slide_signals_by_quarter_cache",
                self.runtime.get("profile_slide_signals_by_quarter_cache"),
            )
            before = set(scope)
            exec(_PROFILE_SIGNAL_SUPPORT_CODE, scope, scope)
            self._scope = scope
            self._owned_names = set(scope) - before
        self._refresh_scope()
        return self._scope

    def _refresh_scope(self) -> None:
        if self._scope is None:
            return
        for key, value in self.runtime.items():
            if key in self._owned_names:
                continue
            self._scope[key] = value

    def _sync_runtime_caches(self) -> None:
        if self._scope is None:
            return
        self.runtime["profile_slide_signals_cache"] = self._scope.get("profile_slide_signals_cache")
        self.runtime["profile_slide_signals_by_quarter_cache"] = self._scope.get(
            "profile_slide_signals_by_quarter_cache"
        )

    def _call(self, name: str, *args: Any, **kwargs: Any) -> Any:
        scope = self._ensure_scope()
        result = scope[name](*args, **kwargs)
        self._sync_runtime_caches()
        return result

    def call_helper(self, name: str, *args: Any, **kwargs: Any) -> Any:
        return self._call(name, *args, **kwargs)

    @property
    def profile_slide_signals_cache(self) -> Any:
        scope = self._ensure_scope()
        return scope.get("profile_slide_signals_cache")

    @property
    def profile_slide_signals_by_quarter_cache(self) -> Any:
        scope = self._ensure_scope()
        return scope.get("profile_slide_signals_by_quarter_cache")

    @property
    def pbi_note_theme_re(self) -> Any:
        return self._ensure_scope()["_pbi_note_theme_re"]

    @property
    def pbi_promise_theme_re(self) -> Any:
        return self._ensure_scope()["_pbi_promise_theme_re"]

    def is_preferred_narrative_source(self, source_type_in: Any) -> bool:
        return bool(self._call("_is_preferred_narrative_source", source_type_in))

    def looks_pbi_fragment_text(self, text_in: Any) -> bool:
        return bool(self._call("_looks_pbi_fragment_text", text_in))

    def is_pbi_clean_sentence(self, text_in: Any) -> bool:
        return bool(self._call("_is_pbi_clean_sentence", text_in))

    def pbi_target_display_ok(self, text_in: Any) -> bool:
        return bool(self._call("_pbi_target_display_ok", text_in))

    def load_profile_slide_signals(self) -> list[dict[str, Any]]:
        return list(self._call("_load_profile_slide_signals"))

    def load_profile_slide_signals_by_quarter(self) -> dict[Any, list[dict[str, Any]]]:
        return dict(self._call("_load_profile_slide_signals_by_quarter"))

    def profile_slide_signals_for_quarter(self, qd: Any) -> list[dict[str, Any]]:
        return list(self._call("_profile_slide_signals_for_quarter", qd))

    def local_slide_driver_fallback(self, qd: Any, driver_kind: str = "") -> str:
        return str(self._call("_local_slide_driver_fallback", qd, driver_kind) or "")

    def pbi_slide_pages_for_qd(self, qd: Any) -> list[dict[str, Any]]:
        return list(self._call("_pbi_slide_pages_for_qd", qd))

    def local_slide_45z_realized_text(self, qd: Any) -> str:
        return str(self._call("_local_slide_45z_realized_text", qd) or "")

    def gpre_official_risk_management_note(self, qd: Any) -> dict[str, Any]:
        return dict(self._call("_gpre_official_risk_management_note_local", qd) or {})

    def gpre_transcript_risk_management_note(self, qd: Any) -> dict[str, Any]:
        return dict(self._call("_gpre_transcript_risk_management_note_local", qd) or {})

    def gpre_official_45z_realized_note(self, qd: Any) -> dict[str, Any]:
        return dict(self._call("_gpre_official_45z_realized_note_local", qd) or {})
